  'CPU':'cpu','CPU性能':'cpu','キャッシュ':'cache','記憶階層':'cache','半導体メモリ':'memorychips','OS':'os','仮想記憶':'os','プロセス状態':'os','割込み':'os','ファイルシステム':'filesystem','RAID':'backup','バックアップ':'backup','信頼性':'reliability','可用性':'reliability',
  'アクセシビリティ':'uiux','画像データ量':'multimedia',
  'SQL':'sql','SQL集約':'sql','GROUP BY':'sql','HAVING':'sql','ORDER BY':'sql','JOIN':'sql','NULL':'sql','主キー':'sql','外部キー':'sql','正規化':'sql','第2正規形':'sql','複合主キー':'sql','インデックス':'sql','トランザクション':'transaction','分離性':'transaction',
  'IPアドレス':'subnet','サブネット':'subnet','プライベートIP':'subnet','デフォルトゲートウェイ':'subnet','IPv6':'subnet','TCP':'tcpudp','TCP/UDP':'tcpudp','DNS':'tcpudp','DHCP':'tcpudp','ARP':'tcpudp','NAT':'tcpudp','NAPT':'tcpudp','ICMP':'tcpudp','HTTP':'tcpudp','HTTPS':'tcpudp','電子メール':'tcpudp','IMAP':'tcpudp','OSI参照モデル':'tcpudp','LANスイッチ':'tcpudp',
  '公開鍵暗号':'crypto','共通鍵暗号':'crypto','ハッシュ':'crypto','HMAC':'crypto','デジタル署名':'signature','デジタル証明書':'signature',
  'システム開発':'development','テスト':'testing','開発モデル':'devmodel','変更管理':'development',
