function automataView(state){
  return `<div class="fsm-wrap"><div class="fsm-row">
    <div class="fsm-state ${state==='A'?'active':''}">状態A</div>
    <div class="fsm-arrow">⇄</div>
    <div class="fsm-state ${state==='B'?'active':''}">状態B</div>
  </div><div class="lesson-copy">入力1：A⇄Bを切替 ／ 入力0：同じ状態を維持</div></div>`;
}
function memoryView(mode){
  const data=[
    ['💨','RAM','揮発性','通常は読書き可'],
    ['📕','ROM','不揮発性','基本は読出し中心'],
    ['⚡','フラッシュ','不揮発性','電気的に書換え可']
  ];
  return `<div class="memory-grid">${data.map((x,i)=>`<div class="mem-card ${mode==='all'||mode===String(i)?'active':''}"><div class="mem-icon">${x[0]}</div><div class="mem-title">${x[1]}</div><div class="mem-props">${mode==='all'||mode===String(i)?`${x[2]}<br>${x[3]}`:'特徴を確認'}</div></div>`).join('')}</div>`;
}
function fileTreeView(active){
  const nodes=[
    ['','/'],
    ['└─ ','home/'],
    ['&nbsp;&nbsp;&nbsp;└─ ','user/'],
    ['&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;└─ ','docs/'],
    ['&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;└─ ','report.pdf']
  ];
  const current=Math.min(active,5);
  return `<div class="file-tree">${nodes.map((x,i)=>`<div class="file-tree-row ${flowState(i,current,5)}">${x[0]}<span class="file-node ${i<=active?'active':''}">${x[1]}</span></div>`).join('')}</div>
    ${current<5?stepPositionNote(`現在：${nodes[current][1]}`, current+1, 5):stepPositionNote('目的のファイルまで到達しました')}
    ${active>=4?'<div class="path-box">/home/user/docs/report.pdf</div>':''}`;
}
