function protocolView(mode){
  const tcp = mode==='tcp'||mode==='both';
  const udp = mode==='udp'||mode==='both';
  const packets=(resend)=>[1,2,3,4].map(n=>{
    if(n===2 && !resend) return `<div class="packet lost">2</div>`;
    if(n===2 && resend) return `<div class="packet resent">2↻</div>`;
    return `<div class="packet ok">${n}</div>`;
  }).join('');
  return `<div class="protocol-grid">
    <div class="protocol-card ${tcp?'active':''}"><b>TCP</b><div class="packet-row">${packets(tcp)}</div><div class="sub">${tcp?'欠落した2を再送して順序をそろえる':'欠落を検出したら再送できる'}</div></div>
    <div class="protocol-card ${udp?'active':''}"><b>UDP</b><div class="packet-row">${packets(false)}</div><div class="sub">${udp?'2が欠けたまま。UDP自体は再送しない':'再送制御を持たない'}</div></div>
  </div>`;
}
