const SUBJECT_A_V136_SPECIFIC_OVERRIDES_4={"coreq_10_01_1":{"choiceExps":["Bは通常byte（バイト）を表す記号で、1秒当たりのbit数という伝送速度の単位ではありません。","dpiはdots per inchの略で、印刷や画像の解像度を表す単位です。通信速度の単位ではありません。","Hzは1秒当たりの周期・振動回数を表す周波数の単位です。1秒当たりに伝送するbit数はbpsで表します。","「bps」が正解です。伝送速度はbps。実効速度は理論最大値より低くなる。"]},"coreq_10_05_1":{"choiceExps":["「192.168.0.0/16」が正解です。192.168.0.0/16。NATとNAPTの違いを理解。","8.8.8.0/24はプライベートアドレス用に予約された範囲ではありません。8.8.8.8などはインターネット上で使われるグローバルアドレスです。","1.1.1.0/24はプライベートIPv4の予約範囲ではなく、インターネット上で使われるグローバルアドレスの範囲です。","224.0.0.0/4はIPv4のマルチキャスト用アドレス範囲です。端末内部ネットワーク用のプライベートアドレス範囲ではありません。"]},"coreq_10_09_1":{"choiceExps":["「CRC」が正解です。CRC：誤りを検出。誤り検出と誤り訂正、再送を区別する。","「DNS」は、ドメイン名とIPアドレスを対応付ける仕組みです。 この問題で求める内容とは一致しない。","「NAT」は、プライベートIPアドレスとグローバルIPアドレスを変換する仕組みです。 この問題で求める内容とは一致しない。","FIFOはFirst In First Outの略で、先に入ったデータを先に取り出す待ち行列の処理順序です。送受信データの誤りを検出する検査方式ではありません。"]},"coreq_10_10_1":{"choiceExps":["「SNMP」が正解です。SNMP（Simple Network Management Protocol）はネットワーク機器の監視・管理で使われる。IPアドレス配布のDHCPと監視用SNMPを区別する。","「SMTP」は、電子メールを送信・転送するためのプロトコルです。 この問題で求める内容とは一致しない。","POPはメールサーバから電子メールを受信するためのプロトコルです。ネットワーク機器の状態監視や管理情報取得を行うSNMPとは用途が異なります。","ARPは同一ネットワーク内でIPv4アドレスから対応するMACアドレスを求める仕組みです。機器の監視・管理プロトコルではありません。"]}};
Object.keys(SUBJECT_A_V136_SPECIFIC_OVERRIDES_4).forEach(qid=>{const q=QUESTION_BANK.find(x=>x.id===qid);if(!q)throw new Error(`v136 missing question: ${qid}`);const patch=SUBJECT_A_V136_SPECIFIC_OVERRIDES_4[qid];const answerBefore=q.a;const idBefore=q.id;Object.assign(q,patch,{qualityAudit:'v136-specific-distractor-pass'});if(q.a!==answerBefore)throw new Error(`v136 answer-index drift: ${qid}`);if(q.id!==idBefore)throw new Error(`v136 id drift: ${qid}`);});
