const CORE_A_CONTEXT_GLOSSARY={"core_06_01":{"プロセス":"OSの文脈では、実行中のプログラムをCPU時間やメモリなどの資源と結び付けて管理する実行単位。"},"core_14_09":{"プロセス":"品質管理の文脈では、入力を成果へ変えるために順序立てて行う一連の活動。レビューやテストなども品質を作り込むプロセスの一部になる。"},"core_15_07":{"プロセス":"サービス改善の文脈では、現状測定・原因分析・改善実施・効果確認などを順につないだ一連の活動。"},"core_15_08":{"プロセス":"サービスマネジメントの文脈では、インシデント管理・問題管理・変更管理など、特定の目的を達成するために定めた一連の活動。"},"core_16_02":{"プロセス":"ここでいうプロセスはOSの実行単位ではなく「業務の流れ」。申請→承認→処理→完了のように、成果を生む複数の作業をつないだもの。","業務プロセス":"受付から完了までのように、業務上の成果を生み出すために人・情報・システム・作業を順につないだ流れ。","As-Is":"現在の業務が実際にどう行われているかを表す現状像。担当者、作業順、待ち時間、二重入力、手戻りなども含めて可視化する。","To-Be":"改善後に実現したい目標の業務像。As-Isで見つけた課題を踏まえ、不要工程の廃止、役割変更、システム化などを設計する。","BPR":"Business Process Re-engineering。既存の手順を少しずつ直すのではなく、業務の目的から考え直してプロセスを抜本的に再設計する考え方。","BPM":"Business Process Management。プロセスを継続的に測定・管理し、改善を繰り返していく考え方。","ボトルネック":"業務全体の処理速度を制限している工程。承認待ちが長い、特定担当者に作業が集中する、といった箇所が例。"},"core_02_06":{"分散":"統計の分散。各データが平均からどれくらい離れているかを2乗して平均した、ばらつきの大きさを表す値。","組合せ":"順番を区別せずに、いくつかを選ぶ場合の数です。n個からk個を選ぶ数は nCk で表します。"},"core_05_02":{"分散":"システム構成での分散。処理や機能、データを複数のコンピュータや場所へ分けて担当させること。","クラスタ":"複数台のコンピュータを連携させ、障害時の切替えや負荷分散などにより可用性・処理能力を高める構成。"},"core_09_08":{"分散":"データベース分野での分散。データや処理を複数のサーバ・拠点へ分けながら、全体として利用できるようにする考え方。"},"core_10_06":{"分散":"DNSなどで、情報や処理を1台へ集中させず複数のサーバへ分けて管理する考え方。"},"core_12_04":{"クラス":"オブジェクト指向で、同じ種類のオブジェクトが持つ属性と処理をまとめた設計図。"},"core_20_03":{"OR":"Operations Research（オペレーションズリサーチ）。数理モデルや最適化手法を使って、経営上の意思決定を支援する考え方。","IE":"Industrial Engineering（経営工学）。人・設備・作業方法・工程を分析し、生産性や効率を改善する考え方。"},"core_04_01":{"CPI":"Cycles Per Instruction。CPUが1命令を実行するのに平均何クロック必要かを表す値です。小さいほど、同じクロック周波数なら命令を多く処理できます。"}};
const CORE_A_GLOSSARY_AUTO_BLOCKLIST=new Set(["プロセス", "分散", "クラス", "クラスタ"]);

function coreGlossaryTermMatches(term,hay){
  if(CORE_A_GLOSSARY_AUTO_BLOCKLIST.has(term))return false;
  if(/^[A-Za-z0-9][A-Za-z0-9+./-]*$/.test(term)){
    const escaped=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    return new RegExp(`(^|[^A-Za-z0-9])${escaped}(?=$|[^A-Za-z0-9])`,'i').test(hay);
  }
  return hay.includes(term);
}
function coreTopicGlossaryDefinition(topicId,term){
  return CORE_A_CONTEXT_GLOSSARY[topicId]?.[term] || CORE_A_BEGINNER_GLOSSARY[term] || '';
}
function coreTopicBeginnerTerms(t){
  const explicit=CORE_A_BEGINNER_TERM_OVERRIDES[t.id]||[];
  const contextual=Object.keys(CORE_A_CONTEXT_GLOSSARY[t.id]||{});
  const e=CORE_A_CONTENT_ENRICHMENT[t.id]||{deep:'',extra:[]};
  const cg=CORE_A_CALC_GUIDES[t.id];
  const cmp=CORE_A_COMPARISON_GUIDES[t.id];
  const extended=[
    t.title,t.lead,...(t.points||[]),...(t.cues||[]),t.example,t.pitfall,
    e.deep,...(e.extra||[]),
    ...(cg?.lines||[]),
    ...((cmp?.rows||[]).flat())
  ].join(' ');
  const auto=Object.keys(CORE_A_BEGINNER_GLOSSARY)
    .filter(term=>term.length>=2 && coreGlossaryTermMatches(term,extended))
    .sort((a,b)=>b.length-a.length);
  const out=[];
  [...explicit,...contextual,...auto].forEach(term=>{
    if(coreTopicGlossaryDefinition(t.id,term)&&!out.includes(term))out.push(term);
  });
  return out.slice(0,16);
}
function coreTopicBeginnerTermView(t){
  const terms=coreTopicBeginnerTerms(t);
  if(!terms.length)return '';
  return `<section class="core-article-section core-beginner-terms">
    <h2>用語</h2>
    <div class="beginner-term-list">${terms.map(term=>`<div class="beginner-term">
      <b>${learningHtml(term)}</b>
      <span>${learningHtml(coreTopicGlossaryDefinition(t.id,term))}</span>
    </div>`).join('')}</div>
  </section>`;
}

const CORE_A_CALC_GUIDES={"core_01_01":{"title":"換算手順","lines":["1byte = 8bit。byte→bitは8倍、bit→byteは8で割る。","通信時間 = データ量(bit) ÷ 通信速度(bit/s)。","例：1MBを10Mbit/sで送る。1MB=8Mbitなので、8÷10=0.8秒。"]},"core_01_03":{"title":"基数変換の手順","lines":["2進数の右端を2^0、その左を2^1、2^2…とする。","bitが1の桁の重みだけを足す。","例：10110₂ = 16+4+2 = 22₁₀。"]},"core_01_04":{"title":"基数変換と計算","lines":["10進数の整数を2進数へ直すときは2で繰り返し割り、余りを下から上へ読む。","2進数と16進数は、整数部を右端から4bitずつ区切って対応させる。","16進数を10進数へ直すときは、右端から16^0、16^1、16^2…の重みを掛けて合計する。","16進数A〜Fは10〜15として計算する。","異なる基数を含む加減算は、いったん10進数へそろえて計算し、最後に指定された基数へ戻す方法でも解ける。","変換後は元の基数へ戻して同じ値になるか確認すると、桁の区切りや重みのミスを見つけやすい。"]},"core_01_05":{"title":"2の補数の作り方","lines":["正の値を指定bit数で表す。","+5を8bitなら00000101。","全bitを反転して11111010。","1を加えて11111011。これが8bitの-5。"]},"core_01_06":{"title":"2進加算","lines":["0+0=0、0+1=1、1+1=10、1+1+1=11。","右端から計算し、2になったら上位桁へ1を繰り上げる。","例：1011+0101=10000。"]},"core_01_07":{"title":"シフトの基本","lines":["左へ1bitの論理シフトは、桁あふれがなければ整数値を2倍する。","右へ1bitの論理シフトは、非負整数なら概ね2で割った商に対応する。","符号付き整数では符号を保つ算術右シフトと区別する。"]},"core_02_06":{"title":"確率・統計の計算","lines":["同様に起こりやすい場合、確率 = 求める場合の数 ÷ 全体の場合の数。","独立な事象A・Bが両方起こる確率は P(A)×P(B)。","『少なくとも1回起こる』は、1－『一度も起こらない確率』で求めると簡単な場合が多い。","n回のうちk回起こる並びの数を数えるときは、組合せ nCk を利用できる。","期待値 = Σ（結果の値×その確率）。","平均 = 値の合計 ÷ 個数。","分散 = 各値と平均との差を2乗した値の平均。標準偏差 = √分散。","相関係数は関係の強さを示すが、値が大きいだけで因果関係を証明したことにはならない。"]},"core_02_07":{"title":"誤差と数値解法","lines":["絶対誤差 = |真値－近似値|。","相対誤差 = 絶対誤差 ÷ |真値|。百分率ならさらに×100する。","相対誤差は、値の大きさが異なる結果同士の誤差を比較するときに使いやすい。","二分法は、根をはさむ区間[a,b]を用意し、中央m=(a+b)/2を求める。","f(m)の符号を調べ、根を含む半分だけを残す操作を繰り返す。","ニュートン法は接線を利用して次の近似値を求める。速く収束することがあるが、初期値によってはうまく収束しない場合がある。","問題で『真値』『近似値』『誤差率』が出たら、数値解法そのものより先に誤差の定義を確認する。"]},"core_02_08":{"title":"情報量","lines":["自己情報量 I = -log₂p。pは事象の発生確率。","確率が小さいほど情報量は大きい。","例：p=1/8なら I=-log₂(1/8)=3bit。"]},"core_04_01":{"title":"CPU性能の計算","lines":["CPU時間 = 命令数 × CPI ÷ クロック周波数。","CPUでのCPIはCycles Per Instructionで、1命令当たりの平均クロック数を表す。","1秒当たり命令数 = クロック周波数 ÷ CPI。","1GHz = 10^9Hzなので、GHzを使う計算では10^9 cycle/sへ直して考える。","MIPS = 1秒当たり命令数 ÷ 10^6。1MIPSは1秒に100万命令。","同じ命令数・同じCPIならクロック周波数が高いほど処理時間は短くなる。","クロック周波数だけで異なるCPUを比較できないのは、命令数やCPIなど他の条件も変わり得るため。"]},"core_05_03":{"title":"性能指標の読み分けと計算","lines":["応答時間（レスポンスタイム）：要求してから最初の応答が返るまで。小さいほどよい。","ターンアラウンドタイム：処理を投入してから処理全体が完了するまで。小さいほどよい。","スループット = 完了した処理件数 ÷ 時間。大きいほどよい。","『正常完了だけを数える』など条件が付く場合は、分子に使う処理件数を問題文どおりに絞る。","分・時間で与えられた時間は、件/秒など求める単位に合わせて秒へ換算してから割る。","性能問題では、まず『時間を問うのか』『単位時間当たりの処理量を問うのか』を見分ける。"]},"core_05_04":{"title":"稼働率の計算","lines":["稼働率 A = MTBF ÷ (MTBF + MTTR)。分母は「稼働時間+修復時間」という1サイクル全体。","例：MTBF=900時間、MTTR=100時間 → A=900÷(900+100)=0.9=90%。","直列構成：A=A₁×A₂。両方が動かないとシステムが動かないため。","並列構成：A=1-(1-A₁)(1-A₂)。「両方とも止まる確率」を1から引く。","例：稼働率0.9の装置2台なら、直列0.81、並列1-(0.1×0.1)=0.99。"]},"core_08_03":{"title":"画像・音声のデータ量","lines":["画像(bit) = 横画素数 × 縦画素数 × 1画素当たりbit数。","音声(bit) = 標本化周波数 × 量子化bit数 × チャネル数 × 秒数。","byteへ直すときは最後に8で割る。圧縮率は非圧縮量を出した後に適用する。"]},"core_10_01":{"title":"伝送時間","lines":["伝送時間(秒) = データ量(bit) ÷ 回線速度(bit/s)。","byteで与えられたデータ量は8倍してbitへそろえる。","実効速度や伝送効率が与えられた場合は、回線速度×効率を実際に使える速度とする。"]},"core_10_04":{"title":"サブネット計算","lines":["/n は先頭n bitがネットワーク部という意味。IPv4は全32bitなのでホスト部は32-n bit。","IPアドレス AND サブネットマスク = ネットワークアドレス。","ホスト部がh bitなら総アドレス数2^h。通常の利用可能ホスト数は2^h-2。","例：/26 → h=6 → 64アドレス、通常62ホスト。"]},"core_14_04":{"title":"クリティカルパスの求め方","lines":["WBSで作業を分解し、各作業の所要時間と前後関係を整理する。","開始から終了まで通り得る経路ごとに、作業時間を合計する。","分岐した作業が並行して進み、後で合流する場合、後続作業は必要な先行作業がすべて終わるまで開始できない。","そのため並列部分では、後続開始を決めるのは通常、完了が遅い側の経路である。","開始から終了までで最も所要時間が長い経路がクリティカルパス。","クリティカルパスの余裕時間は通常0で、その経路上の遅延は全体完了日へ直接影響しやすい。","余裕のある非クリティカル作業は、余裕時間の範囲なら遅れても全体日程へ影響しない場合がある。"]},"core_14_05":{"title":"EVMの基本","lines":["PV：計画上、今までに終えているはずの作業価値。","EV：実際に完了した作業の予算価値。","AC：実際にかかった費用。","SV=EV-PV。負なら予定より遅れ。CV=EV-AC。負なら予算超過。","SPI=EV/PV、CPI=EV/AC。1未満ならそれぞれ進捗・コスト面で不利。"]},"core_20_04":{"title":"損益分岐点","lines":["限界利益率 = 1 - 変動費率。","損益分岐点売上高 = 固定費 ÷ 限界利益率。","例：固定費300万円、変動費率60%なら限界利益率40%。300÷0.4=750万円。"]},"core_20_05":{"title":"財務諸表と財務指標","lines":["B/Sの基本関係：資産 ＝ 負債 ＋ 純資産。","P/L：売上総利益 ＝ 売上高 － 売上原価。","P/L：営業利益 ＝ 売上総利益 － 販売費及び一般管理費。","P/L：経常利益 ＝ 営業利益 ＋ 営業外収益 － 営業外費用。","ROA（%）＝ 利益 ÷ 総資産 × 100。総資産を使ってどれだけ利益を生んだかを見る。","ROE（%）＝ 当期純利益 ÷ 自己資本 × 100。自己資本を使ってどれだけ利益を生んだかを見る。","例：当期純利益80、総資産1000、自己資本400なら、ROA=8%、ROE=20%。","問題文で『営業利益を使う』『期首期末平均の総資産を使う』などの指定があれば、その定義を優先する。"]},"core_20_06":{"title":"減価償却の基本","lines":["定額法では毎期ほぼ同額を費用化する。","単純化した問題では、(取得原価-残存価額)÷耐用年数で年額を求める。","減価償却費を計上しても、そのたびに同額の現金支出が発生するわけではない。"]},"core_02_01":{"title":"集合と論理式の解き方","lines":["A∪B（和集合）は『AまたはB』。少なくとも一方に属する要素を集める。","A∩B（積集合）は『AかつB』。両方に属する要素だけを集める。","補集合は『その集合に属さない』要素を表す。","複数の集合演算では、まず括弧内を処理し、その結果へ次の演算を行う。","NOT(A AND B) = (NOT A) OR (NOT B)。","NOT(A OR B) = (NOT A) AND (NOT B)。","論理式で迷う場合は、A・Bを0/1へ置き換えて真理値表を作ると確認できる。"]},"core_02_02":{"title":"真理値表で確認","lines":["AND：00→0、01→0、10→0、11→1。両方1のときだけ1。","OR：00→0、01→1、10→1、11→1。少なくとも一方が1なら1。","XOR：00→0、01→1、10→1、11→0。入力が異なるとき1。","NANDはANDの反転、NORはORの反転。複合回路は左から中間値を書いて追う。"]},"core_02_03":{"title":"後置記法の読み方","lines":["中置式(A+B)×Cでは、括弧内のA+Bを先に計算する。","後置記法では演算子を対象の後ろへ置くので、A B + C × → AB+C×となる。","後置式の評価は、値をスタックへ積み、演算子が出たら必要な数だけ取り出して計算結果を戻す。"]},"core_03_02":{"title":"計算量の大小","lines":["代表的な増え方は O(1) < O(log n) < O(n) < O(n log n) < O(n²)。","nが2倍になったとき、O(n)は概ね2倍、O(n²)は概ね4倍になる。","二分探索は探索範囲を半分ずつにするためO(log n)。ただし配列が整列済みであることが前提。"]},"core_04_03":{"title":"平均アクセス時間","lines":["単純化した問題では、平均時間 = ヒット率×キャッシュ時間 + ミス率×ミス時時間 と考える。","例：ヒット率90%、ヒット1ns、ミス時に主記憶50nsなら、0.9×1 + 0.1×50 = 5.9ns。","問題文によって『ミス時時間にキャッシュ確認時間を含むか』が異なるので、条件を式にそのまま反映する。"]},"core_07_02":{"title":"標本化と量子化","lines":["標本化周波数fₛは、1秒間に何回測定するかを表す。","標本化定理では、最高周波数fの信号を扱うには原則として2f以上の標本化周波数が必要。","量子化bit数がn bitなら、表現できる段階数は2^n。例：8bitなら256段階。"]},"core_09_03":{"title":"キーと正規化の進め方","lines":["まず『どの列、または列の組合せなら1行を一意に決められるか』を探す。","一意に識別できる最小の組合せが候補キーで、その中から主キーを選ぶ。","一つの列では一意にならず、複数列の組合せで一意にする主キーを複合主キーという。","第1正規形：繰返し項目や一つのセルに複数値を入れる形をなくす。","第2正規形：複合主キーの一部だけに依存する項目（部分関数従属）を別表へ分ける。","第3正規形：主キー以外の項目を経由して決まる項目（推移的関数従属）を別表へ分ける。","『どのキーがどの項目を決めるか』を矢印で書くと、主キー候補と正規化の両方を整理しやすい。"]},"core_09_07":{"title":"SELECT文を組み立てる順序","lines":["まず『どの表から』をFROM、『どの行を対象にするか』をWHEREで決める。","集計するならGROUP BYでグループを作り、COUNT・SUM・AVGなどを使う。","集計後のグループを絞る条件はHAVING。最後に必要な列をSELECTとして確認する。","例：部署別平均給与で平均30万円以上 → GROUP BY 部署、HAVING AVG(給与)>=300000。"]},"core_11_03":{"title":"デジタル署名の流れ","lines":["送信者は元データのハッシュ値を計算し、その値を送信者の秘密鍵で署名する。","受信者は送信者の公開鍵で署名を検証し、自分で計算したハッシュ値と比較する。","一致すれば、改ざんされていないことと署名鍵を持つ者が署名したことを確認できる。","公開鍵が本当に本人のものかは、認証局が発行する電子証明書で確認する。"]},"core_14_06":{"title":"リスク値の考え方","lines":["定量評価の基本は、発生確率×発生時の損失額。","例：発生確率20%、発生時損失500万円なら期待損失は0.2×500=100万円。","期待損失だけでなく、発生した場合に事業継続不能になるような重大リスクは別途優先する場合がある。"]},"core_15_02":{"title":"SLAの可用性を読む","lines":["稼働率99.9%は、停止率0.1%を意味する。","30日を720時間とすると、停止可能時間の目安は720×0.001=0.72時間=43.2分。","SLAでは測定期間、計画停止を含むか、測定地点などの条件も確認する。"]},"core_18_02":{"title":"PPMの4分類","lines":["縦軸に市場成長率、横軸に相対市場シェアを取る。","高成長・高シェア：花形。投資を続け成長を取り込む。","低成長・高シェア：金のなる木。安定した資金創出を期待する。","高成長・低シェア：問題児。投資してシェアを上げるか撤退するかを判断する。","低成長・低シェア：負け犬。縮小・撤退などを検討する。"]},"core_20_03":{"title":"線形計画法の立て方","lines":["何を最大化・最小化したいかを目的関数にする。例：利益=3x+5yを最大化。","材料・時間・予算などの上限を制約条件として不等式で表す。","2変数なら制約を満たす領域を図示し、頂点で目的関数を比較すると最適解を求められる。"]},"core_16_02":{"title":"業務改善の進め方","lines":["1. As-Isを可視化する：担当者、作業順、使用データ、処理時間、待ち時間、手戻りを整理する。","2. 問題を見つける：ボトルネック、重複入力、不要な承認、属人化などを特定する。","3. To-Beを設計する：不要工程を廃止し、役割・順序・情報の流れを見直す。","4. As-IsとTo-Beの差（ギャップ）を整理し、必要な制度変更・教育・システム化を決める。","5. 実行後は処理時間・コスト・ミス率などを測定し、BPMの考え方で改善を続ける。"]},"core_03_03":{"title":"計算量の見方","lines":["O(1)はデータ件数nが増えても処理量がほぼ一定。","O(log n)は探索範囲を半分ずつ減らす処理などで現れ、nが2倍になると処理回数はおおむね1段だけ増える。","O(n)はnに比例、O(n log n)は効率のよい整列でよく現れ、O(n^2)は二重ループなどで現れやすい。","二分探索は整列済みデータが前提で、代表的な比較回数はlog2 nに対応する。","オーダ記法では細かな定数倍より、nが大きくなったときの増え方を比較する。"]},"core_17_01":{"title":"企画から要件定義まで","lines":["1. As-Isとして現状の業務・課題・制約を整理する。","2. To-Beとして達成したい業務成果やあるべき姿を定める。","3. As-IsとTo-Beの差を埋める複数案を比較し、費用対効果・リスク・実現性を評価する。","4. システム化する範囲と方針を決める。","5. 要件定義で機能要件・非機能要件など検証可能な要求へ具体化する。"]}};
function coreTopicCalcGuideView(id){
  const g=CORE_A_CALC_GUIDES[id];if(!g)return '';
  return `<section class="core-article-section core-calc-guide">
    <h2>${escapeHtml(g.title)}</h2>
    <ol>${g.lines.map(x=>`<li>${learningHtml(x)}</li>`).join('')}</ol>
  </section>`;
}

