function coreTopicExamCueView(id){
  const rows=CORE_A_EXAM_CUE_GUIDES[id]||[];
  return `<section class="core-article-section core-exam-cues">
    <h2>問題文の手掛かり</h2>
    <div class="core-cue-grid">
      ${rows.map(row=>`<div class="core-cue-row">
        <div class="core-cue-trigger">${learningHtml(row[0])}</div>
        <div class="core-cue-think">${learningHtml(row[1])}</div>
      </div>`).join('')}
    </div>
  </section>`;
}

function coreTopicComparisonView(id){
  const g=CORE_A_COMPARISON_GUIDES[id];if(!g)return '';
  return `<section class="core-article-section core-compare-guide">
    <h2>比較</h2>
    <div class="core-compare-wrap"><table class="core-compare-table">
      <thead><tr>${g.headers.map(x=>`<th>${escapeHtml(x)}</th>`).join('')}</tr></thead>
      <tbody>${g.rows.map(row=>`<tr>${row.map(x=>`<td>${learningHtml(x)}</td>`).join('')}</tr>`).join('')}</tbody>
    </table></div>
  </section>`;
}

function coreTopicProseParts(id){
  const t=CORE_A_TOPIC_MAP[id];if(!t)return [];
  const e=CORE_A_CONTENT_ENRICHMENT[id]||{};
  const calc=CORE_A_CALC_GUIDES[id]||{};
  const cmp=CORE_A_COMPARISON_GUIDES[id]||{};
  return [
    CORE_A_BEGINNER_OVERVIEWS[id]||'',
    t.lead||'',e.deep||'',t.example||'',CORE_A_CAUTION_GUIDES[id]||t.pitfall||'',
    ...(t.points||[]),
    ...((CORE_A_EXAM_CUE_GUIDES[id]||[]).flat().map(String)),
    ...(e.extra||[]),...(calc.lines||[]),
    ...((cmp.rows||[]).flat().map(String))
  ].filter(Boolean);
}
function coreTopicExplanationVolume(id){
  return coreTopicProseParts(id).reduce((n,x)=>n+String(x).length,0);
}
function coreTopicMaxSentenceLength(id){
  let max=0;
  coreTopicProseParts(id).forEach(text=>{
    String(text).split(/[。！？]/).forEach(sentence=>{
      max=Math.max(max,sentence.trim().length);
    });
  });
  return max;
}
function coreTopicHasTemplatedFiller(id){
  return coreTopicProseParts(id).some(x=>String(x).includes('という関係まで説明できるように整理する'));
}

// ===== v124: Core A prose tone normalization =====
// Natural です・ます調. Formulae, labels, and short non-sentence fragments remain unchanged.
const CORE_A_TONE_EXACT_OVERRIDES={
  'bitとbyte、Bとbの表記を見落とさない':'bitとbyte、Bとbの表記を見落とさないようにします。',
  'プログラミング言語とマークアップ言語・問い合わせ言語を同一視しない':'プログラミング言語とマークアップ言語・問い合わせ言語を同一視しないようにします。',
  'ミドルウェアは利用者が直接操作する画面を持つかどうかだけでは判断しない':'ミドルウェアは利用者が直接操作する画面を持つかどうかだけでは判断しないようにします。',
  '論理回路問題ではゲートごとの出力を左から順に書き込み、最後の出力だけを暗算しない':'論理回路問題ではゲートごとの出力を左から順に書き込み、最後の出力だけを暗算しないようにします。',
  'CREATEとSELECTの役割を同じものとして扱わない':'CREATEとSELECTの役割を同じものとして扱わないようにします。',
  'メール送信と受信で使うプロトコルを混同しない':'メール送信と受信で使うプロトコルを混同しないようにします。',
  '価格だけでベンダを決めない':'価格だけでベンダを決めないようにします。',
  '数量と売上高の公式を取り違えない':'数量と売上高の公式を取り違えないようにします。',
  '単に『セキュリティ事故全般の法律』と覚えない':'単に『セキュリティ事故全般の法律』と覚えないようにします。'
};
function normalizeCorePoliteConnectives(text){
  return String(text??'').replace(/であるが、/g,'ですが、').replace(/だが、/g,'ですが、')
    .replace(/場合があるが、/g,'場合がありますが、').replace(/必要があるが、/g,'必要がありますが、')
    .replace(/できるが、/g,'できますが、').replace(/やすいが、/g,'やすいですが、').replace(/上がるが、/g,'上がりますが、')
    .replace(/られるが、/g,'られますが、').replace(/れるが、/g,'れますが、').replace(/するが、/g,'しますが、').replace(/なるが、/g,'なりますが、');
}
function politeCoreSentence(sentence){
  let src=String(sentence??'').trim();
  if(!src)return '';
  const hadStop=src.endsWith('。');
  let body=hadStop?src.slice(0,-1):src;
  if(CORE_A_TONE_EXACT_OVERRIDES[body])return CORE_A_TONE_EXACT_OVERRIDES[body];
  if(/(?:です|ます|ません|でしょう|ください|しましょう)$/.test(body))return body+'。';

  const fixed=[
    ['とは限らない','とは限りません'],['わけではない','わけではありません'],['ではない','ではありません'],
    ['とはいえない','とはいえません'],['いえない','いえません'],['できない','できません'],
    ['必要がない','必要がありません'],['意味がない','意味がありません'],['値がない','値がありません'],['余裕がない','余裕がありません'],
    ['必要がある','必要があります'],['可能性がある','可能性があります'],['ことがある','ことがあります'],['ことが多い','ことが多いです'],
    ['である','です'],['という','といいます'],['し得る','する場合があります'],['得る','得ます'],
    ['となる','となります'],['になる','になります'],['ある','あります'],['いる','います'],['できる','できます'],
    ['られる','られます'],['れる','れます'],['せる','せます'],['する','します']
  ];
  for(const [from,to] of fixed){if(body.endsWith(from)){body=body.slice(0,-from.length)+to;return body+'。';}}

  const negative=[['しない','しません'],['わない','いません'],['かない','きません'],['さない','しません'],['たない','ちません'],['ばない','びません'],['まない','みません'],['らない','りません']];
  for(const [from,to] of negative){if(body.endsWith(from)){body=body.slice(0,-from.length)+to;return body+'。';}}
  if(body.endsWith('くない'))return body.slice(0,-3)+'くありません。';
  if(body.endsWith('ない'))return body.slice(0,-2)+'ません。';

  const ruGodan=['入る','走る','帰る','切る','知る','要る','減る','滑る','喋る','焦る','限る','握る','参る','混じる','交じる','返る','散る','照る','練る','捻る','蹴る','湿る','茂る','覆る','蘇る','遮る','陥る','至る','渡る','上がる','下がる','変わる','つながる','異なる','決まる','残る','守る','作る','取る','割る','測る','絞る','戻る','終わる','始まる','高まる','分かる','起こる','当たる','かかる','関わる','広がる','下回る','上回る'];
  const oneKanjiIchidanRu=['見る','出る','寝る','着る','似る','煮る','経る','居る','射る'];
  if(body.endsWith('る')){
    if(ruGodan.some(v=>body.endsWith(v)))return body.slice(0,-1)+'ります。';
    if(oneKanjiIchidanRu.some(v=>body.endsWith(v)))return body.slice(0,-1)+'ます。';
    const prev=body.at(-2)||'';
    if('いきぎしじちぢにひびぴみりえけげせぜてでねへべぺめれ'.includes(prev))return body.slice(0,-1)+'ます。';
    return body.slice(0,-1)+'ります。';
  }
  const godan=[['う','います'],['く','きます'],['ぐ','ぎます'],['す','します'],['つ','ちます'],['ぬ','にます'],['ぶ','びます'],['む','みます']];
  for(const [from,to] of godan){if(body.endsWith(from))return body.slice(0,-1)+to+'。';}

  if(body.endsWith('い'))return body+'です。';
  if(body.endsWith('だ'))return body.slice(0,-1)+'です。';
  if(/[ぁ-んァ-ヶ一-龠]$/.test(body))return body+'です。';
  return body+(hadStop?'。':'');
}
function politeCoreProse(text){
  const parts=String(text??'').match(/[^。]+。?/g)||[];
  return normalizeCorePoliteConnectives(parts.map(p=>politeCoreSentence(p)).join(''));
}
function politeCoreCautionSentence(sentence){
  let src=String(sentence??'').trim(); if(!src)return '';
  const hadStop=src.endsWith('。'); const body=hadStop?src.slice(0,-1):src;
  const factualNegative=/(?:とは限らない|わけではない|ではない|とはいえない|いえない|できない|必要がない|意味がない|値がない|余裕がない|にはならない)$/;
  if(body.endsWith('ない')&&!factualNegative.test(body))return normalizeCorePoliteConnectives(body+'ようにします。');
  return politeCoreSentence(src);
}
function politeCoreCautionProse(text){
  const parts=String(text??'').match(/[^。]+。?/g)||[];
  return normalizeCorePoliteConnectives(parts.map(p=>politeCoreCautionSentence(p)).join(''));
}
// ===== v125: Core A readability / redundancy pass =====
// The source curriculum is preserved. These are presentation-only sentence rewrites and curated duplicate-bullet omissions.
const CORE_A_READABILITY_EXACT_OVERRIDES={"オペランドをスタックへ積み、演算子が現れたら必要な数だけ取り出して計算結果を戻す、という手順を理解すると変換問題と評価問題の両方に対応できます。":"スタック評価では、まずオペランドを積みます。演算子が現れたら必要な値を取り出して計算し、結果を戻します。この流れを理解すると、変換問題と評価問題の両方に対応できます。","通常の中置記法では演算子の優先順位や括弧が必要ですが、逆ポーランド記法では演算子を後ろに置くため括弧なしでも計算順序を一意に表せます。":"中置記法では、演算子の優先順位や括弧で計算順序を示します。逆ポーランド記法は演算子を後ろに置くため、括弧なしでも順序を一意に表せます。","AI（Artificial Intelligence：人工知能）は、人間が行う認識・予測・判断などをコンピュータで実現しようとする技術の総称です。":"AI（Artificial Intelligence：人工知能）は、人間の認識・予測・判断などをコンピュータで実現する技術です。幅広い技術を含む総称として使われます。","教師あり学習は正解ラベル付きデータから学び、教師なし学習はラベルなしデータの構造を見つけ、強化学習は行動の結果として得る報酬を手掛かりに学びます。":"教師あり学習は、正解ラベル付きデータから学びます。教師なし学習はラベルなしデータの構造を見つけ、強化学習は報酬を手掛かりに行動を改善します。","教師あり学習は正解付きデータから予測規則を学び、教師なし学習は正解ラベルなしでクラスタなどデータの構造を見つけ、強化学習は報酬を基に行動方策を改善します。":"教師あり学習は正解付きデータから予測規則を学びます。教師なし学習はデータの構造を見つけ、強化学習は報酬を基に行動方策を改善します。","計算量ではO(1)、O(log n)、O(n)、O(n log n)、O(n^2)などを使い、一般に右へ行くほど大規模データで負担が増えます。":"計算量はO(1)、O(log n)、O(n)、O(n log n)、O(n^2)などで表します。一般に後ろのものほど、データ量が増えたときの負担が大きくなります。","CPU（Central Processing Unit：中央処理装置）は、命令を読み取り、計算や制御を行うコンピュータの中心部品です。":"CPU（Central Processing Unit：中央処理装置）は、コンピュータの中心となる部品です。命令を読み取り、計算や制御を行います。","USBは周辺装置接続、HDMIは映像・音声伝送、Bluetoothは近距離無線接続など用途が異なるため、端子名だけでなく何を接続・伝送するかで整理します。":"USBは周辺装置の接続、HDMIは映像・音声の伝送、Bluetoothは近距離無線に使います。名称だけでなく、何を接続・伝送する規格かを区別します。","3層構造ではさらに、画面表示を担当するプレゼンテーション層、業務ロジックを担当するアプリケーション層、データ保存を担当するデータベース層へ分離します。":"3層構造では役割を三つに分けます。画面表示はプレゼンテーション層、業務ロジックはアプリケーション層、データ保存はデータベース層が担当します。","フルバックアップは対象全体、差分バックアップは直近のフル以降の変更分、増分バックアップは直前のバックアップ以降の変更分を保存します。":"フルバックアップは対象全体を保存します。差分は直近のフル以降、増分は直前のバックアップ以降の変更分を保存します。","DRAMは電荷を保持するためリフレッシュが必要で主記憶に広く使われ、SRAMは高速でリフレッシュ不要ですが高価なためキャッシュなどに使われます。":"DRAMはリフレッシュが必要ですが、大容量化しやすく主記憶に広く使われます。SRAMは高速でリフレッシュ不要ですが、高価なため主にキャッシュで使われます。","ROM系は電源を切っても内容を保持する不揮発性メモリで、フラッシュメモリは電気的に書換え可能な不揮発性メモリとしてSSDやUSBメモリなどに使われます。":"ROM系は、電源を切っても内容を保持する不揮発性メモリです。フラッシュメモリは電気的に書き換えられ、SSDやUSBメモリなどに使われます。","UIでは利用者の入力に対して『受け付けた』『処理中』『完了した』『失敗した』など状態を返すフィードバックが、誤操作防止と安心感につながります。":"UIでは、操作を受け付けたか、処理中か、完了・失敗したかを利用者へ返します。こうしたフィードバックは、誤操作や戸惑いを減らします。","ユーザビリティは特定の利用者が目的を効率よく満足して達成できるか、アクセシビリティは障害・年齢・環境などにかかわらず利用できるかという観点です。":"ユーザビリティは、対象の利用者が目的を効率よく達成できるかを見る観点です。アクセシビリティは、障害・年齢・利用環境などにかかわらず利用できるかを見ます。","個別ファイルを各部門で別々に持つ方式では、重複や不整合、アクセス制御のばらつきが起きやすいため、DBMSで一元的に管理する利点があります。":"部門ごとに個別ファイルを持つと、重複や不整合、アクセス制御のばらつきが起きやすくなります。DBMSで一元管理すると、これらを抑えやすくなります。","DBMS（Database Management System：データベース管理システム）は、データベースを安全・効率的に利用するためのソフトウェアです。":"DBMS（Database Management System：データベース管理システム）は、データベースを管理するソフトウェアです。安全で効率的な利用を支えます。","データ定義、検索・更新、アクセス制御、同時実行制御、障害回復、バックアップなどを担い、アプリが記憶装置の細かな実装を直接意識しなくてもよいようにします。":"DBMSは、データ定義、検索・更新、アクセス制御、同時実行制御、障害回復、バックアップなどを担います。アプリは記憶装置の細かな実装を直接意識せずにデータを扱えます。","原子性は全部成功か全部失敗、整合性はルールを壊さない、独立性は同時実行が互いへ不適切に影響しない、耐久性はCOMMIT後の結果が障害でも保持されることを表します。":"ACIDの4特性を分けて覚えます。原子性は「全部成功か全部失敗」、整合性は「ルールを守る」、独立性は「同時実行が互いに不適切な影響を与えない」、耐久性は「COMMIT後の結果を保持する」です。","データベース応用では、日々の更新を扱うOLTP、大量データを分析するOLAP、データウェアハウス、NoSQLなど、目的に応じた使い分けを学びます。":"データベースには、日々の更新を扱うOLTPや大量データを分析するOLAPがあります。データウェアハウスやNoSQLも、目的に応じて使い分けます。","L2スイッチは主にMACアドレスを使って同一LAN内のフレームを転送し、ルータはIPアドレスを使って異なるネットワーク間のパケットを中継します。":"L2スイッチは主にMACアドレスを見て、同一LAN内のフレームを転送します。ルータはIPアドレスを見て、異なるネットワーク間のパケットを中継します。","IPアドレスはネットワーク部とホスト部に分かれ、どこまでがネットワーク部かはサブネットマスクやプレフィックス長と組み合わせて判断します。":"IPアドレスは、ネットワーク部とホスト部に分かれます。境界はサブネットマスクやプレフィックス長で判断します。","グローバルIPアドレスはインターネット上で重複しない住所、プライベートIPアドレスは家庭や社内など閉じたネットワーク内で使う住所です。":"グローバルIPアドレスは、インターネット上で一意に使う住所です。プライベートIPアドレスは、家庭や社内などの内部ネットワークで使います。","WebではHTTP/HTTPS、メール送信ではSMTP、メール受信ではPOP3/IMAP、ファイル転送ではFTP/SFTPなどが使われます。":"WebではHTTP/HTTPSを使います。メール送信はSMTP、受信はPOP3/IMAP、ファイル転送はFTP/SFTPなどを使います。","マルウェアは不正な動作を行うソフトウェアの総称で、ウイルスは他のファイル等へ寄生して広がり、ワームは自らネットワーク経由で広がる性質を持ちます。":"マルウェアは、不正な動作を行うソフトウェアの総称です。ウイルスは他のファイルなどへ寄生して広がり、ワームは自らネットワーク経由で広がります。","Web攻撃では、SQLインジェクションはSQL文へ不正入力を混ぜる攻撃、XSSはブラウザで不正スクリプトを実行させる攻撃として、狙う場所を区別します。":"SQLインジェクションは、SQL文へ不正な入力を混ぜる攻撃です。XSSは、ブラウザで不正なスクリプトを実行させます。攻撃対象の違いを区別します。","HTTPSで用いるTLSでは、公開鍵技術を使ってサーバ認証や鍵合意を行い、確立したセッションでは共通鍵暗号で効率よく通信データを保護します。":"HTTPSで使うTLSは、公開鍵技術でサーバ認証や鍵合意を行います。その後の通信は、共通鍵暗号を使って効率よく保護します。","ファイアウォールは主にネットワーク層・トランスポート層の条件で通信を制御し、WAFはHTTPリクエストなどWebアプリ層を検査します。":"ファイアウォールは、主にIPアドレスやポートなどを基に通信を制御します。WAFはHTTPリクエストなど、Webアプリへの通信内容を検査します。","機能要件は検索・登録・計算など『何をするか』、非機能要件は応答時間、可用性、セキュリティ、操作性など『どの程度の品質で動くか』を表します。":"機能要件は、検索・登録・計算など「何をするか」を表します。非機能要件は、応答時間・可用性・セキュリティ・操作性など「どの程度の品質で動くか」を表します。","外部設計は利用者から見える画面・帳票・外部インタフェースなどを具体化し、内部設計はプログラムやデータ構造など実装側の詳細を決める、という整理が基本です。":"外部設計では、画面・帳票・外部インタフェースなど利用者から見える仕様を具体化します。内部設計では、プログラム構造やデータ構造など実装側の詳細を決めます。","外部設計は画面・帳票・外部インタフェースなど利用者から見える仕様を中心に決め、内部設計はモジュール構造や内部データなど実装に近い詳細を決めます。":"外部設計は、利用者から見える仕様を中心に決めます。内部設計は、モジュール構造や内部データなど実装に近い詳細を決めます。","単体テストは部品単位、結合テストは部品間の連携、システムテストはシステム全体の要件、受入れ・運用テストは利用者業務の観点で確認します。":"単体テストは部品単位、結合テストは部品間の連携を確認します。システムテストは全体の要件、受入れテストは利用者業務の観点で確認します。","ブラックボックステストは内部構造を意識せず入力と出力から確認し、ホワイトボックステストは命令や分岐など内部構造の実行状況を確認します。":"ブラックボックステストは、内部構造を見ずに入力と出力から確認します。ホワイトボックステストは、命令や分岐など内部構造の実行状況を確認します。","保守には、障害を直す是正保守、環境変化へ対応する適応保守、性能や使いやすさを改善する完全化保守、将来の障害を防ぐ予防保守などがあります。":"保守は目的によって分類します。障害を直す是正保守、環境変化へ対応する適応保守、性能などを改善する完全化保守、将来の障害を防ぐ予防保守があります。","構成管理ではソース、設定、ライブラリ、文書などを構成アイテムとして識別し、どの版の組合せが製品を構成したかを追跡できるようにします。":"構成管理では、ソース・設定・ライブラリ・文書などを構成アイテムとして識別します。どの版の組合せで製品を作ったか追跡できるようにします。","経営層には意思決定に必要な要約、開発者には詳細な作業情報、利用者には変更点や利用方法など、相手に合わせて内容・頻度・媒体を設計します。":"伝える情報は相手に合わせます。経営層には意思決定用の要約、開発者には詳細な作業情報、利用者には変更点や利用方法などを伝えます。","サービスデスクは利用者との単一窓口として、問い合わせ・障害報告・サービス要求を受け付け、記録・分類・一次対応・エスカレーションを行います。":"サービスデスクは、利用者との単一窓口です。問い合わせ・障害報告・サービス要求を受け付け、記録・分類・一次対応・エスカレーションを行います。","サーバやネットワーク機器が正常でも、停電、過熱、浸水、火災などでサービスは停止するため、UPS、非常用電源、温湿度管理、入退室管理などを組み合わせます。":"サーバやネットワーク機器が正常でも、停電・過熱・浸水・火災などでサービスは止まります。そのため、UPS、非常用電源、温湿度管理、入退室管理などを組み合わせます。","システム監査では、監査目的・範囲・方法を計画し、ログ・承認記録・設定情報・聞き取りなどから監査証拠を集め、基準に照らして評価します。":"システム監査では、まず目的・範囲・方法を計画します。ログ・承認記録・設定情報・聞き取りなどから監査証拠を集め、基準に照らして評価します。","ソリューションビジネスは、製品単体を売るだけでなく、顧客の課題を解決するために複数の製品やサービスを組み合わせて提供する考え方です。":"ソリューションビジネスは、顧客の課題解決を目的に製品やサービスを組み合わせて提供します。単体製品の販売だけを目的としません。","ソリューションビジネスは製品そのものではなく顧客の業務課題を出発点にし、分析、システム、クラウド、教育、運用支援などを組み合わせて解決します。":"ソリューションビジネスは、顧客の業務課題を出発点にします。分析・システム・クラウド・教育・運用支援などを組み合わせて解決します。","SWOT分析は内部環境のStrengths・Weaknessesと外部環境のOpportunities・Threatsを整理します。":"SWOT分析は、内部環境のStrengths（強み）・Weaknesses（弱み）と、外部環境のOpportunities（機会）・Threats（脅威）を分けて整理します。","低コスト、差別化、特定市場への集中など、顧客へどんな価値を提供するかを明確にし、その方針に合わせて製品・価格・販売・業務能力を整えます。":"低コスト・差別化・特定市場への集中など、顧客へ提供する価値を明確にします。その方針に合わせて、製品・価格・販売・業務能力を整えます。","マーケティングでは、市場をセグメントに分け、狙う顧客をターゲットとして選び、自社製品をどう認識してもらうかポジショニングを考えます。":"マーケティングでは、市場を分けて狙う顧客を選びます。その上で、競合と比べて自社製品をどう位置付けるかを考えます。","STPはSegmentationで市場を分け、Targetingで狙う顧客層を決め、Positioningで競合と比べた自社の立ち位置を定めます。":"STPは三つの段階で考えます。Segmentationで市場を分け、Targetingで狙う顧客層を決め、Positioningで競合と比べた立ち位置を定めます。","技術開発戦略では、どの技術領域へ研究開発資源を重点配分するかを、顧客価値、競争優位、自社能力、必要投資、回収可能性などから判断します。":"技術開発戦略では、研究開発資源をどの技術領域へ配分するか決めます。顧客価値・競争優位・自社能力・必要投資・回収可能性などを基に判断します。","組込みシステムは機器の中へ組み込まれ、限られたCPU・メモリ・電力で決められた機能を実行するため、リアルタイム性や信頼性が重要になります。":"組込みシステムは、限られたCPU・メモリ・電力で決められた機能を実行します。そのため、リアルタイム性や信頼性が重要です。","OR（Operations Research）とIE（Industrial Engineering）は、データや数理的手法を使って業務を効率化する考え方です。":"OR（Operations Research）とIE（Industrial Engineering）は、業務改善に数理的手法を使う分野です。データを基に、最適化や作業改善を考えます。","販売数量で損益分岐点を求める場合、1個当たり限界利益=販売価格－1個当たり変動費を求め、固定費÷1個当たり限界利益で数量を求めます。":"販売数量の損益分岐点では、まず1個当たり限界利益を求めます。販売価格－1個当たり変動費で計算し、固定費をその値で割ります。","固定資産は建物・設備など長期利用する資産、棚卸資産は商品・製品・原材料など販売や生産のための在庫、無形資産はソフトウェアなど形を持たない資産です。":"固定資産は、建物・設備など長期利用する資産です。棚卸資産は商品・製品・原材料などの在庫、無形資産はソフトウェアなど形を持たない資産です。","試験では「何を保護したいのか」を先に見抜くのがコツで、技術的発明、物品等のデザイン、名称・ロゴ、プログラムや文章をそれぞれ別の権利へ対応させます。":"知的財産権の問題では、まず「何を保護したいのか」を確認します。発明、デザイン、名称・ロゴ、プログラムや文章を、それぞれ対応する権利へ結び付けます。","産業財産権では、特許権は発明、実用新案権は物品の形状・構造などの考案、意匠権はデザイン、商標権は商品・サービスを識別する標章を保護します。":"産業財産権は保護対象で区別します。特許権は発明、実用新案権は物品の形状・構造などの考案、意匠権はデザイン、商標権は商品・サービスを識別する標章を保護します。","同じ製品でも、技術は特許、外観は意匠、名称・ロゴは商標、説明書やプログラムの創作的表現は著作権というように複数の権利が別々に関係します。":"一つの製品に複数の権利が関係する場合があります。技術は特許、外観は意匠、名称・ロゴは商標、説明書やプログラムの創作的表現は著作権で保護されます。","ソフトウェアの作成を中小受託事業者へ委託する場面では、契約関係だけでなく、情報成果物の委託として取引適正化に関するルールが関係する場合があります。":"ソフトウェア作成を外部へ委託するときは、契約関係だけでなく取引適正化のルールも確認します。情報成果物の委託として対象になる場合があります。","逆変換では整数部と小数部で手順が異なる点も重要です。":"逆変換では、整数部と小数部で手順が異なります。","ド・モルガンの法則は否定がANDとORを入れ替える点が重要です。":"ド・モルガンの法則では、否定するとANDとORが入れ替わります。","版管理は開発ツールとは別に構成管理の観点でも重要です。":"版管理は、構成管理でも扱います。","入力に対して結果が分かるフィードバックが重要です。":"操作後は、結果が分かるフィードバックを返します。","銀行振込の「引き落とし」と「入金」のように、途中だけ成功すると困る処理で重要です。":"銀行振込の「引き落とし」と「入金」は、トランザクションの典型例です。途中だけ成功すると整合性が崩れます。","トランザクションではACID特性が重要です。":"トランザクションは、ACIDの4特性で整理します。","単一対策に依存せず、多層防御にすることが重要です。":"単一の対策に頼らず、複数の対策を重ねます。","各工程の成果物は次工程の入力となり、要件とテスト結果を追跡できることが重要です。":"各工程の成果物は、次工程の入力になります。要件からテスト結果まで追跡できるようにします。","要望をそのまま列挙するのではなく、目的・制約・優先順位を整理し、後で検証できる表現にすることが重要です。":"要望はそのまま列挙せず、目的・制約・優先順位を整理します。後で検証できる表現に具体化します。","差を把握・管理し、再現可能にすることが重要です。":"環境差を把握・管理し、再現できる状態にします。","自社開発物と第三者著作物の権利関係を記録しておくことが重要です。":"自社開発物と第三者著作物の権利関係を記録します。","特定の人へ作業が集中すると遅延や品質低下の原因になるため、負荷の平準化も重要です。":"特定の人へ作業が集中すると、遅延や品質低下につながります。作業負荷を平準化します。","進捗と費用を一緒に見るEVMも重要です。":"EVMでは、進捗と費用を同じ基準で確認します。","完成後に検査するだけでなく、最初から品質を作り込むための手順やレビューも重要です。":"品質は完成後の検査だけで確保するものではありません。手順やレビューで、開発途中から作り込みます。","手戻りを減らすには完成後の検査だけでなく、レビューなど上流での予防が重要です。":"手戻りを減らすには、レビューなど上流工程で不具合を予防します。","目標を定めるだけでなく、実績との差を確認し、必要ならサービス改善へつなげるところまでが重要です。":"サービス水準は、目標を決めて終わりではありません。実績との差を確認し、必要なら改善します。","設備対策は『停止させない』だけでなく、事故時に安全に停止・復旧できることも重要です。":"設備対策では、停止を防ぐだけでなく、事故時に安全に停止・復旧できるようにします。","指標を集めるだけでなく、意思決定へつなげることが重要です。":"指標は集めるだけで終わらせず、改善の判断に使います。","経営目標とIT施策が結び付いていることが重要です。":"IT施策は、経営目標と結び付けて考えます。","『何のために導入するか』を曖昧にしたまま製品選定へ進まないことが重要です。":"製品を選ぶ前に、「何のために導入するか」を明確にします。","略語と対象業務を対応させることが重要です。":"略語は、対象となる業務と結び付けて覚えます。","マトリックス組織は複数の指揮系統を持つため調整が重要です。":"マトリックス組織は複数の指揮系統を持つため、部門間の調整が必要です。","営業秘密として保護するには、秘密として管理されていること、事業に有用であること、一般に知られていないことが重要です。":"営業秘密として保護されるには、秘密管理性・有用性・非公知性の要件を満たす必要があります。","契約名だけでなく、実際の指揮命令関係や取引内容を見ることが重要です。":"契約名だけでなく、実際の指揮命令関係や取引内容を確認します。","契約書の名称だけでなく実態で判断する点が重要です。":"契約書の名称だけでなく、実際の働き方や責任関係で判断します。","DBMS（Database Management System：データベース管理システム）は、データベースを管理するソフトウェアです。":"DBMSは、データベースを管理するソフトウェアです。正式名称はDatabase Management System（データベース管理システム）です。","原子性は「全部成功か全部失敗」、整合性は「ルールを守る」、独立性は「同時実行が互いに不適切な影響を与えない」、耐久性は「COMMIT後の結果を保持する」です。":"原子性は「全部成功か全部失敗」、整合性は「ルールを守る」です。独立性は「同時実行が互いに不適切な影響を与えない」、耐久性は「COMMIT後の結果を保持する」です。","SWOT分析は、内部環境のStrengths（強み）・Weaknesses（弱み）と、外部環境のOpportunities（機会）・Threats（脅威）を分けて整理します。":"SWOT分析は、内部環境と外部環境を分けて見ます。内部環境はStrengths（強み）・Weaknesses（弱み）、外部環境はOpportunities（機会）・Threats（脅威）です。","Segmentationで市場を分け、Targetingで狙う顧客層を決め、Positioningで競合と比べた立ち位置を定めます。":"Segmentationで市場を分け、Targetingで狙う顧客層を決めます。Positioningで競合と比べた立ち位置を定めます。","OR（Operations Research）とIE（Industrial Engineering）は、業務改善に数理的手法を使う分野です。":"ORはOperations Research、IEはIndustrial Engineeringの略です。どちらも数理的手法を使って業務改善を考える分野です。","内部環境はStrengths（強み）・Weaknesses（弱み）、外部環境はOpportunities（機会）・Threats（脅威）です。":"内部環境はStrengths（強み）とWeaknesses（弱み）です。外部環境はOpportunities（機会）とThreats（脅威）です。"};
const CORE_A_REDUNDANT_EXTRA_INDEXES={"core_01_05":[0],"core_02_05":[2],"core_02_08":[0],"core_05_04":[0],"core_06_03":[2],"core_06_04":[0],"core_09_02":[2],"core_09_05":[0],"core_11_04":[0],"core_12_02":[0],"core_12_03":[2],"core_12_05":[2],"core_13_01":[2],"core_14_02":[0],"core_14_07":[2],"core_15_03":[2],"core_16_03":[2],"core_19_02":[0],"core_19_03":[2],"core_21_01":[1],"core_21_03":[0]};
function readableCoreProse(text){
  let out=politeCoreProse(text);
  for(const [from,to] of Object.entries(CORE_A_READABILITY_EXACT_OVERRIDES)) out=out.split(from).join(to);
  return out;
}
function readableCoreCautionProse(text){
  let out=politeCoreCautionProse(text);
  for(const [from,to] of Object.entries(CORE_A_READABILITY_EXACT_OVERRIDES)) out=out.split(from).join(to);
  return out;
}
function readableCoreExtras(id,items){
  const hidden=new Set(CORE_A_REDUNDANT_EXTRA_INDEXES[id]||[]);
  return (items||[]).filter((_x,i)=>!hidden.has(i));
}
function politeCoreHtml(text){return learningHtml(readableCoreProse(text));}
function politeCoreCautionHtml(text){return learningHtml(readableCoreCautionProse(text));}


