const B_COMPOUND_SECONDS=20*60;
const B_COMPOUND_SETS=[{"id":"sales_filter","level":"標準","title":"売上データの集計","lead":"日別売上から基準以上の値だけを集計し、最大値と平均も求めます。","code":["sales ← [42, 18, 55, 31, 67]","limit ← 40","sum ← 0","count ← 0","max ← sales[0]","for i ← 0 to 4","    if sales[i] ≥ limit","        sum ← sum + sales[i]","        count ← count + 1","    endif","    if sales[i] > max","        max ← sales[i]","    endif","endfor","avg ← sum / count","sum, count, max, avg を出力する"],"data":[{"label":"注意","text":"添字は0から始まり、avgは条件を満たした売上だけの平均です。"}],"qs":[{"q":"i=2 の処理がすべて終わった直後、sum と count の組合せは？","opts":["sum=42, count=1","sum=115, count=3","sum=55, count=1","sum=97, count=2"],"a":3,"exp":"42と55が基準40以上です。18は対象外なので、i=2終了時点でsum=97、count=2です。"},{"q":"ループ終了後の max は？","opts":["55","67","97","213"],"a":1,"exp":"配列の最大値67までmaxが更新されます。"},{"q":"最後に出力される avg は？","opts":["54.67","41.4","53.25","71.0"],"a":0,"exp":"対象は42,55,67で合計164、個数3なので164÷3≒54.67です。"}]},{"id":"matrix_threshold","level":"応用","title":"二次元配列のしきい値判定","lead":"2×3行列を行優先で走査し、50以上の要素数と位置スコアを求めます。","code":["m ← [[20, 60, 45], [80, 30, 70]]","count ← 0","score ← 0","for r ← 0 to 1","    for c ← 0 to 2","        if m[r][c] ≥ 50","            count ← count + 1","            score ← score + r + c","        endif","    endfor","endfor","count, score を出力する"],"data":[{"label":"走査順","text":"(0,0)→(0,1)→(0,2)→(1,0)→(1,1)→(1,2)"}],"qs":[{"q":"(0,1) の要素60を処理した直後、count と score は？","opts":["count=0, score=0","count=1, score=60","count=2, score=1","count=1, score=1"],"a":3,"exp":"60は50以上なのでcount=1、scoreには0+1=1が加わります。"},{"q":"すべての走査終了後、count は？","opts":["2","4","3","6"],"a":2,"exp":"50以上なのは60,80,70の3要素です。"},{"q":"すべての走査終了後、score は？","opts":["3","5","4","6"],"a":1,"exp":"対象位置(0,1),(1,0),(1,2)のr+cは1,1,3で、合計5です。"}]},{"id":"queue_service","level":"標準","title":"受付キューの処理","lead":"受付番号をFIFOのキューで処理し、途中で新しい受付を追加します。","code":["q ← [101, 102, 103]","x ← DEQUEUE(q)","ENQUEUE(q, 104)","y ← DEQUEUE(q)","ENQUEUE(q, 105)","z ← DEQUEUE(q)","q, x, y, z を出力する"],"data":[{"label":"FIFO","text":"DEQUEUEは先頭から、ENQUEUEは末尾へ追加します。"}],"qs":[{"q":"ENQUEUE(q,104) を実行した直後の q は？","opts":["[101,102,103,104]","[102,103,104]","[104,102,103]","[102,104]"],"a":1,"exp":"101を取り出した後の[102,103]へ104を追加するので[102,103,104]です。"},{"q":"y に代入される値は？","opts":["101","103","104","102"],"a":3,"exp":"次の先頭は102なのでy=102です。"},{"q":"最後に出力される q は？","opts":["[104,105]","[103,104,105]","[105]","[]"],"a":0,"exp":"101,102,103が順に取り出され、104,105が残ります。"}]},{"id":"linked_rank","level":"応用","title":"連結リストの条件付き集計","lead":"単方向リストを先頭からたどり、valueが10以上のノードだけ集計します。","code":["A(value=8,next=B)","B(value=14,next=C)","C(value=11,next=D)","D(value=5,next=null)","p ← A","count ← 0","sum ← 0","while p ≠ null","    if p.value ≥ 10","        count ← count + 1","        sum ← sum + p.value","    endif","    p ← p.next","endwhile","count, sum を出力する"],"data":[{"label":"リスト","text":"A(8) → B(14) → C(11) → D(5) → null"}],"qs":[{"q":"Bを処理し終えた直後、count と sum は？","opts":["count=0, sum=0","count=2, sum=22","count=1, sum=8","count=1, sum=14"],"a":3,"exp":"A=8は条件外で、B=14で初めてcount=1、sum=14です。"},{"q":"Cを処理し終えた直後の sum は？","opts":["14","25","19","33"],"a":1,"exp":"Bの14とCの11を足して25です。"},{"q":"最終的に出力される count は？","opts":["2","1","3","4"],"a":0,"exp":"10以上なのはBとCの2ノードです。"}]},{"id":"binary_count","level":"応用","title":"二分探索の比較回数","lead":"昇順配列から目的値を探しながら、比較回数も数えます。","code":["data ← [3, 7, 12, 18, 25, 31, 40, 52]","target ← 31","low ← 0","high ← 7","count ← 0","while low ≤ high","    mid ← (low + high) div 2","    count ← count + 1","    if data[mid] = target","        pos ← mid","        break","    elseif data[mid] < target","        low ← mid + 1","    else","        high ← mid - 1","    endif","endwhile","pos, count を出力する"],"data":[{"label":"div","text":"整数除算で小数点以下を切り捨てます。"}],"qs":[{"q":"最初の mid は？","opts":["2","4","5","3"],"a":3,"exp":"(0+7) div 2=3です。"},{"q":"最初の比較後、low はいくつに更新される？","opts":["3","4","5","6"],"a":1,"exp":"data[3]=18は31より小さいのでlow=mid+1=4です。"},{"q":"最終的な pos と count の組合せは？","opts":["pos=5, count=3","pos=5, count=2","pos=6, count=2","pos=6, count=3"],"a":1,"exp":"mid=3の18、次にmid=5の31を比較して見つかるのでpos=5、count=2です。"}]},{"id":"recursive_sum","level":"標準","title":"再帰による合計","lead":"1からnまでの合計を再帰で求め、戻り値が合成される流れを読み取ります。","code":["function total(n)","    if n = 1","        return 1","    endif","    return n + total(n - 1)","endfunction","x ← total(4)","x を出力する"],"data":[{"label":"呼出し","text":"total(4) → total(3) → total(2) → total(1)"}],"qs":[{"q":"total(1) の戻り値は？","opts":["0","2","1","4"],"a":2,"exp":"終了条件n=1に一致するので1を返します。"},{"q":"total(3) の戻り値は？","opts":["3","5","6","7"],"a":2,"exp":"3+(2+1)=6です。"},{"q":"最後に x に入る値は？","opts":["6","8","24","10"],"a":3,"exp":"4+3+2+1=10です。"}]},{"id":"insertion_pass","level":"標準","title":"挿入ソートの途中状態","lead":"未整列の要素keyを、整列済み部分の適切な位置へ挿入します。空欄補充と途中配列をまとめて読みます。","code":["data ← [7, 3, 5, 2]","for i ← 1 to 3","    key ← data[i]","    j ← i - 1","    while j ≥ 0 and data[j] > key","        data[j+1] ← data[j]","        j ← j - 1","    endwhile","    [A]","endfor","data を出力する"],"data":[{"label":"空欄[A]","text":"keyを空いた位置へ戻す処理が入ります。"}],"qs":[{"kind":"空欄補充","q":"空欄[A]に入る処理として適切なのは？","opts":["data[j] ← key","key ← data[j+1]","data[i] ← j","data[j+1] ← key"],"a":3,"exp":"whileで大きい要素を右へずらした後、空いた位置j+1へkeyを入れます。"},{"kind":"トレース","q":"i=1 の処理が終わった直後の data は？","opts":["[7,3,5,2]","[3,5,7,2]","[3,7,5,2]","[2,3,5,7]"],"a":2,"exp":"key=3、7を右へずらして3を先頭へ入れるので[3,7,5,2]です。"},{"kind":"変更予測","q":"外側ループを i=1 to 2 に変更した場合、終了時の data は？","opts":["[2,3,5,7]","[3,5,7,2]","[3,7,5,2]","[3,5,2,7]"],"a":1,"exp":"i=1で[3,7,5,2]、i=2で5を挿入して[3,5,7,2]となり、i=3は実行しません。"}]},{"id":"postfix_stack","level":"応用","title":"逆ポーランド記法の評価","lead":"数値はスタックへ積み、演算子が現れたら2値を取り出して計算結果を積みます。","code":["tokens ← [3, 4, +, 2, ×]","stack ← 空","for token in tokens","    if token が数値","        PUSH(stack, token)","    else","        b ← POP(stack)","        a ← POP(stack)","        PUSH(stack, a token b)","    endif","endfor","result ← POP(stack)","result を出力する"],"data":[{"label":"演算順","text":"3 4 + 2 × は (3+4)×2 を表します。"}],"qs":[{"kind":"トレース","q":"+ を処理し終えた直後の stack は？","opts":["[7]","[3,4]","[4,3]","[12]"],"a":0,"exp":"3と4をPOPして加算し、7をPUSHするのでstack=[7]です。"},{"kind":"空欄補充","q":"演算子処理で a と b を取り出す順序が必要な主な理由は？","opts":["スタックでは加算できないため","PUSHは1回しかできないため","減算や除算では順序で結果が変わるため","数値を昇順にするため"],"a":2,"exp":"a-bやa÷bではオペランド順が重要なので、先に取り出した値をb、次をaとして扱います。"},{"kind":"トレース","q":"最後の result は？","opts":["9","12","14","18"],"a":2,"exp":"3+4=7、その後7×2=14です。"}]},{"id":"bfs_queue","level":"応用","title":"幅優先探索とキュー","lead":"グラフを幅優先にたどり、発見した頂点をキューへ追加します。","code":["adj[A] ← [B,C]","adj[B] ← [D]","adj[C] ← [E]","adj[D] ← []","adj[E] ← []","q ← [A]","visited[A] ← true","while q が空でない","    v ← DEQUEUE(q)","    v を出力","    for each u in adj[v]","        if visited[u] = false","            [A]","            ENQUEUE(q,u)","        endif","    endfor","endwhile"],"data":[{"label":"前提","text":"隣接リストは表示順に処理し、A以外のvisited初期値はfalseです。"}],"qs":[{"kind":"空欄補充","q":"同じ頂点を何度もキューへ入れないため、空欄[A]に入れる処理は？","opts":["visited[u] ← true","visited[v] ← false","q ← 空","u ← v"],"a":0,"exp":"uをキューへ追加する時点でvisited[u]=trueにして重複追加を防ぎます。"},{"kind":"トレース","q":"Aを処理し終えた直後の q は？","opts":["[A,B,C]","[B,C]","[C,B]","[B]"],"a":1,"exp":"Aを取り出した後、B、Cを順に追加するので[B,C]です。"},{"kind":"処理理解","q":"このコードの出力順として正しいものは？","opts":["A,B,D,C,E","A,B,C,D,E","A,C,E,B,D","D,B,E,C,A"],"a":1,"exp":"幅優先探索なので距離1のB,Cを先に処理し、その後D,Eへ進みます。"}]},{"id":"bit_permission","level":"標準","title":"権限ビットの操作","lead":"ビットマスクのANDで権限を確認し、ORで新しい権限を追加します。","code":["perm ← 1001₂","writeMask ← 0100₂","adminMask ← 1000₂","if (perm AND writeMask) ≠ 0000₂","    canWrite ← true","else","    canWrite ← false","endif","[A]","perm を出力する"],"data":[{"label":"ビット","text":"上位から admin / write / read / guest とします。"}],"qs":[{"kind":"トレース","q":"初期状態で canWrite は？","opts":["false","true","未定義","adminと同じ"],"a":0,"exp":"1001 AND 0100 = 0000なのでwriteビットは立っておらずfalseです。"},{"kind":"空欄補充","q":"write権限を追加するため空欄[A]に入れる処理は？","opts":["perm ← perm AND writeMask","perm ← perm OR writeMask","perm ← NOT perm","perm ← perm XOR adminMask"],"a":1,"exp":"特定ビットを1に設定するには、そのマスクとのORを使います。"},{"kind":"変更予測","q":"[A]を正しく補った後の perm は？","opts":["1001₂","0100₂","1101₂","0000₂"],"a":2,"exp":"1001 OR 0100 = 1101です。"}]},{"id":"object_cart","level":"標準","title":"オブジェクトとメソッド","lead":"Cartオブジェクトの合計金額を、メソッド呼出しで更新します。","code":["class Cart","    total","    procedure add(price)","        total ← total + price","    endprocedure","    procedure discount(rate)","        [A]","    endprocedure","endclass","c ← Cart(total=0)","c.add(1200)","c.add(800)","c.discount(0.10)","c.total を出力する"],"data":[{"label":"rate","text":"0.10は10%を表します。"}],"qs":[{"kind":"トレース","q":"2回の add が終わった直後の total は？","opts":["2000","800","1200","1800"],"a":0,"exp":"1200と800を順に加えるのでtotal=2000です。"},{"kind":"空欄補充","q":"10%割引を行う空欄[A]の処理として適切なのは？","opts":["total ← total × (1 - rate)","total ← total × rate","total ← total + rate","rate ← total × 0.1"],"a":0,"exp":"10%引き後は元の90%なのでtotal×(1-rate)です。"},{"kind":"変更予測","q":"割引率を0.25へ変更した場合、最終totalは？","opts":["500","1500","1750","2000"],"a":1,"exp":"2000×(1-0.25)=1500です。"}]},{"id":"matrix_transpose","level":"応用","title":"行列の転置","lead":"2×3行列の行と列を入れ替えて3×2行列を作ります。","code":["m ← [[1,2,3],[4,5,6]]","out ← 3行2列の配列","for r ← 0 to 1","    for c ← 0 to 2","        [A]","    endfor","endfor","out を出力する"],"data":[{"label":"転置","text":"元のm[r][c]をoutの列・行を入れ替えた位置へ置きます。"}],"qs":[{"kind":"空欄補充","q":"転置を行う空欄[A]の処理は？","opts":["out[r][c] ← m[r][c]","out[r][c] ← m[c][r]","m[c][r] ← out[r][c]","out[c][r] ← m[r][c]"],"a":3,"exp":"行と列を入れ替えるのでout[c][r]へm[r][c]を代入します。"},{"kind":"トレース","q":"処理後の out[2][1] は？","opts":["3","4","5","6"],"a":3,"exp":"out[2][1]にはm[1][2]=6が入ります。"},{"kind":"処理理解","q":"最終的な out は？","opts":["[[1,4],[2,5],[3,6]]","[[1,2,3],[4,5,6]]","[[1,2],[3,4],[5,6]]","[[4,1],[5,2],[6,3]]"],"a":0,"exp":"各列を行として並べると[[1,4],[2,5],[3,6]]です。"}]},{"id":"merge_sorted","level":"応用","title":"整列済み配列のマージ","lead":"昇順の2配列を先頭から比較し、小さい方をoutへ移して1つの昇順配列にします。","code":["a ← [2,5,9]","b ← [1,6,8]","i ← 0, j ← 0","out ← []","while i < 3 and j < 3","    if a[i] ≤ b[j]","        out の末尾に a[i] を追加","        i ← i + 1","    else","        out の末尾に b[j] を追加","        j ← j + 1","    endif","endwhile","残った要素をoutへ追加","out を出力する"],"data":[{"label":"比較","text":"各配列は最初から昇順に整列済みです。"}],"qs":[{"kind":"トレース","q":"outに3個の値が入った時点の内容は？","opts":["[1,2,6]","[2,5,9]","[1,2,5]","[1,5,6]"],"a":2,"exp":"1(b)、2(a)、5(a)の順で追加されます。"},{"kind":"変更予測","q":"aを[2,7,9]へ変更した場合、outの先頭4要素は？","opts":["[1,2,7,6]","[2,1,6,7]","[1,2,6,7]","[1,6,2,7]"],"a":2,"exp":"1、2、次は6<7なので6、その次に7となります。"},{"kind":"処理理解","q":"元の配列で最終的なoutは？","opts":["[2,5,9,1,6,8]","[1,2,6,5,8,9]","[9,8,6,5,2,1]","[1,2,5,6,8,9]"],"a":3,"exp":"2つの昇順配列をマージするので[1,2,5,6,8,9]です。"}]},{"id":"sentinel_search","level":"標準","title":"番兵を使った線形探索","lead":"配列末尾へ目的値を番兵として置き、ループ内の範囲判定を省きます。","code":["data ← [4,7,1,9]","target ← 6","n ← 4","data[n] ← target","i ← 0","while [A]","    i ← i + 1","endwhile","if i < n","    pos ← i","else","    pos ← -1","endif","pos を出力する"],"data":[{"label":"番兵","text":"data[4]には必ずtargetが入るため、探索ループはいずれ停止します。"}],"qs":[{"kind":"空欄補充","q":"空欄[A]に入る条件として適切なのは？","opts":["data[i] ≠ target","i < n","data[i] = target","i = target"],"a":0,"exp":"targetと一致するまでiを進めるのでdata[i]≠targetを条件にします。"},{"kind":"トレース","q":"target=6のとき、while終了直後の i は？","opts":["3","5","4","-1"],"a":2,"exp":"元の4要素には6がないため、番兵を置いた添字4で一致して停止します。"},{"kind":"変更予測","q":"targetを9へ変更した場合、最終posは？","opts":["3","2","4","-1"],"a":0,"exp":"元のdata[3]=9で見つかるのでi=3<nとなりpos=3です。"}]},{"id":"tree_height","level":"応用","title":"木の高さを再帰で求める","lead":"空の子を高さ0、葉を高さ1として、左右部分木の大きい方へ1を加えます。","code":["function height(node)","    if node = null","        return 0","    endif","    left ← height(node.left)","    right ← height(node.right)","    [A]","endfunction","A.left=B, A.right=C","B.left=D, B.right=null","C.left=null, C.right=null","D.left=null, D.right=null","height(A) を出力する"],"data":[{"label":"木","text":"Aの子はB,C。Bの左子はDです。"}],"qs":[{"kind":"空欄補充","q":"空欄[A]に入る戻り値は？","opts":["return 1 + max(left,right)","return 1 + left + right","return max(left,right) - 1","return 1 + min(left,right)"],"a":0,"exp":"現在ノード自身の1を、左右部分木の高い方へ加えます。"},{"kind":"トレース","q":"height(B) は？","opts":["1","3","4","2"],"a":3,"exp":"B→Dという2階層なのでheight(B)=2です。"},{"kind":"変更予測","q":"Dの左子にEを追加した場合、height(A)は？","opts":["2","3","4","5"],"a":2,"exp":"空の子を0とするのでE=1、D=2、B=3、A=4です。"}]}];

