function applyCompoundQualityAudit(){
  B_COMPOUND_SETS.forEach(set=>{
    const meta=B_COMPOUND_QUALITY[set.id];
    if(!meta||meta.length!==set.qs.length) return;
    set.qs.forEach((q,i)=>Object.assign(q,meta[i]));
  });
}
applyCompoundQualityAudit();

if(!profile.bCompoundHistory)profile.bCompoundHistory=[];
if(!profile.bCompoundStats)profile.bCompoundStats={};
B_COMPOUND_SETS.forEach(s=>{if(!profile.bCompoundStats[s.id])profile.bCompoundStats[s.id]={seen:0,correct:0,lastSeen:null}});
let bCompoundSet=null,bCompoundAnswers=[],bCompoundIndex=0,bCompoundSeconds=B_COMPOUND_SECONDS,bCompoundTimerId=null,bCompoundStartedAt=null;
function randomizeCompoundSet(set){const out=structuredClone(set);out.qs=out.qs.map(q=>{const correct=q.opts[q.a];const opts=shuffled(q.opts);return {...q,opts,a:opts.indexOf(correct)}});return out}
function chooseCompoundSet(){const picked=[...B_COMPOUND_SETS].sort((a,b)=>{const sa=profile.bCompoundStats[a.id]?.seen||0,sb=profile.bCompoundStats[b.id]?.seen||0;if(sa!==sb)return sa-sb;const la=profile.bCompoundStats[a.id]?.lastSeen||'',lb=profile.bCompoundStats[b.id]?.lastSeen||'';if(la!==lb)return la.localeCompare(lb);return Math.random()-.5})[0];return randomizeCompoundSet(picked)}
function startCompoundChallenge(){bCompoundSet=chooseCompoundSet();bCompoundAnswers=Array(3).fill(null);bCompoundIndex=0;bCompoundSeconds=B_COMPOUND_SECONDS;bCompoundStartedAt=Date.now();document.getElementById('bMockSelect')?.classList.add('hidden');document.getElementById('bCompoundResult')?.classList.remove('show');document.getElementById('bCompoundExam')?.classList.add('show');document.getElementById('bCompoundLevel').textContent=bCompoundSet.level;document.getElementById('bCompoundTitle').textContent=bCompoundSet.title;document.getElementById('bCompoundLead').textContent=bCompoundSet.lead;document.getElementById('bCompoundCode').innerHTML=bCompoundSet.code.map((line,i)=>`<div class="bmock-code-line"><span class="ln">${i+1}</span><span>${escapeHtml(line)}</span></div>`).join('');document.getElementById('bCompoundData').innerHTML=(bCompoundSet.data||[]).map(d=>`<div class="bcompound-data-card"><b>${escapeHtml(d.label)}</b>${escapeHtml(d.text)}</div>`).join('');renderCompoundQuestion();startCompoundTimer()}
function startCompoundTimer(){stopCompoundTimer();updateCompoundTimer();bCompoundTimerId=setInterval(()=>{bCompoundSeconds--;updateCompoundTimer();if(bCompoundSeconds<=0){stopCompoundTimer();finishCompoundChallenge(true)}},1000)}
function stopCompoundTimer(){if(bCompoundTimerId){clearInterval(bCompoundTimerId);bCompoundTimerId=null}}
function updateCompoundTimer(){const t=document.getElementById('bCompoundTimer');if(!t)return;t.textContent=bMockFormatTime(bCompoundSeconds);t.classList.toggle('warn',bCompoundSeconds<=300&&bCompoundSeconds>120);t.classList.toggle('danger',bCompoundSeconds<=120)}
function renderCompoundQuestion(){const q=bCompoundSet.qs[bCompoundIndex],ans=bCompoundAnswers[bCompoundIndex];const diffClass=q.qlevel==='基礎'?'diff-basic':q.qlevel==='応用'?'diff-advanced':'diff-standard';document.getElementById('bCompoundQProgress').innerHTML=`設問 ${bCompoundIndex+1} / 3 <span class="bcompound-kind">${escapeHtml(q.kind||'トレース')}</span> <span class="bcompound-kind ${diffClass}">${escapeHtml(q.qlevel||'標準')}</span>`;document.getElementById('bCompoundQuestion').textContent=q.q;document.getElementById('bCompoundOptions').innerHTML=q.opts.map((opt,i)=>`<button class="bmock-option ${ans===i?'selected':''}" data-copt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(opt)}</button>`).join('');document.querySelectorAll('[data-copt]').forEach(btn=>btn.onclick=()=>{bCompoundAnswers[bCompoundIndex]=Number(btn.dataset.copt);renderCompoundQuestion()});document.getElementById('bCompoundPrev').disabled=bCompoundIndex===0;document.getElementById('bCompoundNext').textContent=bCompoundIndex===2?'提出へ':'次へ →';document.getElementById('bCompoundQNav').innerHTML=bCompoundSet.qs.map((_,i)=>`<button class="${bCompoundAnswers[i]!==null?'answered':''} ${i===bCompoundIndex?'current':''}" data-cq="${i}">${i+1}</button>`).join('');document.querySelectorAll('[data-cq]').forEach(btn=>btn.onclick=()=>{bCompoundIndex=Number(btn.dataset.cq);renderCompoundQuestion()})}
function askSubmitCompound(){const blank=bCompoundAnswers.filter(x=>x===null).length;if(confirm(blank?`未回答が${blank}問あります。提出しますか？`:'回答を提出しますか？'))finishCompoundChallenge(false)}
function finishCompoundChallenge(timeUp=false){if(!bCompoundSet)return;stopCompoundTimer();const used=Math.min(B_COMPOUND_SECONDS,Math.max(0,Math.round((Date.now()-(bCompoundStartedAt||Date.now()))/1000)));let correct=0,blank=0;const details=bCompoundSet.qs.map((q,i)=>{const ans=bCompoundAnswers[i],ok=ans===q.a;if(ok)correct++;if(ans===null)blank++;return{q:q.q,selected:ans===null?null:q.opts[ans],correct:q.opts[q.a],ok,exp:q.exp,kind:q.kind||'トレース',qlevel:q.qlevel||'標準',point:q.point||'',pitfall:q.pitfall||''}});const rate=Math.round(correct/3*100),earned=correct*12+(correct===3?15:0);profile.xp=(profile.xp||0)+earned;const st=profile.bCompoundStats[bCompoundSet.id];st.seen=(st.seen||0)+1;st.correct=(st.correct||0)+correct;st.lastSeen=localDateISO(0);profile.bCompoundHistory=[{date:localDateISO(0),id:bCompoundSet.id,title:bCompoundSet.title,level:bCompoundSet.level,total:3,correct,blank,rate,seconds:used,timeUp,details},...(profile.bCompoundHistory||[])].slice(0,20);saveProfile();document.getElementById('bCompoundExam')?.classList.remove('show');document.getElementById('bCompoundResult')?.classList.add('show');document.getElementById('bCompoundResultScore').textContent=`${correct} / 3`;document.getElementById('bCompoundResultMessage').textContent=correct===3?`長いコードを最後まで読み切れています。+${earned} XP`:correct===2?`あと一歩です。間違えた設問の途中状態を確認しましょう。+${earned} XP`:`紙に途中値を書きながら再挑戦するのがおすすめです。+${earned} XP`;document.getElementById('bCompoundCorrect').textContent=correct;document.getElementById('bCompoundWrong').textContent=3-correct-blank;document.getElementById('bCompoundBlank').textContent=blank;document.getElementById('bCompoundTime').textContent=bMockFormatTime(used);document.getElementById('bCompoundReview').innerHTML=details.map((d,i)=>`<div class="bcompound-review-item ${d.ok?'correct':'wrong'}"><b>設問${i+1} ${d.ok?'✓ 正解':'✕ 要確認'}</b><div class="bcompound-review-meta"><span>${escapeHtml(d.kind)}</span><span>${escapeHtml(d.qlevel)}</span></div><div class="bcompound-review-q">${escapeHtml(d.q)}</div><div class="bcompound-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="bcompound-review-box"><b>考え方</b><span>${escapeHtml(d.exp)}</span></div><div class="bcompound-review-box"><b>見るポイント</b><span>${escapeHtml(d.point)}</span></div><div class="bcompound-review-box pitfall"><b>間違えやすい点</b><span>${escapeHtml(d.pitfall)}</span></div></div>`).join('')}
document.getElementById('bCompoundStart')?.addEventListener('click',startCompoundChallenge);document.getElementById('bCompoundRetry')?.addEventListener('click',startCompoundChallenge);document.getElementById('bCompoundBackMenu')?.addEventListener('click',()=>{stopCompoundTimer();document.getElementById('bCompoundResult')?.classList.remove('show');continueSubjectBFlow()});document.getElementById('bCompoundPrev')?.addEventListener('click',()=>{if(bCompoundIndex>0){bCompoundIndex--;renderCompoundQuestion()}});document.getElementById('bCompoundNext')?.addEventListener('click',()=>{if(bCompoundIndex<2){bCompoundIndex++;renderCompoundQuestion()}else askSubmitCompound()});document.getElementById('bCompoundSubmit')?.addEventListener('click',askSubmitCompound);document.getElementById('bCompoundExit')?.addEventListener('click',()=>{if(confirm('複合問題を終了しますか？回答は保存されません。')){stopCompoundTimer();document.getElementById('bCompoundExam')?.classList.remove('show');showBMockMenu()}});

const B_MOCK_COUNT=8;
const B_MOCK_SECONDS=40*60;
const B_MOCK_QUOTAS={'基礎':2,'標準':4,'応用':2};

const B_MOCK_EXTRA_DISTRACTOR={
  loop_sum:'5',array_max:'11',linear_search:'2',stack_ops:'8',recursion:'4',tree_dfs:'B',
  count_even:'4',array_reverse:'5',nested_loop:'8',binary_search_b:'6',
  bubble_sort_b:'[4,1,2,5]',selection_sort_b:'[1,5,2,4]',matrix_sum:'7',matrix_find:'(0,2)',
  queue_ops:'7',linked_list:'12',bit_mask:'0001',object_counter:'2',gcd_euclid:'3',recursive_fib:'5'
};

const B_MOCK_EXPLANATION={
  loop_sum:'i=2のときは直前のsum=1に2を加えるので、sum=3になります。',
  array_max:'data[1]=9は現在のmax=4より大きいため、maxは9へ更新されます。',
  linear_search:'添字は0から始まるため、12を見つけた位置はdata[3]で、posには3が入ります。',
  stack_ops:'スタックはLIFO（Last In, First Out：後入れ先出し）です。2の上に4が積まれているので、次のPOPでは4が取り出されます。',
  recursion:'factorialの終了条件ではfactorial(1)=1を返します。ここから呼出し元へ値が戻ります。',
  tree_dfs:'先行順の深さ優先探索ではA→Bの次にBの左子Dへ進むので、次の出力はDです。',
  count_even:'8は2で割り切れるので条件が真となり、countは0から1へ増えます。',
  array_reverse:'末尾から走査しているため、5の次はdata[3]=4がoutへ追加されます。',
  nested_loop:'外側3回×内側2回なので、countを増やす処理は合計6回実行されます。',
  binary_search_b:'data[3]=12はtarget=21より小さいため左側を捨て、low=mid+1=4とします。',
  bubble_sort_b:'5と2を交換すると、1走査後の配列は[1,4,2,5]になります。',
  selection_sort_b:'未整列部分の最小値1は添字3にあるため、最終的なminPosは3です。',
  matrix_sum:'ここまでのsum=6に最後の要素4を加えるので、合計は10です。',
  matrix_find:'10は2行目・2列目にあり、添字が0始まりなので位置は(1,1)です。',
  queue_ops:'キューはFIFO（First In, First Out：先入れ先出し）です。3,5の順に入っているので、次のDEQUEUEは先頭の3です。',
  linked_list:'A=5、B=7、C=9を順に合計するため、最終sumは5+7+9=21です。',
  bit_mask:'1101 AND 0100は0100で0ではないため、条件が真となりflag=trueです。',
  object_counter:'value=3の状態でinc()をもう1回呼ぶので、valueは4になります。',
  gcd_euclid:'12は6で割り切れるため12 mod 6=0です。これで次の反復で終了条件に到達します。',
  recursive_fib:'fib(3)=fib(2)+fib(1)=1+1=2です。'
};

if(!profile.bMockHistory) profile.bMockHistory=[];
if(!profile.bMockStats) profile.bMockStats={};
B_EXERCISES.forEach(ex=>{
  if(!profile.bMockStats[ex.id]) profile.bMockStats[ex.id]={seen:0,correct:0,lastSeen:null};
});

let bMockItems=[],bMockAnswers=[],bMockFlags=new Set(),bMockIndex=0;
let bMockSeconds=B_MOCK_SECONDS,bMockTimerId=null,bMockStartedAt=null,lastBMockAttempt=null;

function bMockCandidateFromExercise(ex){
  const predSteps=ex.steps.map((s,i)=>({s,i})).filter(x=>x.s.predict);
  if(!predSteps.length)return null;
  const pick=predSteps[Math.floor(Math.random()*predSteps.length)];
  const step=pick.s,pred=step.predict,correct=String(pred.opts[pred.a]);
  const options=pred.opts.map(String);
  return {
    id:ex.id,exId:ex.id,checkpoint:pick.i,title:ex.title,level:ex.level,code:ex.code,line:step.line,
    state:structuredClone(step.state||{}),
    visual:{
      array:structuredClone(ex.array||null),arrayState:structuredClone(step.arrayState||null),
      focus:step.focus,found:step.found,target:ex.target,matrix:structuredClone(ex.matrix||null),
      matrixFocus:structuredClone(step.matrixFocus||null),queue:structuredClone(step.queue||null),
      list:structuredClone(ex.list||null),currentNode:step.currentNode,visited:structuredClone(step.visited||null),
      bits:structuredClone(step.bits||null),object:structuredClone(step.object||null),objectName:ex.objectName,
      stack:structuredClone(step.stack||null),tree:structuredClone(ex.tree||null)
    },
    q:pred.q,options,correctText:correct,
    explain:pred.explain||B_MOCK_EXPLANATION[ex.id]||`${ex.title}をコード通りに追うと、正解は「${correct}」です。`
  };
}

function shuffleBMockAnswer(item){
  const options=shuffled(item.options);
  return {...item,options,a:options.indexOf(item.correctText)};
}

function buildBMock(){
  const candidates=B_EXERCISES.map(bMockCandidateFromExercise).filter(Boolean),selected=[];
  Object.entries(B_MOCK_QUOTAS).forEach(([level,n])=>{
    const pool=candidates.filter(x=>x.level===level).sort((a,b)=>{
      const sa=profile.bMockStats[a.id]?.seen||0,sb=profile.bMockStats[b.id]?.seen||0;
      if(sa!==sb)return sa-sb;
      const la=profile.bMockStats[a.id]?.lastSeen||'',lb=profile.bMockStats[b.id]?.lastSeen||'';
      if(la!==lb)return la.localeCompare(lb);
      return Math.random()-.5;
    });
    selected.push(...pool.slice(0,n));
  });
  return shuffled(selected).map(shuffleBMockAnswer);
}

function bMockFormatTime(sec){
  sec=Math.max(0,Math.floor(sec||0));
  return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;
}

function renderPracticeNextCard(){
  const title=document.getElementById('bPracticeNextTitle'),desc=document.getElementById('bPracticeNextDesc'),action=document.getElementById('bPracticeNextAction');
  if(!title||!desc||!action)return;
  const rec=subjectBHubRecommendation();
  if(rec.stage<3){
    title.textContent=`先に ${rec.title}`;desc.textContent='実戦演習へ進む前に、未完了の基礎演習を1つ進めるのがおすすめです。';action.textContent='基礎演習へ →';
  }else if(rec.mode==='final'){
    title.textContent='短い実戦演習は一通り完了しました';desc.textContent='100分を確保できる日は、科目B 総合実戦で20問を通して確認できます。';action.textContent='総合実戦を確認 →';
  }else if(rec.mode==='securityMock'){
    title.textContent='セキュリティ ミニ模試';desc.textContent='次はケース判断を8問・20分でヒントなし確認します。';action.textContent='セキュリティ実戦へ →';
  }else if(rec.mode==='miniMock'){
    title.textContent='アルゴリズム ミニ模試';desc.textContent='8問・40分で、途中状態を連続して読み切れるか確認します。';action.textContent='ミニ模試を始める →';
  }else{
    title.textContent=rec.title||'複合問題を1セット';desc.textContent=rec.desc||'長いコードを3問で読みます。';action.textContent='複合問題を始める →';
  }
  action.onclick=()=>launchSubjectBRecommendation(rec);
}

function renderBMockMenu(){
  const hist=profile.bMockHistory||[],best=hist.length?Math.max(...hist.map(x=>x.rate||0)):null;
  document.getElementById('bMockBest').textContent=best===null?'ベスト —':`ベスト ${best}%`;
  const root=document.getElementById('bMockHistory'),rows=hist.slice(0,5);
  root.innerHTML=rows.length?rows.map(h=>`
    <div class="bmock-history-row">
      <div class="bmock-history-main"><b>${h.correct}/${h.total}問 正解</b><span>${escapeHtml(h.date||'')}</span></div>
      <div class="bmock-history-time">${bMockFormatTime(h.seconds||0)}</div><div class="bmock-history-score">${h.rate}%</div>
    </div>`).join(''):'<div class="sub">まだ受験履歴はありません。</div>';
  const croot=document.getElementById('bCompoundHistoryMenu');
  if(croot){const cs=(profile.bCompoundHistory||[]).slice(0,5);croot.innerHTML=cs.length?cs.map(h=>`<div class="bmock-history-row"><div class="bmock-history-main"><b>${escapeHtml(h.title)} ${h.correct}/3</b><span>${escapeHtml(h.date||'')}</span></div><div class="bmock-history-time">${bMockFormatTime(h.seconds||0)}</div><div class="bmock-history-score">${h.rate}%</div></div>`).join(''):'<div class="sub">まだ受験履歴はありません。</div>';}
  renderPracticeNextCard();
  if(typeof renderSubjectBHub==='function')renderSubjectBHub();
}

function showBMockMenu(){
  stopBMockTimer();
  stopCompoundTimer();
  document.getElementById('bSelect')?.classList.add('hidden');
  document.getElementById('secSelect')?.classList.add('hidden');
  document.getElementById('bLab')?.classList.remove('show');
  document.getElementById('secLab')?.classList.remove('show');
  document.getElementById('bMockExam')?.classList.remove('show');
  document.getElementById('bMockResult')?.classList.remove('show');
  document.getElementById('bCompoundExam')?.classList.remove('show');
  document.getElementById('bCompoundResult')?.classList.remove('show');
  document.getElementById('bMockSelect')?.classList.remove('hidden');
  renderBMockMenu();
}

function startBMiniMock(){
  bMockItems=buildBMock();bMockAnswers=Array(bMockItems.length).fill(null);bMockFlags=new Set();bMockIndex=0;
  bMockSeconds=B_MOCK_SECONDS;bMockStartedAt=Date.now();lastBMockAttempt=null;
  document.getElementById('bMockSelect')?.classList.add('hidden');
  document.getElementById('bMockResult')?.classList.remove('show');
  document.getElementById('bMockExam')?.classList.add('show');
  renderBMockQuestion();startBMockTimer();
}

function startBMockTimer(){
  stopBMockTimer();updateBMockTimer();
  bMockTimerId=setInterval(()=>{bMockSeconds--;updateBMockTimer();if(bMockSeconds<=0){stopBMockTimer();finishBMiniMock(true);}},1000);
}
function stopBMockTimer(){if(bMockTimerId){clearInterval(bMockTimerId);bMockTimerId=null;}}
function updateBMockTimer(){
  const t=document.getElementById('bMockTimer');if(!t)return;
  t.textContent=bMockFormatTime(bMockSeconds);
  t.classList.toggle('warn',bMockSeconds<=600&&bMockSeconds>300);t.classList.toggle('danger',bMockSeconds<=300);
}

function bMockVisualHtml(item){
  const v=item.visual||{};
  if(v.matrix){const f=v.matrixFocus||[];return `<div class="trace-matrix">${v.matrix.map((row,r)=>`<div class="trace-matrix-row">${row.map((x,c)=>`<div class="trace-matrix-cell ${f[0]===r&&f[1]===c?'focus':''}">${escapeHtml(x)}<span class="trace-matrix-index">${r},${c}</span></div>`).join('')}</div>`).join('')}</div>`;}
  if(v.queue)return `<div class="trace-queue-label">先頭 → 末尾</div><div class="trace-queue">${v.queue.length?v.queue.map(x=>`<div class="trace-queue-item">${escapeHtml(x)}</div>`).join(''):'<div class="sub">空</div>'}</div>`;
  if(v.list){const visited=v.visited||[];return `<div class="trace-list">${v.list.map((node,i)=>`${i?'<span class="trace-list-arrow">→</span>':''}<div class="trace-list-node ${v.currentNode===node.id?'current':''} ${visited.includes(node.id)?'visited':''}"><div class="trace-node-id">${escapeHtml(node.id)}</div><div class="trace-node-value">${escapeHtml(node.value)}</div></div>`).join('')}<span class="trace-list-arrow">→ null</span></div>`;}
  if(v.bits){const labels={x:'x',mask:'mask',result:'AND'};return `<div class="trace-bits">${Object.entries(v.bits).map(([k,val])=>`<div class="trace-bit-row"><div class="trace-bit-label">${labels[k]||escapeHtml(k)}</div><div class="trace-bit-value">${escapeHtml(val)}</div></div>`).join('')}</div>`;}
  if(v.object)return `<div class="trace-object"><div class="trace-object-title">${escapeHtml(v.objectName||'object')}</div>${Object.entries(v.object).map(([k,val])=>`<div class="trace-object-prop"><span>${escapeHtml(k)}</span><b>${escapeHtml(val)}</b></div>`).join('')}</div>`;
  if(v.array){const arr=v.arrayState||v.array;return `<div class="trace-array">${arr.map((x,i)=>`<div class="trace-array-cell ${v.focus===i?'focus':''} ${v.found===i?'found':''}">${escapeHtml(x)}<span class="trace-array-index">${i}</span></div>`).join('')}</div>${v.target!==undefined?`<div class="visit-path">target = ${escapeHtml(v.target)}</div>`:''}`;}
  if(v.stack)return `<div class="sub" style="text-align:center;margin-bottom:6px">トップ</div><div class="trace-stack">${v.stack.map(x=>`<div class="trace-stack-item">${escapeHtml(x)}</div>`).join('')}</div>`;
  if(v.tree){const visited=v.visited||[],mark=n=>visited.includes(n)?`[${n}]`:n;return `<div class="tree-view">       ${mark('A')}
      /   \\
    ${mark('B')}     ${mark('C')}
   / \\
 ${mark('D')}   ${mark('E')}</div>`;}
  return '';
}

function renderBMockQuestion(){
  if(!bMockItems.length)return;
  const item=bMockItems[bMockIndex];
  document.getElementById('bMockQNum').textContent=`問題 ${bMockIndex+1} / ${bMockItems.length}`;
  document.getElementById('bMockCode').innerHTML=item.code.map((line,i)=>`<div class="bmock-code-line ${i===item.line?'target':''}"><span class="ln">${i+1}</span><span>${escapeHtml(line)}</span></div>`).join('');
  document.getElementById('bMockState').innerHTML=Object.entries(item.state||{}).map(([k,v])=>`<div class="bmock-state-card"><div class="bmock-state-key">${escapeHtml(k)}</div><div class="bmock-state-val">${escapeHtml(v)}</div></div>`).join('');
  document.getElementById('bMockVisual').innerHTML=bMockVisualHtml(item);
  document.getElementById('bMockQuestion').textContent=item.q;
  const answer=bMockAnswers[bMockIndex];
  document.getElementById('bMockOptions').innerHTML=item.options.map((opt,i)=>`<button class="bmock-option ${answer===i?'selected':''}" data-bmopt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(opt)}</button>`).join('');
  document.querySelectorAll('[data-bmopt]').forEach(btn=>btn.onclick=()=>{bMockAnswers[bMockIndex]=Number(btn.dataset.bmopt);renderBMockQuestion();});
  document.getElementById('bMockPrev').disabled=bMockIndex===0;
  document.getElementById('bMockNext').textContent=bMockIndex===bMockItems.length-1?'提出へ':'次へ →';
  document.getElementById('bMockFlag').classList.toggle('active',bMockFlags.has(bMockIndex));
  document.getElementById('bMockFlag').textContent=bMockFlags.has(bMockIndex)?'★ 後で見る':'☆ 後で見る';
  renderBMockNav();
}

function renderBMockNav(){
  const root=document.getElementById('bMockNavGrid');
  root.innerHTML=bMockItems.map((_,i)=>`<button class="bmock-nav-q ${bMockAnswers[i]!==null?'answered':''} ${bMockFlags.has(i)?'flagged':''} ${i===bMockIndex?'current':''}" data-bmq="${i}">${i+1}</button>`).join('');
  root.querySelectorAll('[data-bmq]').forEach(btn=>btn.onclick=()=>{bMockIndex=Number(btn.dataset.bmq);renderBMockQuestion();});
  document.getElementById('bMockAnswerCount').textContent=`${bMockAnswers.filter(x=>x!==null).length} / ${bMockItems.length} 回答`;
}

function askSubmitBMock(){
  const blank=bMockAnswers.filter(x=>x===null).length;
  if(confirm(blank?`未回答が${blank}問あります。提出しますか？`:'回答を提出しますか？'))finishBMiniMock(false);
}

function finishBMiniMock(timeUp=false){
  if(!bMockItems.length)return;
  stopBMockTimer();
  const used=Math.min(B_MOCK_SECONDS,Math.max(0,Math.round((Date.now()-(bMockStartedAt||Date.now()))/1000)));
  let correct=0,blank=0;
  const details=bMockItems.map((item,i)=>{
    const ans=bMockAnswers[i],ok=ans===item.a;if(ok)correct++;if(ans===null)blank++;
    const st=profile.bMockStats[item.id]||(profile.bMockStats[item.id]={seen:0,correct:0,lastSeen:null});
    st.seen=(st.seen||0)+1;if(ok)st.correct=(st.correct||0)+1;st.lastSeen=localDateISO(0);
    return {id:item.id,exId:item.exId,title:item.title,level:item.level,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain};
  });
  const rate=Math.round(correct/bMockItems.length*100),earned=correct*8+(rate>=75?20:0);
  profile.xp=(profile.xp||0)+earned;
  if(profile.skills?.['アルゴリズム']!==undefined)profile.skills['アルゴリズム']=clamp(profile.skills['アルゴリズム']+(rate>=75?2:rate>=50?1:0),0,100);
  const attempt={
    date:localDateISO(0),total:bMockItems.length,correct,blank,rate,seconds:used,timeUp,
    levels:Object.fromEntries(['基礎','標準','応用'].map(level=>{const rows=details.filter(d=>d.level===level);return[level,{correct:rows.filter(d=>d.ok).length,total:rows.length}]})),
    details
  };
  profile.bMockHistory=[attempt,...(profile.bMockHistory||[])].slice(0,20);lastBMockAttempt=attempt;saveProfile();
  document.getElementById('bMockExam')?.classList.remove('show');document.getElementById('bMockResult')?.classList.add('show');
  renderBMockResult(attempt,earned);
  if(typeof renderReadiness==='function')renderReadiness();
  if(typeof renderDailyPlan==='function')renderDailyPlan();
}

function renderBMockResult(attempt,earned){
  document.getElementById('bMockResultScore').textContent=`${attempt.correct} / ${attempt.total}`;
  document.getElementById('bMockResultMessage').textContent=attempt.rate>=88?`かなり安定しています。+${earned} XP`:attempt.rate>=75?`実戦レベルに近づいています。+${earned} XP`:attempt.rate>=50?`間違えた状態変化を学習モードで追い直しましょう。+${earned} XP`:`誤答した演習を1行ずつトレースし直すのがおすすめです。+${earned} XP`;
  document.getElementById('bMockStatCorrect').textContent=attempt.correct;
  document.getElementById('bMockStatWrong').textContent=attempt.total-attempt.correct-attempt.blank;
  document.getElementById('bMockStatBlank').textContent=attempt.blank;document.getElementById('bMockStatTime').textContent=bMockFormatTime(attempt.seconds);
  document.getElementById('bMockBreakdown').innerHTML=['基礎','標準','応用'].map(level=>{const x=attempt.levels[level],pct=x.total?Math.round(x.correct/x.total*100):0;return `<div class="bmock-break-row"><div class="bmock-break-label">${level}</div><div class="bmock-break-bar"><div class="bmock-break-fill" style="width:${pct}%"></div></div><div class="bmock-break-score">${x.correct}/${x.total}</div></div>`}).join('');
  document.getElementById('bMockReviewList').innerHTML=attempt.details.map((d,i)=>`
    <div class="bmock-review-item ${d.ok?'correct':'wrong'}">
      <div class="bmock-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span class="bmock-review-mark">${d.ok?'✓ 正解':'✕ 要復習'}</span></div>
      <div class="bmock-review-q">${escapeHtml(d.q)}</div>
      <div class="bmock-review-answer">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div>
      <div class="bmock-review-explain">${escapeHtml(d.explain)}</div>
      ${d.ok?'':`<button class="bmock-review-study" data-bstudy="${escapeHtml(d.exId)}">学習モードで1行ずつ確認 →</button>`}
    </div>`).join('');
  document.querySelectorAll('[data-bstudy]').forEach(btn=>btn.onclick=()=>{document.getElementById('bMockResult')?.classList.remove('show');setBMode('trace');startBExercise(btn.dataset.bstudy);});
}

document.getElementById('bMockStart')?.addEventListener('click',startBMiniMock);
document.getElementById('bMockRetry')?.addEventListener('click',startBMiniMock);
document.getElementById('bMockResultList')?.addEventListener('click',continueSubjectBFlow);
document.getElementById('bMockSubmitTop')?.addEventListener('click',askSubmitBMock);
document.getElementById('bMockPrev')?.addEventListener('click',()=>{if(bMockIndex>0){bMockIndex--;renderBMockQuestion();}});
document.getElementById('bMockNext')?.addEventListener('click',()=>{if(bMockIndex<bMockItems.length-1){bMockIndex++;renderBMockQuestion();}else askSubmitBMock();});
document.getElementById('bMockFlag')?.addEventListener('click',()=>{bMockFlags.has(bMockIndex)?bMockFlags.delete(bMockIndex):bMockFlags.add(bMockIndex);renderBMockQuestion();});
document.getElementById('bMockExit')?.addEventListener('click',()=>{if(confirm('実戦ミニ模試を終了しますか？回答は保存されません。'))showBMockMenu();});


if(!profile.bProgress) profile.bProgress={};
B_EXERCISES.forEach(x=>{
  if(profile.bProgress[x.id]===undefined) profile.bProgress[x.id]=0;
});
saveProfile();

let currentB=null;
let bStepIndex=-1;
let bPredictionSatisfied=true;
let lastBState={};


let currentBFilter='all';
function traceNextRecommendation(){
  const ex=B_EXERCISES.find(x=>(profile.bProgress?.[x.id]||0)<100);
  if(ex)return {id:ex.id,title:ex.title,level:ex.level,concept:ex.concept};
  return null;
}
function renderTraceNextCard(){
  const title=document.getElementById('bTraceNextTitle'),desc=document.getElementById('bTraceNextDesc'),action=document.getElementById('bTraceNextAction');
  if(!title||!desc||!action)return;
  const next=traceNextRecommendation();
  if(next){
    title.textContent=next.title;desc.textContent=`${next.level}・${next.concept}`;action.textContent='この演習を始める →';action.onclick=()=>startBExercise(next.id);
  }else{
    const rec=subjectBHubRecommendation();
    title.textContent='アルゴリズム20演習は完了しました';
    desc.textContent=rec.mode==='security'?'次はセキュリティ ケース演習へ進みます。':'短い実戦演習へ進めます。';
    action.textContent=rec.mode==='security'?'セキュリティへ →':'次の科目Bへ →';action.onclick=()=>launchSubjectBRecommendation(rec);
  }
}
document.getElementById('bFilterTabs')?.querySelectorAll('[data-bfilter]').forEach(btn=>{
  btn.onclick=()=>{
    currentBFilter=btn.dataset.bfilter;
    document.getElementById('bFilterTabs').querySelectorAll('[data-bfilter]').forEach(x=>x.classList.toggle('active',x===btn));
    renderBGrid();
  };
});

function renderBGrid(){
  const root=document.getElementById('bExerciseGrid');
  if(!root) return;
  root.innerHTML='';
  const done=B_EXERCISES.filter(ex=>(profile.bProgress?.[ex.id]||0)>=100).length;
  const visible=B_EXERCISES.filter(ex=>currentBFilter==='all'||ex.level===currentBFilter);
  visible.forEach(ex=>{
    const pct=profile.bProgress?.[ex.id]||0;
    const card=document.createElement('div');
    const nextId=traceNextRecommendation()?.id;
    card.className='b-card'+(pct>=100?' done':'')+(ex.id===nextId?' b-next-highlight':'');
    const diffClass=ex.level==='標準'?'medium':ex.level==='応用'?'hard':'';
    card.innerHTML=`
      <div class="b-card-top">
        <div class="b-card-icon">${ex.icon}</div>
        <div>
          <div class="b-card-title">${ex.title}</div>
          <div class="b-card-meta">${ex.concept}</div>
        </div>
      </div>
      <div class="b-card-desc">${ex.desc}</div>
      <div class="b-card-bottom">
        <span class="difficulty ${diffClass}">${ex.level}</span>
        ${pct>=100?'<span class="b-check">✓ 完了</span>':''}
        <button class="b-start" data-bex="${ex.id}">${pct>=100?'もう一度':'開始'}</button>
      </div>`;
    root.appendChild(card);
  });
  const t=document.getElementById('bProgressText');
  if(t){
    const levels=['基礎','標準','応用'].map(level=>{
      const all=B_EXERCISES.filter(x=>x.level===level).length;
      const clear=B_EXERCISES.filter(x=>x.level===level&&(profile.bProgress?.[x.id]||0)>=100).length;
      return `${level}${clear}/${all}`;
    }).join(' ・ ');
    t.innerHTML=`<div>${done} / ${B_EXERCISES.length}</div><div style="font-size:14px;color:#8965ab;margin-top:2px">${levels}</div>`;
  }
  root.querySelectorAll('[data-bex]').forEach(b=>b.onclick=()=>startBExercise(b.dataset.bex));
  renderTraceNextCard();
  if(typeof renderSubjectBHub==='function')renderSubjectBHub();
}

document.getElementById('mapTrace')?.addEventListener('click',()=>{
  showScreen('trace');
  showBList();
});

function showBList(){
  stopBMockTimer();
  document.getElementById('bSelect').classList.remove('hidden');
  document.getElementById('secSelect')?.classList.add('hidden');
  document.getElementById('bMockSelect')?.classList.add('hidden');
  document.getElementById('bMockExam')?.classList.remove('show');
  document.getElementById('bMockResult')?.classList.remove('show');
  document.getElementById('bLab').classList.remove('show');
  renderBGrid();
}
document.getElementById('bBackToList')?.addEventListener('click',showBList);
document.getElementById('bNextExercise')?.addEventListener('click',continueSubjectBFlow);

function startBExercise(id){
  currentB=B_EXERCISES.find(x=>x.id===id);
  if(!currentB) return;
  bStepIndex=-1;
  bPredictionSatisfied=true;
  lastBState={};

  document.getElementById('bSelect').classList.add('hidden');
  document.getElementById('bLab').classList.add('show');
  document.getElementById('bComplete').classList.remove('show');
  document.getElementById('bLabTitle').textContent=currentB.title;
  document.getElementById('bLabMeta').textContent=`科目B・${currentB.concept}・${currentB.level}`;
  document.getElementById('bCode').innerHTML=currentB.code.map((line,i)=>`<div class="b-code-line" data-bline="${i}">${escapeHtml(line)}</div>`).join('');
  resetBView();
}

function escapeHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function resetBView(){
  bStepIndex=-1;
  bPredictionSatisfied=true;
  lastBState={};
  document.querySelectorAll('.b-code-line').forEach(l=>l.classList.remove('active'));
  document.getElementById('bStateGrid').innerHTML='<div class="sub">まだ実行していません。</div>';
  document.getElementById('bVisual').innerHTML='<div class="sub" style="text-align:center">1行ずつ実行し、途中2か所で次の状態を予測します。</div>';
  document.getElementById('bTraceMessage').textContent='最初の行から1行ずつ実行してください。';
  document.getElementById('bTraceProgress').style.width='0%';
  document.getElementById('predictionBox').classList.remove('show');
  document.getElementById('bStep').disabled=false;
  document.getElementById('bStep').textContent='▶ 次の行を実行';
  document.getElementById('bComplete').classList.remove('show');
}
document.getElementById('bReset')?.addEventListener('click',resetBView);

document.getElementById('bStep')?.addEventListener('click',()=>{
  if(!currentB) return;
  if(!bPredictionSatisfied){
    popToast('予測問題に答えてから進みましょう');
    return;
  }
  if(bStepIndex < currentB.steps.length-1){
    bStepIndex++;
    renderBStep(currentB.steps[bStepIndex]);
  }
});

function renderBStep(step){
  document.querySelectorAll('.b-code-line').forEach(l=>l.classList.remove('active'));
  const active=document.querySelector(`.b-code-line[data-bline="${step.line}"]`);
  if(active) active.classList.add('active');

  renderBState(step.state||{});
  renderBVisual(step);
  document.getElementById('bTraceMessage').textContent=step.msg||'';
  document.getElementById('bTraceProgress').style.width=`${((bStepIndex+1)/currentB.steps.length)*100}%`;

  if(step.predict){
    showBPrediction(step.predict);
  }else{
    bPredictionSatisfied=true;
    document.getElementById('predictionBox').classList.remove('show');
  }

  if(bStepIndex===currentB.steps.length-1 && !step.predict){
    finishBExercise();
  }
}

function renderBState(state){
  const grid=document.getElementById('bStateGrid');
  grid.innerHTML='';
  Object.entries(state).forEach(([k,v])=>{
    const changed=lastBState[k]!==undefined && String(lastBState[k])!==String(v);
    const d=document.createElement('div');
    d.className='state-card';
    d.innerHTML=`<div class="state-key">${escapeHtml(k)}</div><div class="state-value ${changed?'changed':''}">${escapeHtml(v)}</div>`;
    grid.appendChild(d);
  });
  lastBState={...state};
}

function renderBVisual(step){
  const v=document.getElementById('bVisual');

  if(currentB.matrix){
    const focus=step.matrixFocus||[];
    v.innerHTML=`<div class="trace-matrix">${currentB.matrix.map((row,r)=>`
      <div class="trace-matrix-row">${row.map((x,c)=>`<div class="trace-matrix-cell ${focus[0]===r&&focus[1]===c?'focus':''}">${x}<span class="trace-matrix-index">${r},${c}</span></div>`).join('')}</div>`).join('')}</div>`;
    return;
  }

  if(step.queue){
    v.innerHTML=`<div class="trace-queue-label">先頭 → 末尾</div><div class="trace-queue">${step.queue.length?step.queue.map(x=>`<div class="trace-queue-item">${escapeHtml(x)}</div>`).join(''):'<div class="sub">空</div>'}</div>`;
    return;
  }

  if(currentB.list){
    const visited=step.visited||[];
    v.innerHTML=`<div class="trace-list">${currentB.list.map((node,i)=>`
      ${i?'<span class="trace-list-arrow">→</span>':''}
      <div class="trace-list-node ${step.currentNode===node.id?'current':''} ${visited.includes(node.id)?'visited':''}">
        <div class="trace-node-id">${node.id}</div><div class="trace-node-value">${node.value}</div>
      </div>`).join('')}<span class="trace-list-arrow">→ null</span></div>`;
    return;
  }

  if(step.bits){
    const labels={x:'x',mask:'mask',result:'AND'};
    v.innerHTML=`<div class="trace-bits">${Object.entries(step.bits).map(([k,val])=>`
      <div class="trace-bit-row"><div class="trace-bit-label">${labels[k]||escapeHtml(k)}</div><div class="trace-bit-value">${escapeHtml(val)}</div></div>`).join('')}</div>`;
    return;
  }

  if(step.object){
    const title=currentB.objectName||'object';
    v.innerHTML=`<div class="trace-object"><div class="trace-object-title">${escapeHtml(title)}</div>${Object.entries(step.object).map(([k,val])=>`
      <div class="trace-object-prop"><span>${escapeHtml(k)}</span><b>${escapeHtml(val)}</b></div>`).join('')}</div>`;
    return;
  }

  if(currentB.array){
    const arr=step.arrayState||currentB.array;
    v.innerHTML=`<div class="trace-array">${
      arr.map((x,i)=>`<div class="trace-array-cell ${step.focus===i?'focus':''} ${step.found===i?'found':''}">${x}<span class="trace-array-index">${i}</span></div>`).join('')
    }</div>${currentB.target!==undefined?`<div class="visit-path">target = ${currentB.target}</div>`:''}`;
    return;
  }

  if(step.stack){
    v.innerHTML=`<div class="sub" style="text-align:center;margin-bottom:6px">トップ</div><div class="trace-stack">${step.stack.map(x=>`<div class="trace-stack-item">${escapeHtml(x)}</div>`).join('')}</div>`;
    return;
  }

  if(currentB.tree){
    const visited=step.visited||[];
    const mark=n=>visited.includes(n)?`[${n}]`:n;
    v.innerHTML=`<div class="tree-view">       ${mark('A')}
      /   \\
    ${mark('B')}     ${mark('C')}
   / \\
 ${mark('D')}   ${mark('E')}</div>
 <div class="visit-path">出力：${escapeHtml(step.state?.output||'—')}</div>`;
    return;
  }

  v.innerHTML='<div class="sub" style="text-align:center">変数の変化を右上のSTATEで追いましょう。</div>';
}

function showBPrediction(pred){
  bPredictionSatisfied=false;
  const box=document.getElementById('predictionBox');
  box.classList.add('show');
  document.getElementById('predictionTitle').textContent='⚡ 次を予測：'+pred.q;
  const root=document.getElementById('predictionOptions');
  root.innerHTML='';
  pred.opts.forEach((o,i)=>{
    const b=document.createElement('button');
    b.className='prediction-option';
    b.textContent=o;
    b.onclick=()=>{
      if(i===pred.a){
        b.classList.add('good');
        bPredictionSatisfied=true;
        root.querySelectorAll('button').forEach(x=>x.disabled=true);
        document.getElementById('bTraceMessage').textContent=pred.explain||'予測した状態と実際の処理を対応させて確認しましょう。';
        popToast('予測正解！ +5 XP');
        profile.xp += 5;
        saveProfile();
      }else{
        b.classList.add('bad');
        popToast(pred.hint?`ヒント：${pred.hint}`:'現在の状態と次に実行する行を確認しましょう');
        setTimeout(()=>b.classList.remove('bad'),700);
      }
    };
    root.appendChild(b);
  });
}

function finishBExercise(){
  const old=profile.bProgress[currentB.id]||0;
  profile.bProgress[currentB.id]=100;
  profile.skills['アルゴリズム']=clamp((profile.skills['アルゴリズム']||50)+(old<100?3:1),0,100);
  profile.xp += old<100?80:20;
  saveProfile();

  document.getElementById('bCompleteXp').textContent=`+${old<100?80:20} XP`;
  document.getElementById('bCompleteText').textContent=`「${currentB.concept}」のトレースを完了しました。`;
  document.getElementById('bComplete').classList.add('show');
  document.getElementById('bStep').disabled=true;
  document.getElementById('bStep').textContent='✓ 完了';
  renderBGrid();
  updateSubjectBCompletionButton('bNextExercise');
}



