function showBFinalMenu(){
  stopBFinalTimer();
  ['bSelect','secSelect','bMockSelect'].forEach(id=>document.getElementById(id)?.classList.add('hidden'));
  ['bLab','secLab','bMockExam','bMockResult','bCompoundExam','bCompoundResult','secMockExam','secMockResult','bFinalExam','bFinalResult'].forEach(id=>document.getElementById(id)?.classList.remove('show'));
  document.getElementById('bFinalSelect')?.classList.remove('hidden');
  renderBFinalMenu();
}


const BFINAL_RESUME_KEY='fequest_bfinal_resume_v1';
function clearBFinalResume(){
  try{localStorage.removeItem(BFINAL_RESUME_KEY)}catch(e){}
}
function saveBFinalResume(){
  if(!bFinalItems?.length||!document.getElementById('bFinalExam')?.classList.contains('show'))return false;
  try{
    const payload={
      version:1,appVersion:APP_VERSION,
      items:bFinalItems,answers:bFinalAnswers,flags:[...bFinalFlags],index:bFinalIndex,
      expiresAt:Date.now()+Math.max(0,bFinalSeconds)*1000,
      startedAt:bFinalStartedAt||Date.now(),savedAt:Date.now()
    };
    localStorage.setItem(BFINAL_RESUME_KEY,JSON.stringify(payload));
    return true;
  }catch(e){console.warn('B final resume save failed',e);return false}
}
function readBFinalResume(){
  try{return JSON.parse(localStorage.getItem(BFINAL_RESUME_KEY)||'null')}catch(e){return null}
}
function restoreBFinalResume(){
  const s=readBFinalResume();
  if(!s||!Array.isArray(s.items)||s.items.length!==20||!Array.isArray(s.answers)||s.answers.length!==20)return false;
  const remain=Math.ceil((Number(s.expiresAt||0)-Date.now())/1000);
  if(remain<=0){clearBFinalResume();return false}
  bFinalItems=s.items;
  bFinalAnswers=s.answers;
  bFinalFlags=new Set(s.flags||[]);
  bFinalIndex=Math.max(0,Math.min(19,Number(s.index)||0));
  bFinalSeconds=Math.min(B_FINAL_SECONDS,remain);
  bFinalStartedAt=Number(s.startedAt)||Date.now();
  lastBFinalAttempt=null;
  setBMode('final');
  document.getElementById('bFinalSelect')?.classList.add('hidden');
  document.getElementById('bFinalResult')?.classList.remove('show');
  document.getElementById('bFinalExam')?.classList.add('show');
  showScreen('trace',{replaceHistory:true,instant:true});
  renderBFinalQuestion();
  startBFinalTimer();
  return true;
}

function startBFinal(){
  const days=examDaysRemaining();
  if(days!=null&&days>=0&&days<=3){popToast('試験直前は100分の総合実戦ではなく、今日の短い確認を優先します');showScreen('home');return;}
  clearBFinalResume();
  bFinalItems=buildBFinal();bFinalAnswers=Array(bFinalItems.length).fill(null);bFinalFlags=new Set();bFinalIndex=0;
  bFinalSeconds=B_FINAL_SECONDS;bFinalStartedAt=Date.now();lastBFinalAttempt=null;
  document.getElementById('bFinalSelect')?.classList.add('hidden');
  document.getElementById('bFinalResult')?.classList.remove('show');
  document.getElementById('bFinalExam')?.classList.add('show');
  renderBFinalQuestion();startBFinalTimer();saveBFinalResume();
}
function stopBFinalTimer(){if(bFinalTimerId){clearInterval(bFinalTimerId);bFinalTimerId=null}}
function startBFinalTimer(){
  stopBFinalTimer();updateBFinalTimer();
  bFinalTimerId=setInterval(()=>{bFinalSeconds--;updateBFinalTimer();if(bFinalSeconds>0&&bFinalSeconds%15===0)saveBFinalResume();if(bFinalSeconds<=0){stopBFinalTimer();finishBFinal(true)}},1000);
}
function updateBFinalTimer(){
  const t=document.getElementById('bFinalTimer');if(!t)return;
  t.textContent=bMockFormatTime(bFinalSeconds);
  t.classList.toggle('warn',bFinalSeconds<=15*60&&bFinalSeconds>5*60);
  t.classList.toggle('danger',bFinalSeconds<=5*60);
}

function finalAlgoDataHtml(item){
  return (item.data||[]).map(d=>`<div class="bfinal-data-card"><b>${escapeHtml(d.label||'補足')}</b>${escapeHtml(d.text||'')}</div>`).join('');
}

function renderBFinalQuestion(){
  const item=bFinalItems[bFinalIndex];if(!item)return;
  document.getElementById('bFinalTopMeta').textContent=`問題 ${bFinalIndex+1} / ${bFinalItems.length}`;
  document.getElementById('bFinalQNum').textContent=`Q${bFinalIndex+1}`;
  const type=document.getElementById('bFinalQType');
  type.textContent=item.kind==='security'?'情報セキュリティ':'擬似言語';
  type.classList.toggle('security',item.kind==='security');
  document.getElementById('bFinalQFormat').textContent=item.kind==='security'?bFinalFormatOf(item):`${item.domain||'擬似言語'}・${bFinalFormatOf(item)}`;

  const algo=document.getElementById('bFinalAlgoBlock'),sec=document.getElementById('bFinalSecurityBlock');
  if(item.kind==='algo'){
    algo.classList.remove('hidden');algo.hidden=false;
    sec.classList.add('hidden');sec.hidden=true;
    document.getElementById('bFinalAlgoContext').textContent=item.context||'';
    document.getElementById('bFinalCode').innerHTML=item.code.map((line,i)=>`<div class="bmock-code-line"><span class="ln">${i+1}</span><span>${escapeHtml(line)}</span></div>`).join('');
    document.getElementById('bFinalAlgoData').innerHTML=finalAlgoDataHtml(item);
  }else{
    algo.classList.add('hidden');algo.hidden=true;
    sec.classList.remove('hidden');sec.hidden=false;
    document.getElementById('bFinalSecIcon').textContent=item.incident.icon;
    document.getElementById('bFinalSecTitle').textContent=item.incident.title;
    document.getElementById('bFinalSecText').textContent=item.incident.text;
    document.getElementById('bFinalSecEvidence').innerHTML=securityMockEvidenceHtml(item);
  }

  document.getElementById('bFinalQuestion').textContent=item.q;
  const ans=bFinalAnswers[bFinalIndex];
  document.getElementById('bFinalOptions').innerHTML=item.options.map((op,i)=>`<button class="bfinal-option ${item.kind==='security'?'security':''} ${ans===i?'selected':''}" data-bfopt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(op)}</button>`).join('');
  document.querySelectorAll('[data-bfopt]').forEach(btn=>btn.onclick=()=>{bFinalAnswers[bFinalIndex]=Number(btn.dataset.bfopt);renderBFinalQuestion()});

  document.getElementById('bFinalPrev').disabled=bFinalIndex===0;
  document.getElementById('bFinalNext').textContent=bFinalIndex===bFinalItems.length-1?'提出へ':'次へ →';
  document.getElementById('bFinalFlag').classList.toggle('active',bFinalFlags.has(bFinalIndex));
  document.getElementById('bFinalFlag').textContent=bFinalFlags.has(bFinalIndex)?'★ 後で見る':'☆ 後で見る';
  document.getElementById('bFinalProgressMini').style.width=`${((bFinalIndex+1)/bFinalItems.length)*100}%`;
  renderBFinalNav();
}

function renderBFinalNav(){
  const root=document.getElementById('bFinalNavGrid');
  root.innerHTML=bFinalItems.map((item,i)=>`<button class="bfinal-nav-q ${item.kind==='security'?'security':'algo'} ${bFinalAnswers[i]!==null?'answered':''} ${bFinalFlags.has(i)?'flagged':''} ${i===bFinalIndex?'current':''}" data-bfq="${i}">${i+1}</button>`).join('');
  root.querySelectorAll('[data-bfq]').forEach(btn=>btn.onclick=()=>{bFinalIndex=Number(btn.dataset.bfq);renderBFinalQuestion()});
  const answered=bFinalAnswers.filter(x=>x!==null).length;
  const algo=bFinalItems.reduce((n,x,i)=>n+(x.kind==='algo'&&bFinalAnswers[i]!==null?1:0),0);
  const sec=bFinalItems.reduce((n,x,i)=>n+(x.kind==='security'&&bFinalAnswers[i]!==null?1:0),0);
  document.getElementById('bFinalAnswerCount').textContent=`${answered} / ${bFinalItems.length} 回答`;
  document.getElementById('bFinalAlgoAnswered').textContent=algo;document.getElementById('bFinalSecAnswered').textContent=sec;
  saveBFinalResume();
}

function askSubmitBFinal(){
  const blank=bFinalAnswers.filter(x=>x===null).length;
  if(confirm(blank?`未回答が${blank}問あります。総合実戦を提出しますか？`:'20問の回答を提出しますか？'))finishBFinal(false);
}


if(!profile.bFinalMistakeStats)profile.bFinalMistakeStats={};
function bFinalMistakeKey(d){return `${d.kind}:${d.sourceId}:${d.format}`;}
function bFinalReviewReasonMeta(reason,d){
  const m={
    'トレースミス':['TRACEで1行ずつ確認','途中状態を紙に書き、変数・配列の更新を1行ずつ追います。'],
    'コード理解':['複合問題で確認','空欄や処理目的を、コード全体の役割から判断する練習へ進みます。'],
    '読み違い':['条件を読み直す','設問が聞いている時点・対象・条件を先に囲ってからコードを読みます。'],
    '知識不足':[d.kind==='security'?'セキュリティ演習で確認':'学習モードで確認','用語や仕組みを短く整理してから、もう一度判断します。'],
    '時間不足':['時間を区切って再挑戦','一つの設問に粘りすぎず、後で戻る判断を練習します。']
  };return m[reason]||[d.kind==='security'?'セキュリティ演習へ':'学習モードへ','まず該当する学習モードで処理を確認します。'];
}
function bFinalAutoDiagnosis(a){
  const wrong=a.details.filter(d=>!d.ok),byFormat={},byDomain={};
  wrong.forEach(d=>{
    byFormat[d.format]=(byFormat[d.format]||0)+1;
    const domain=d.domain||(d.kind==='security'?'情報セキュリティ':'擬似言語');
    byDomain[domain]=(byDomain[domain]||0)+1;
  });
  const top=Object.entries(byFormat).sort((a,b)=>b[1]-a[1])[0];
  const topDomain=Object.entries(byDomain).sort((a,b)=>b[1]-a[1])[0];
  const secWrong=a.details.filter(d=>d.kind==='security'&&!d.ok).length,algoWrong=a.details.filter(d=>d.kind==='algo'&&!d.ok).length;
  const repeat=wrong.filter(d=>(profile.bFinalMistakeStats?.[bFinalMistakeKey(d)]?.misses||0)>=2).length;
  return {topFormat:top?.[0]||'—',topCount:top?.[1]||0,topDomain:topDomain?.[0]||'—',topDomainCount:topDomain?.[1]||0,secWrong,algoWrong,repeat};
}
function renderBFinalDiagnosis(a){
  const root=document.getElementById('bFinalDiagnosis');if(!root)return;const x=bFinalAutoDiagnosis(a);
  root.innerHTML=`<div class="bfinal-diagnosis-title">今回の総合実戦診断</div><div class="bfinal-diagnosis-grid">
    <div class="bfinal-diagnosis-item"><span>崩れた形式</span><b>${escapeHtml(x.topFormat)}</b><small>${x.topCount}問の誤答</small></div>
    <div class="bfinal-diagnosis-item"><span>弱点領域</span><b>${escapeHtml(x.topDomain)}</b><small>${x.topDomainCount}問の誤答</small></div>
    <div class="bfinal-diagnosis-item"><span>繰り返し誤答</span><b>${x.repeat}問</b><small>以前の総合実戦でも同じ型でつまずいた問題</small></div>
  </div>`;
}
function finishBFinal(timeUp=false){
  if(!bFinalItems.length)return;
  stopBFinalTimer();
  clearBFinalResume();
  const used=Math.min(B_FINAL_SECONDS,Math.max(0,Math.round((Date.now()-(bFinalStartedAt||Date.now()))/1000)));
  let correct=0,blank=0,algoCorrect=0,secCorrect=0;
  const details=bFinalItems.map((item,i)=>{
    const ans=bFinalAnswers[i],ok=ans===item.a;if(ok){correct++;if(item.kind==='algo')algoCorrect++;else secCorrect++;}if(ans===null)blank++;
    const key=item.kind==='security'?`sec:${item.sourceId}`:`algo:${item.sourceId}`;
    if(!profile.bFinalStats[key])profile.bFinalStats[key]={seen:0,correct:0,lastSeen:null};
    const st=profile.bFinalStats[key];st.seen++;if(ok)st.correct++;st.lastSeen=localDateISO(0);
    const detail={sourceId:item.sourceId,kind:item.kind,format:bFinalFormatOf(item),domain:item.kind==='security'?(item.concept||'情報セキュリティ'):(item.domain||'擬似言語'),title:item.title,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain,studyMode:item.studyMode};
    if(!ok){const mk=bFinalMistakeKey(detail);const ms=profile.bFinalMistakeStats[mk]||(profile.bFinalMistakeStats[mk]={misses:0,reasons:{},lastReason:null,last:null});ms.misses=(ms.misses||0)+1;ms.last=localDateISO(0);}
    return detail;
  });
  // Internal legacy practice points are retained only for saved-data compatibility and XP logic.
  // The UI shows raw correct count/rate and does not present this as an IRT or exam score.
  const points=correct*50,rate=Math.round(correct/20*100),earned=correct*10+(points>=600?40:0);
  profile.xp=(profile.xp||0)+earned;
  const attempt={date:localDateISO(0),total:20,correct,blank,points,rate,seconds:used,timeUp,algoCorrect,secCorrect,details};
  profile.bFinalHistory=[attempt,...(profile.bFinalHistory||[])].slice(0,20);lastBFinalAttempt=attempt;saveProfile();

  document.getElementById('bFinalExam')?.classList.remove('show');document.getElementById('bFinalResult')?.classList.add('show');
  renderBFinalResult(attempt,earned);
}

const B_FINAL_DOMAIN_REMEDIATION={
  '制御':'nested_loop',
  '一次元配列':'array_reverse',
  '二次元配列':'matrix_find',
  '再帰・関数':'recursion',
  '木構造':'tree_dfs',
  'オブジェクト指向':'object_counter',
  'リスト':'linked_list',
  'スタック・キュー':'stack_ops',
  'ビット列':'bit_mask',
  '探索・整列':'binary_search_b'
};

function bFinalRemediationTarget(mode,source,domain){
  if(mode==='security')return {mode:'security',id:source};
  if(mode==='trace')return {mode:'trace',id:source};
  if(mode==='exam')return {mode:'trace',id:B_FINAL_DOMAIN_REMEDIATION[domain]||'binary_search_b'};
  if(mode==='compound')return {mode:'compound',id:source};
  return {mode:'mock',id:null};
}

function renderBFinalResult(a,earned){
  document.getElementById('bFinalResultPoints').textContent=`${a.rate}%`;
  document.getElementById('bFinalResultRaw').textContent=`${a.correct} / 20 正解`;
  document.getElementById('bFinalResultMessage').textContent=a.rate>=80?`かなり安定しています。時間配分を保ったまま精度を維持しましょう。+${earned} XP`:a.rate>=60?`練習上の目安には届いています。誤答分野を潰して余裕を作りましょう。+${earned} XP`:a.rate>=45?`あと少しです。誤答を「トレース」「読解」「判断」に分けて復習しましょう。+${earned} XP`:`学習モードへ戻り、途中状態を書き出す練習から積み直すのがおすすめです。+${earned} XP`;
  document.getElementById('bFinalStatCorrect').textContent=a.correct;
  document.getElementById('bFinalStatWrong').textContent=20-a.correct-a.blank;
  document.getElementById('bFinalStatBlank').textContent=a.blank;
  document.getElementById('bFinalStatTime').textContent=bMockFormatTime(a.seconds);
  document.getElementById('bFinalAlgoScore').textContent=`${a.algoCorrect} / 16`;
  document.getElementById('bFinalSecScore').textContent=`${a.secCorrect} / 4`;
  renderBFinalDiagnosis(a);

  const formats=[...new Set(a.details.map(d=>d.format))];
  document.getElementById('bFinalFormatBreakdown').innerHTML=formats.map(f=>{
    const rows=a.details.filter(d=>d.format===f),n=rows.filter(d=>d.ok).length,pct=Math.round(n/rows.length*100);
    return `<div class="bfinal-format-row"><div class="bfinal-format-label">${escapeHtml(f)}</div><div class="bfinal-format-bar"><div class="bfinal-format-fill" style="width:${pct}%"></div></div><div class="bfinal-format-score">${n}/${rows.length}</div></div>`;
  }).join('');

  document.getElementById('bFinalReviewList').innerHTML=a.details.map((d,i)=>{
    const mk=bFinalMistakeKey(d),ms=profile.bFinalMistakeStats?.[mk],reason=ms?.lastReason||'';const meta=bFinalReviewReasonMeta(reason,d);
    return `<div class="bfinal-review-item ${d.ok?'correct':'wrong'}"><div class="bfinal-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span>${d.kind==='security'?'🛡️ '+escapeHtml(d.domain||'セキュリティ'):'💻 '+escapeHtml(d.domain||'擬似言語')+' / '+escapeHtml(d.format)} / ${d.ok?'✓ 正解':'✕ 要復習'}</span></div><div class="bfinal-review-q">${escapeHtml(d.q)}</div><div class="bfinal-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="bfinal-review-e">${escapeHtml(d.explain)}</div>${d.ok?'':`<div class="bfinal-review-reason"><div class="bfinal-review-reason-title">なぜ崩れましたか？</div><div class="bfinal-review-reason-chips">${['トレースミス','コード理解','読み違い','知識不足','時間不足'].map(r=>`<button class="bfinal-review-reason-chip ${reason===r?'picked':''}" data-bfreason="${r}" data-bfkey="${escapeHtml(mk)}">${r}</button>`).join('')}</div></div><div class="bfinal-review-action" data-bfaction="${escapeHtml(mk)}"><b>${escapeHtml(meta[0])}</b>${escapeHtml(meta[1])}</div><button class="bfinal-review-study smart" data-bfinalstudy="${escapeHtml(d.studyMode)}" data-bfinalsource="${escapeHtml(d.sourceId)}" data-bfinaldomain="${escapeHtml(d.domain||'')}">${escapeHtml(meta[0])} →</button>`}</div>`;
  }).join('');
  document.querySelectorAll('[data-bfreason]').forEach(btn=>btn.onclick=()=>{
    const key=btn.dataset.bfkey,reason=btn.dataset.bfreason,st=profile.bFinalMistakeStats[key];if(!st)return;
    if(st.lastReason&&st.reasons?.[st.lastReason])st.reasons[st.lastReason]=Math.max(0,st.reasons[st.lastReason]-1);
    st.lastReason=reason;st.reasons=st.reasons||{};st.reasons[reason]=(st.reasons[reason]||0)+1;st.last=localDateISO(0);saveProfile();renderBFinalResult(a,0);
  });
  document.querySelectorAll('[data-bfinalstudy]').forEach(btn=>btn.onclick=()=>{
    document.getElementById('bFinalResult')?.classList.remove('show');
    const target=bFinalRemediationTarget(btn.dataset.bfinalstudy,btn.dataset.bfinalsource,btn.dataset.bfinaldomain);
    if(target.mode==='security'){
      setBMode('security');startSecurityScenario(target.id);
    }else if(target.mode==='trace'){
      setBMode('trace');startBExercise(target.id);
    }else if(target.mode==='compound'){
      setBMode('mock');startCompoundChallenge();
    }else{
      setBMode('mock');showBMockMenu();
    }
  });
}

