document.getElementById('bFinalRetry')?.addEventListener('click',startBFinal);
document.getElementById('bFinalBackMenu')?.addEventListener('click',continueSubjectBFlow);
document.getElementById('bFinalSubmit')?.addEventListener('click',askSubmitBFinal);
document.getElementById('bFinalPrev')?.addEventListener('click',()=>{if(bFinalIndex>0){bFinalIndex--;renderBFinalQuestion()}});
document.getElementById('bFinalNext')?.addEventListener('click',()=>{if(bFinalIndex<bFinalItems.length-1){bFinalIndex++;renderBFinalQuestion()}else askSubmitBFinal()});
