// ===== v37: Security ミニ模試 =====
const SECURITY_MOCK_COUNT=8;
const SECURITY_MOCK_SECONDS=20*60;
const SECURITY_MOCK_QUOTAS={'基礎':2,'標準':4,'応用':2};

if(!profile.securityMockHistory) profile.securityMockHistory=[];
if(!profile.securityMockStats) profile.securityMockStats={};

function ensureSecurityMockStats(){
  SECURITY_SCENARIOS.forEach(s=>{
    if(!profile.securityMockStats[s.id]) profile.securityMockStats[s.id]={seen:0,correct:0,lastSeen:null};
  });
}

let secMockItems=[],secMockAnswers=[],secMockFlags=new Set(),secMockIndex=0;
let secMockSeconds=SECURITY_MOCK_SECONDS,secMockTimerId=null,secMockStartedAt=null,lastSecurityMockAttempt=null;

function randomizeSecurityMockItem(s,stepIndex){
  const step=s.steps[stepIndex];
  const correctText=step.options[step.a];
  const options=shuffled([...step.options]);
  return {
    id:`${s.id}:${stepIndex}`,scenarioId:s.id,title:s.title,level:s.level,concept:s.concept,
    incident:structuredClone(s.incident),evidence:structuredClone(s.evidence||null),log:s.log||null,risk:!!s.risk,
    q:step.q,options,a:options.indexOf(correctText),correctText,explain:step.explain
  };
}

function securityAppliedStepIndex(s){
  // 実戦では「攻撃名を当てる」だけの最初の設問を避け、
  // 対応・根拠・対策を判断する2問目/3問目を使う。
  const candidates=(s.steps||[]).map((_,i)=>i).filter(i=>i>=1);
  return candidates[Math.floor(Math.random()*candidates.length)] ?? 0;
}

function securityScenarioSeen(s,stats){
  return stats?.[s.id]?.seen||0;
}
function sortSecurityScenarioPool(pool,stats){
  return [...pool].sort((a,b)=>{
    const sa=securityScenarioSeen(a,stats),sb=securityScenarioSeen(b,stats);
    if(sa!==sb)return sa-sb;
    const la=stats?.[a.id]?.lastSeen||'',lb=stats?.[b.id]?.lastSeen||'';
    if(la!==lb)return la.localeCompare(lb);
    return Math.random()-.5;
  });
}

function buildSecurityMock(){
  ensureSecurityMockStats();
  const selected=[];
  const used=new Set();

  // ログ読解を最低2問（標準1・応用1）必ず含める。
  const requiredLogLevels=['標準','応用'];
  requiredLogLevels.forEach(level=>{
    const pool=sortSecurityScenarioPool(
      SECURITY_SCENARIOS.filter(s=>s.level===level&&s.log&&!used.has(s.id)),
      profile.securityMockStats
    );
    const pick=pool[0];
    if(pick){selected.push(pick);used.add(pick.id);}
  });

  // 基礎2・標準4・応用2の配分を保ったまま残りを埋める。
  Object.entries(SECURITY_MOCK_QUOTAS).forEach(([level,n])=>{
    const already=selected.filter(s=>s.level===level).length;
    const need=Math.max(0,n-already);
    const pool=sortSecurityScenarioPool(
      SECURITY_SCENARIOS.filter(s=>s.level===level&&!used.has(s.id)),
      profile.securityMockStats
    );
    pool.slice(0,need).forEach(s=>{selected.push(s);used.add(s.id)});
  });

  return shuffled(selected).map(s=>randomizeSecurityMockItem(s,securityAppliedStepIndex(s)));
}

function securityMockEvidenceHtml(item){
  if(item.log)return `<div class="log-box">${escapeHtml(item.log)}</div>`;
  if(item.risk)return `<div class="risk-matrix">
    <div class="risk-cell"></div><div class="risk-cell">影響 低</div><div class="risk-cell">影響 中</div><div class="risk-cell">影響 高</div>
    <div class="risk-cell">可能性 高</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div><div class="risk-cell high">R1：高</div>
    <div class="risk-cell">可能性 中</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div>
    <div class="risk-cell">可能性 低</div><div class="risk-cell low">低</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div>
  </div>`;
  return `<div class="evidence-list">${(item.evidence||[]).map(e=>`<div class="evidence-item"><span class="ev-icon">${e.icon}</span><div>${e.text}</div></div>`).join('')}</div>`;
}

function startSecurityMock(){
  secMockItems=buildSecurityMock();
  secMockAnswers=Array(secMockItems.length).fill(null);
  secMockFlags=new Set();secMockIndex=0;secMockSeconds=SECURITY_MOCK_SECONDS;secMockStartedAt=Date.now();
  document.getElementById('secSelect')?.classList.add('hidden');
  document.getElementById('secMockResult')?.classList.remove('show');
  document.getElementById('secMockExam')?.classList.add('show');
  renderSecurityMockQuestion();startSecurityMockTimer();
}

function stopSecurityMockTimer(){if(secMockTimerId){clearInterval(secMockTimerId);secMockTimerId=null}}
function startSecurityMockTimer(){
  stopSecurityMockTimer();updateSecurityMockTimer();
  secMockTimerId=setInterval(()=>{secMockSeconds--;updateSecurityMockTimer();if(secMockSeconds<=0){stopSecurityMockTimer();finishSecurityMock(true)}},1000);
}
function updateSecurityMockTimer(){
  const t=document.getElementById('secMockTimer');if(!t)return;
  t.textContent=bMockFormatTime(secMockSeconds);
  t.classList.toggle('warn',secMockSeconds<=300&&secMockSeconds>120);
  t.classList.toggle('danger',secMockSeconds<=120);
}

function renderSecurityMockQuestion(){
  const item=secMockItems[secMockIndex];
  if(!item)return;
  document.getElementById('secMockQNum').textContent=`問題 ${secMockIndex+1} / ${secMockItems.length}`;
  document.getElementById('secMockIncidentIcon').textContent=item.incident.icon;
  document.getElementById('secMockIncidentTitle').textContent=item.incident.title;
  document.getElementById('secMockIncidentText').textContent=item.incident.text;
  document.getElementById('secMockEvidence').innerHTML=securityMockEvidenceHtml(item);
  document.getElementById('secMockQuestion').textContent=item.q;
  const ans=secMockAnswers[secMockIndex];
  document.getElementById('secMockOptions').innerHTML=item.options.map((op,i)=>`<button class="secmock-option ${ans===i?'selected':''}" data-smopt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(op)}</button>`).join('');
  document.querySelectorAll('[data-smopt]').forEach(btn=>btn.onclick=()=>{secMockAnswers[secMockIndex]=Number(btn.dataset.smopt);renderSecurityMockQuestion()});
  document.getElementById('secMockPrev').disabled=secMockIndex===0;
  document.getElementById('secMockNext').textContent=secMockIndex===secMockItems.length-1?'提出へ':'次へ →';
  document.getElementById('secMockFlag').classList.toggle('active',secMockFlags.has(secMockIndex));
  document.getElementById('secMockFlag').textContent=secMockFlags.has(secMockIndex)?'★ 後で見る':'☆ 後で見る';
  renderSecurityMockNav();
}
function renderSecurityMockNav(){
  const root=document.getElementById('secMockNavGrid');
  root.innerHTML=secMockItems.map((_,i)=>`<button class="bmock-nav-q ${secMockAnswers[i]!==null?'answered':''} ${secMockFlags.has(i)?'flagged':''} ${i===secMockIndex?'current':''}" data-smq="${i}">${i+1}</button>`).join('');
  root.querySelectorAll('[data-smq]').forEach(btn=>btn.onclick=()=>{secMockIndex=Number(btn.dataset.smq);renderSecurityMockQuestion()});
  document.getElementById('secMockAnswerCount').textContent=`${secMockAnswers.filter(x=>x!==null).length} / ${secMockItems.length} 回答`;
}
function askSubmitSecurityMock(){
  const blank=secMockAnswers.filter(x=>x===null).length;
  if(confirm(blank?`未回答が${blank}問あります。提出しますか？`:'回答を提出しますか？'))finishSecurityMock(false);
}
function finishSecurityMock(timeUp=false){
  if(!secMockItems.length)return;
  stopSecurityMockTimer();
  const used=Math.min(SECURITY_MOCK_SECONDS,Math.max(0,Math.round((Date.now()-(secMockStartedAt||Date.now()))/1000)));
  let correct=0,blank=0;
  const details=secMockItems.map((item,i)=>{
    const ans=secMockAnswers[i],ok=ans===item.a;
    if(ok)correct++;if(ans===null)blank++;
    const st=profile.securityMockStats[item.scenarioId]||(profile.securityMockStats[item.scenarioId]={seen:0,correct:0,lastSeen:null});
    st.seen=(st.seen||0)+1;if(ok)st.correct=(st.correct||0)+1;st.lastSeen=localDateISO(0);
    return {scenarioId:item.scenarioId,title:item.title,level:item.level,concept:item.concept,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain};
  });
  const rate=Math.round(correct/secMockItems.length*100),earned=correct*8+(rate>=75?20:0);
  profile.xp=(profile.xp||0)+earned;
  if(profile.skills?.['セキュリティ']!==undefined)profile.skills['セキュリティ']=clamp(profile.skills['セキュリティ']+(rate>=75?2:rate>=50?1:0),0,100);
  const attempt={
    date:localDateISO(0),total:secMockItems.length,correct,blank,rate,seconds:used,timeUp,
    levels:Object.fromEntries(['基礎','標準','応用'].map(level=>{const r=details.filter(d=>d.level===level);return[level,{correct:r.filter(d=>d.ok).length,total:r.length}]})),
    details
  };
  profile.securityMockHistory=[attempt,...(profile.securityMockHistory||[])].slice(0,20);
  lastSecurityMockAttempt=attempt;saveProfile();

  document.getElementById('secMockExam')?.classList.remove('show');
  document.getElementById('secMockResult')?.classList.add('show');
  document.getElementById('secMockResultScore').textContent=`${correct} / ${secMockItems.length}`;
  document.getElementById('secMockResultMessage').textContent=rate>=88?`状況判断がかなり安定しています。+${earned} XP`:rate>=75?`実戦で十分戦える水準に近づいています。+${earned} XP`:rate>=50?`誤答したケースを学習モードで確認しましょう。+${earned} XP`:`まずは誤答ケースの「何を最優先するか」を整理しましょう。+${earned} XP`;
  document.getElementById('secMockCorrect').textContent=correct;
  document.getElementById('secMockWrong').textContent=secMockItems.length-correct-blank;
  document.getElementById('secMockBlank').textContent=blank;
  document.getElementById('secMockTime').textContent=bMockFormatTime(used);
  document.getElementById('secMockBreakdown').innerHTML=['基礎','標準','応用'].map(level=>{const x=attempt.levels[level],pct=x.total?Math.round(x.correct/x.total*100):0;return `<div class="secmock-break-row"><div class="secmock-break-label">${level}</div><div class="secmock-break-bar"><div class="secmock-break-fill" style="width:${pct}%"></div></div><div class="secmock-break-score">${x.correct}/${x.total}</div></div>`}).join('');
  document.getElementById('secMockReviewList').innerHTML=details.map((d,i)=>`<div class="secmock-review-item ${d.ok?'correct':'wrong'}"><div class="secmock-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span>${d.ok?'✓ 正解':'✕ 要復習'}</span></div><div class="secmock-review-q">${escapeHtml(d.q)}</div><div class="secmock-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="secmock-review-e">${escapeHtml(d.explain)}</div>${d.ok?'':`<button class="secmock-review-study" data-sstudy="${escapeHtml(d.scenarioId)}">学習モードで確認 →</button>`}</div>`).join('');
  document.querySelectorAll('[data-sstudy]').forEach(btn=>btn.onclick=()=>{document.getElementById('secMockResult')?.classList.remove('show');setBMode('security');startSecurityScenario(btn.dataset.sstudy)});
}

