function setBMode(mode){
  document.querySelectorAll('.b-mode-switcher').forEach(d=>d.open=false);
  const traceMode=mode==='trace',securityMode=mode==='security',mockMode=mode==='mock',finalMode=mode==='final';
  document.getElementById('bSelect')?.classList.toggle('hidden',!traceMode);
  document.getElementById('secSelect')?.classList.toggle('hidden',!securityMode);
  document.getElementById('bMockSelect')?.classList.toggle('hidden',!mockMode);
  document.getElementById('bFinalSelect')?.classList.toggle('hidden',!finalMode);
  document.getElementById('bLab')?.classList.remove('show');
  document.getElementById('secLab')?.classList.remove('show');
  document.getElementById('bMockExam')?.classList.remove('show');
  document.getElementById('bMockResult')?.classList.remove('show');
  document.getElementById('bCompoundExam')?.classList.remove('show');
  document.getElementById('bCompoundResult')?.classList.remove('show');
  document.getElementById('secMockExam')?.classList.remove('show');
  document.getElementById('secMockResult')?.classList.remove('show');
  document.getElementById('bFinalExam')?.classList.remove('show');
  document.getElementById('bFinalResult')?.classList.remove('show');
  stopSecurityMockTimer();stopBFinalTimer();
  document.querySelectorAll('[data-bmode]').forEach(b=>b.classList.toggle('active',b.dataset.bmode===mode));
  if(traceMode)renderBGrid();else if(securityMode)renderSecGrid();else if(mockMode)renderBMockMenu();else if(finalMode)renderBFinalMenu();
}
document.querySelectorAll('[data-bmode]').forEach(b=>{
  b.addEventListener('click',()=>setBMode(b.dataset.bmode));
});


let currentSecFilter='all';
function securityNextRecommendation(){
  const sc=SECURITY_SCENARIOS.find(x=>(profile.securityBProgress?.[x.id]||0)<100);
  if(sc)return {id:sc.id,title:sc.title,level:sc.level,concept:sc.concept};
  return null;
}
function renderSecurityNextCard(){
  const title=document.getElementById('secNextTitle'),desc=document.getElementById('secNextDesc'),action=document.getElementById('secNextAction');
  if(!title||!desc||!action)return;
  const next=securityNextRecommendation();
  if(next){
    title.textContent=next.title;desc.textContent=`${next.level}・${next.concept}`;action.textContent='このケースを始める →';action.onclick=()=>startSecurityScenario(next.id);
  }else{
    const rec=subjectBHubRecommendation();
    title.textContent='セキュリティ15ケースは完了しました';
    desc.textContent=rec.mode==='securityMock'?'次は8問のミニ模試でヒントなしの判断を確認します。':'短い実戦演習へ進めます。';
    action.textContent=rec.mode==='securityMock'?'ミニ模試へ →':'次の科目Bへ →';action.onclick=()=>launchSubjectBRecommendation(rec);
  }
  const fold=document.getElementById('secPracticeFold');
  if(fold){const done=SECURITY_SCENARIOS.filter(s=>(profile.securityBProgress?.[s.id]||0)>=100).length;fold.classList.toggle('recommended',done===SECURITY_SCENARIOS.length);}
}
