function renderSecGrid(){
  const root=document.getElementById('secScenarioGrid');
  if(!root) return;
  root.innerHTML='';
  const done=SECURITY_SCENARIOS.filter(s=>(profile.securityBProgress?.[s.id]||0)>=100).length;
  const visible=SECURITY_SCENARIOS.filter(s=>currentSecFilter==='all'||s.level===currentSecFilter);
  visible.forEach(s=>{
    const pct=profile.securityBProgress?.[s.id]||0;
    const diffClass=s.level==='標準'?'medium':s.level==='応用'?'hard':'';
    const card=document.createElement('div');
    const nextId=securityNextRecommendation()?.id;
    card.className='sec-card'+(pct>=100?' done':'')+(s.id===nextId?' b-next-highlight':'');
    card.innerHTML=`
      <div class="sec-card-top">
        <div class="sec-card-icon">${s.icon}</div>
        <div>
          <div class="sec-card-title">${s.title}</div>
          <div class="sec-card-meta">${s.concept}</div>
        </div>
      </div>
      <div class="sec-card-desc">${s.desc}</div>
      <div class="sec-card-bottom">
        <span class="difficulty ${diffClass}">${s.level}</span>
        ${pct>=100?'<span class="sec-check">✓ 完了</span>':''}
        <button class="sec-start" data-sec="${s.id}">${pct>=100?'もう一度':'開始'}</button>
      </div>`;
    root.appendChild(card);
  });
  document.getElementById('secProgressText').textContent=`${done} / ${SECURITY_SCENARIOS.length}`;
  root.querySelectorAll('[data-sec]').forEach(b=>b.onclick=()=>startSecurityScenario(b.dataset.sec));
  renderSecurityNextCard();
  if(typeof renderSubjectBHub==='function')renderSubjectBHub();
}
