function renderSecEvidence(s){
  const root=document.getElementById('secEvidence');
  if(s.log){
    root.innerHTML=`<div class="log-box">${escapeHtml(s.log)}</div>`;
    return;
  }
  if(s.risk){
    root.innerHTML=`
      <div class="risk-matrix">
        <div class="risk-cell"></div><div class="risk-cell">影響 低</div><div class="risk-cell">影響 中</div><div class="risk-cell">影響 高</div>
        <div class="risk-cell">可能性 高</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div><div class="risk-cell high">R1：最優先候補</div>
        <div class="risk-cell">可能性 中</div><div class="risk-cell low">R3</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div>
        <div class="risk-cell">可能性 低</div><div class="risk-cell low">R2</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div>
      </div>`;
    return;
  }
  root.innerHTML=`<div class="evidence-list">${
    (s.evidence||[]).map(e=>`<div class="evidence-item"><span class="ev-icon">${e.icon}</span><div>${e.text}</div></div>`).join('')
  }</div>`;
}

function startSecurityScenario(id){
  currentSec=SECURITY_SCENARIOS.find(s=>s.id===id);
  if(!currentSec) return;
  secStepIndex=0;
  secAnswered=false;
  secCorrect=0;
  secFirstTryCorrect=0;
  secAttempts=0;

  document.getElementById('secSelect').classList.add('hidden');
  document.getElementById('bSelect').classList.add('hidden');
  document.getElementById('bLab').classList.remove('show');
  document.getElementById('secLab').classList.add('show');
  document.getElementById('secComplete').classList.remove('show');

  document.getElementById('secLabTitle').textContent=currentSec.title;
  document.getElementById('secLabMeta').textContent=`科目B・${currentSec.concept}・${currentSec.level}`;
  document.getElementById('secIncidentIcon').textContent=currentSec.incident.icon;
  document.getElementById('secIncidentTitle').textContent=currentSec.incident.title;
  document.getElementById('secIncidentBadge').textContent=currentSec.incident.badge;
  document.getElementById('secIncidentText').textContent=currentSec.incident.text;
  renderSecEvidence(currentSec);
  renderSecDecision();
}

function renderSecDecision(){
  const step=currentSec.steps[secStepIndex];
  secAnswered=false;
  secAttempts=0;
  document.getElementById('secDecisionNum').textContent=secStepIndex+1;
  document.getElementById('secQuestion').textContent=step.q;
  document.getElementById('secFeedback').className='decision-feedback';
  document.getElementById('secFeedback').textContent='';
  document.getElementById('secNext').classList.remove('show');
  document.getElementById('secCounter').textContent=`${secStepIndex+1} / ${currentSec.steps.length}`;
  document.getElementById('secStepProgress').style.width=`${(secStepIndex/currentSec.steps.length)*100}%`;

  const root=document.getElementById('secOptions');
  root.innerHTML='';
  step.options.forEach((op,i)=>{
    const b=document.createElement('button');
    b.className='decision-option';
    b.textContent=`${String.fromCharCode(65+i)}. ${op}`;
    b.onclick=()=>answerSecDecision(i,b);
    root.appendChild(b);
  });
}

function answerSecDecision(i,button){
  if(secAnswered) return;
  const step=currentSec.steps[secStepIndex];
  const ok=i===step.a;
  const firstTry=secAttempts===0;
  secAttempts++;

  const buttons=[...document.querySelectorAll('#secOptions .decision-option')];
  const fb=document.getElementById('secFeedback');

  if(!ok && secAttempts===1){
    button.disabled=true;
    button.classList.add('bad');
    fb.className='decision-feedback show bad';
    fb.innerHTML=`<b>もう一度考えてみましょう</b><div class="sec-retry-hint">💡 ${escapeHtml(step.hint||'この状況で守るべき情報・被害拡大防止・証拠保全のどれを優先するか整理してください。')}</div>`;
    return;
  }

  secAnswered=true;
  buttons.forEach((b,idx)=>{
    b.disabled=true;
    if(idx===step.a) b.classList.add('good');
    else if(idx===i && !ok) b.classList.add('bad');
  });

  if(ok){
    secCorrect++;
    if(firstTry){
      secFirstTryCorrect++;
      profile.xp += 8;
      popToast('判断正解！ +8 XP');
    }else{
      profile.xp += 4;
      popToast('再挑戦で正解！ +4 XP');
    }
  }
  saveProfile();

  fb.className='decision-feedback show'+(ok?'':' bad');
  fb.innerHTML=`<b>${ok?'⭕ 適切です':'❌ 正解を確認しましょう'}</b><div style="margin-top:6px">${escapeHtml(step.explain)}</div>`;

  document.getElementById('secStepProgress').style.width=`${((secStepIndex+1)/currentSec.steps.length)*100}%`;
  const next=document.getElementById('secNext');
  next.textContent=secStepIndex===currentSec.steps.length-1?'演習結果を見る':'次の判断へ →';
  next.classList.add('show');
}

document.getElementById('secNext')?.addEventListener('click',()=>{
  if(!secAnswered) return;
  if(secStepIndex<currentSec.steps.length-1){
    secStepIndex++;
    renderSecDecision();
  }else{
    finishSecurityScenario();
  }
});

function finishSecurityScenario(){
  const old=profile.securityBProgress[currentSec.id]||0;
  profile.securityBProgress[currentSec.id]=100;
  profile.skills['セキュリティ']=clamp((profile.skills['セキュリティ']||50)+(old<100?3:1),0,100);
  const bonus=old<100?60:15;
  profile.xp += bonus;
  saveProfile();

  document.getElementById('secCompleteXp').textContent=`+${bonus} XP`;
  document.getElementById('secCompleteText').textContent=`${secFirstTryCorrect} / ${currentSec.steps.length} 個を最初の回答で正解しました。再挑戦を含む最終正解は ${secCorrect} / ${currentSec.steps.length} です。`;
  document.getElementById('secCompleteSummary').innerHTML=`<b>今回の要点</b><br>${currentSec.summary}`;
  document.getElementById('secComplete').classList.add('show');
  document.querySelector('.decision-panel').style.display='none';
  renderSecGrid();
  updateSubjectBCompletionButton('secReturnList');
}

