// ===== v10: Adaptive daily scheduler / roadmap =====
if(!profile.settings) profile.settings={studyMinutes:60,examDate:''};
if(!profile.dailyPlans) profile.dailyPlans={};
if(!profile.activity) profile.activity={};
if(!profile.settings.studyMinutes) profile.settings.studyMinutes=60;
if(profile.settings.autoPace==null) profile.settings.autoPace=true;
if(profile.settings.variantReview==null) profile.settings.variantReview=true;
saveProfile();

function dateKey(d=new Date()){
  const x=new Date(d);
  const y=x.getFullYear();
  const m=String(x.getMonth()+1).padStart(2,'0');
  const day=String(x.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
}
function addActivity(minutes,type='study'){
  const k=dateKey();
  if(!profile.activity[k]) profile.activity[k]={minutes:0,events:[]};
  profile.activity[k].minutes += Number(minutes)||0;
  profile.activity[k].events.push({type,time:new Date().toISOString()});
  profile.activity[k].events=profile.activity[k].events.slice(-30);
  saveProfile();
}
function getDailyRecord(){
  const k=dateKey();
  if(!profile.dailyPlans[k]) profile.dailyPlans[k]={done:{},createdAt:new Date().toISOString()};
  const rec=profile.dailyPlans[k];
  rec.done=rec.done||{};
  // v65: old "lesson/prescription" completion keys are unified into one learning slot.
  if((rec.done.lesson||rec.done.prescription)&&rec.done.learn==null)rec.done.learn=true;
  return rec;
}
function dailyTaskSlot(t){
  if(!t)return '';
  if(t.type==='lesson'||t.type==='prescription'||t.type==='finalFocus')return 'learn';
  if(t.type==='taperReview')return 'review';
  if(t.type==='warmup')return 'boss';
  return t.type;
}
function persistProfileSilently(){
  if(!appBootComplete){bootProfileSavePending=true;return true;}
  if(profileWriteBlocked||profileConflictBlocked){restoreCommittedProfileInMemory(false);return false;}
  try{if(profileCommittedChecksum&&profileIntegrityChecksum(profile)===profileCommittedChecksum)return true}catch(_e){}
  if(!acquireProfileWriteLease()){restoreCommittedProfileInMemory(false);return false;}
  let saved=false;
  try{
    profile=stampProfileForSave(profile);
    const result=writeCurrentProfile(profile,{preservePrevious:true});
    profile=result.profile;rememberCommittedProfile(profile);clearProfileSaveFailure();
    saved=true;
  }catch(e){
    restoreCommittedProfileInMemory(false);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT')markProfileConflict();
    else{profileWriteBlocked=true;console.warn('silent save failed',e);setTimeout(()=>refreshPwaHealth?.(),0);}
    return false;
  }finally{releaseProfileWriteLease()}
  try{queueRecoveryCheckpoint('autosave',false)}catch(e){console.warn('Recovery checkpoint queue failed',e)}
  return saved;
}

function snapshotDailyTasks(tasks){
  return (tasks||[]).map(t=>structuredClone({...t,slot:dailyTaskSlot(t)}));
}
function ensureTodayPlanSnapshot(force=false){
  const rec=getDailyRecord();
  const stale=rec.planVersion!=='v98';
  if(force||!Array.isArray(rec.tasks)||!rec.tasks.length||stale){
    const old=snapshotDailyTasks(Array.isArray(rec.tasks)?rec.tasks:[]);
    const fresh=snapshotDailyTasks(buildTodayTasks());
    const done=rec.done||{};
    rec.tasks=fresh.map(t=>{
      const slot=dailyTaskSlot(t);
      if(done[slot])return old.find(x=>dailyTaskSlot(x)===slot)||t;
      return t;
    });
    rec.targetMinutes=rec.tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0);
    rec.planVersion='v98';
    rec.plannedAt=rec.plannedAt||new Date().toISOString();
    if(stale)rec.replannedAt=new Date().toISOString();
    persistProfileSilently();
  }
  return rec.tasks;
}
function dailyTaskDone(rec,t){
  const slot=dailyTaskSlot(t);
  return !!(rec.done?.[slot]||rec.done?.[t.type]);
}
function dailyTaskMatches(t,type,meta={}){
  if(!t)return false;
  if(type==='review'||type==='boss')return t.type===type;
  if(type==='taperReview')return t.type==='taperReview';
  if(type==='warmup')return t.type==='warmup';
  if(type==='lesson')return t.type==='lesson'&&(!meta.lessonId||t.lessonId===meta.lessonId);
  if(type==='prescription')return t.type==='prescription'&&(!meta.mode||rxMode(t.rx)===meta.mode);
  if(type==='finalFocus')return t.type==='finalFocus';
  if(type==='subjectB'){
    // 残り3日以内は科目Bを「learn枠のfinalFocus」として置くことがある。
    if(t.type==='finalFocus'&&t.focus?.kind==='subjectB'){
      const b=t.focus.b||{};
      if(meta.mode&&b.mode!==meta.mode)return false;
      if((meta.mode==='trace'||meta.mode==='security')&&meta.id&&b.id!==meta.id)return false;
      return true;
    }
    if(t.type!=='subjectB')return false;
    if(meta.mode&&t.bmode!==meta.mode)return false;
    if((meta.mode==='trace'||meta.mode==='security')&&meta.id&&t.bid!==meta.id)return false;
    return true;
  }
  return false;
}
function markDailyTask(type,meta={}){
  const rec=getDailyRecord(),tasks=ensureTodayPlanSnapshot();
  const task=tasks.find(t=>dailyTaskMatches(t,type,meta));
  if(!task)return false;
  const slot=dailyTaskSlot(task);
  if(!rec.done[slot]){
    rec.done[slot]=true;
    addActivity(task.minutes,slot);
  }else{
    persistProfileSilently();
  }
  renderDailyPlan();
  renderPlannerScreen();
  return true;
}
function rebuildTodayPlanPreservingDone(){
  const rec=getDailyRecord(),old=snapshotDailyTasks(ensureTodayPlanSnapshot()),fresh=snapshotDailyTasks(buildTodayTasks());
  const done=rec.done||{};
  rec.tasks=fresh.map(t=>{
    const slot=dailyTaskSlot(t);
    if(done[slot]){
      return old.find(x=>dailyTaskSlot(x)===slot)||t;
    }
    return t;
  });
  rec.targetMinutes=rec.tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0);
  rec.planVersion='v98';
  rec.replannedAt=new Date().toISOString();
  persistProfileSilently();
  renderDailyPlan();
  renderAllocation();
}

function lessonCompletionAverage(ids=null){
  const all=ids || (typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS||{}));
  if(!all.length) return 0;
  return Math.round(all.reduce((s,id)=>s+(profile.lessonProgress?.[id]||0),0)/all.length);
}
function objectCompletion(obj,totalExpected=1){
  const vals=Object.values(obj||{});
  if(!vals.length) return 0;
  const total=Math.max(Number(totalExpected)||1,vals.length);
  return Math.round(vals.reduce((s,v)=>s+(v||0),0)/total);
}
function recentQuizRate(){
  const s=(profile.sessions||[]).slice(0,5);
  if(!s.length) return 0;
  return Math.round(s.reduce((a,x)=>a+(x.rate||0),0)/s.length);
}
function recentAverageRate(rows,limit=3){
  const vals=(rows||[]).slice(0,limit).map(x=>Number(x.rate)).filter(Number.isFinite);
  return vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0;
}
function readinessComponents(){
  const lesson=lessonCompletionAverage();
  const skillVals=sortedSkills().map(x=>x[1]);
  const skill=skillVals.length?Math.round(skillVals.reduce((a,b)=>a+b,0)/skillVals.length):0;
  const quiz=recentQuizRate();
  const cognitive=subjectACognitiveEvidence();
  const aPractice=Math.round(skill*.35 + quiz*.30 + cognitive*.35);

  const fullMocks=(profile.mockHistory||[]).filter(x=>x.mode==='full');
  const halfMocks=(profile.mockHistory||[]).filter(x=>x.mode==='half');
  const aMock=fullMocks.length?recentAverageRate(fullMocks,3):Math.round(recentAverageRate(halfMocks,2)*.8);

  const bAlgo=objectCompletion(profile.bProgress,B_EXERCISES.length);
  const bSec=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
  const bTraining=Math.round((bAlgo+bSec)/2);
  const bExam=recentAverageRate(profile.bFinalHistory||[],3);

  const mem=memoryHealth();
  const memoryEvidence=mem.attempted?Math.round(mem.avg*Math.min(1,mem.attempted/60)):0;

  return {lesson,aPractice,aMock,bTraining,bExam,memoryEvidence,cognitive};
}
function calcReadiness(){
  const c=readinessComponents();
  // FE QUEST独自の「受験準備の仕上がり」指標。合格確率ではない。
  const raw=c.lesson*.25 + c.aPractice*.20 + c.aMock*.20 + c.bTraining*.15 + c.bExam*.15 + c.memoryEvidence*.05;
  return Math.round(clamp(raw,0,100));
}


function recentConsistency(rows,limit,avgTarget,minTarget){
  const vals=(rows||[]).slice(0,limit).map(x=>Number(x.rate)).filter(Number.isFinite);
  const avg=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0;
  const min=vals.length?Math.min(...vals):0;
  return {count:vals.length,avg,min,passed:vals.length>=limit&&avg>=avgTarget&&min>=minTarget};
}

function courseMasteryStatus(){
  ensureChapterMasteryProfile();
  const topicStates=CORE_A_CURRICULUM.map(t=>({topic:t,state:coreTopicLearningState(t.id)}));
  syncMasteryRecoveryHistory(topicStates);
  const recovering=topicStates.filter(x=>!!masteryRecoveryInfo(x.topic.id)).length;
  const master=topicStates.filter(x=>x.state.key==='master').length;
  const stable=topicStates.filter(x=>['stable','master'].includes(x.state.key)).length;
  const lessonDone=CORE_A_CURRICULUM.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
  const chapterPassed=CORE_A_CHAPTERS.filter(ch=>chapterIntegrationEvidence(ch).passed).length;

  const skillRows=sortedSkills();
  const weakest=skillRows[0]||['アルゴリズム',0];
  const mem=memoryHealth();

  const fullMocks=(profile.mockHistory||[]).filter(x=>x.mode==='full');
  const aMock=recentConsistency(fullMocks,2,75,70);
  const bFinal=recentConsistency(profile.bFinalHistory||[],2,70,65);

  const bAlgo=objectCompletion(profile.bProgress,B_EXERCISES.length);
  const bSec=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
  const bTraining=Math.round((bAlgo+bSec)/2);

  const gates=[
    {id:'lesson',name:'科目A教材',passed:lessonDone===CORE_A_CURRICULUM.length,value:`${lessonDone}/${CORE_A_CURRICULUM.length}`},
    {id:'topics',name:'テーマ定着',passed:stable>=117,value:`${stable}/130（習得 ${master}）`},
    {id:'chapters',name:'章末統合',passed:chapterPassed===21,value:`${chapterPassed}/21`},
    {id:'weak',name:'最低分野習熟',passed:Number(weakest[1])>=70,value:`${weakest[0]} ${Math.round(weakest[1])}%`},
    {id:'memory',name:'復習定着',passed:mem.attempted>0&&mem.avg>=85&&mem.due<=10,value:`保持 ${mem.avg}%・要復習 ${mem.due}`},
    {id:'bTraining',name:'科目B学習',passed:bTraining>=90,value:`${bTraining}%`},
    {id:'aMock',name:'科目Aフル模試',passed:aMock.passed,value:aMock.count>=2?`直近2回 平均${aMock.avg}%・最低${aMock.min}%`:`${aMock.count}/2回`},
    {id:'bFinal',name:'科目B総合実戦',passed:bFinal.passed,value:bFinal.count>=2?`直近2回 平均${bFinal.avg}%・最低${bFinal.min}%`:`${bFinal.count}/2回`}
  ];

  return {
    topicStates,master,recovering,stable,lessonDone,chapterPassed,weakest,mem,bTraining,aMock,bFinal,gates,
    passed:gates.filter(g=>g.passed).length,
    ready:gates.every(g=>g.passed)
  };
}

function nextUnpassedChapter(){
  const rows=CORE_A_CHAPTERS.map(ch=>{
    const e=chapterIntegrationEvidence(ch);
    const topics=CORE_A_CURRICULUM.filter(t=>t.chapter===ch);
    const done=topics.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
    const settled=topics.filter(t=>['stable','master'].includes(coreTopicLearningState(t.id).key)).length;
    return {ch,e,done,total:topics.length,settled};
  }).filter(x=>!x.e.passed);
  rows.sort((a,b)=>{
    const ar=a.done/a.total,br=b.done/b.total;
    if(ar!==br)return br-ar;
    if(a.e.bestRate!==b.e.bestRate)return b.e.bestRate-a.e.bestRate;
    return a.ch-b.ch;
  });
  return rows[0]||null;
}

function nextMasterTopicCandidate(){
  const rank={stable:0,understood:1,review:2,learning:3,new:4,master:9};
  return courseMasteryStatus().topicStates
    .filter(x=>x.state.key!=='master')
    .sort((a,b)=>{
      const aRecovery=masteryRecoveryInfo(a.topic.id)?0:1,bRecovery=masteryRecoveryInfo(b.topic.id)?0:1;
      if(aRecovery!==bRecovery)return aRecovery-bRecovery;
      const ra=rank[a.state.key]??8,rb=rank[b.state.key]??8;
      if(ra!==rb)return ra-rb;
      const ar=a.state.retention??0,br=b.state.retention??0;
      return br-ar;
    })[0]||null;
}

function finalFocusRecommendation(status=courseMasteryStatus()){
  const days=examDaysRemaining();
  const urgentPhase=days!=null&&days>=0&&days<=14;
  const deepTaper=days!=null&&days>=0&&days<=3;
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;

  if(days===0){
    return {kind:'warmup',icon:'☀️',title:'今日は3問だけ確認',desc:'新規教材も長時間模試も追加しません。既習3問で感覚だけ整えます。',button:'ウォームアップ3問'};
  }
  if(days===1){
    if(routes||due)return {kind:'review',icon:'🧠',title:'前日は復習だけ',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。長時間模試や新規教材は追加しません。`,button:'5問まで確認'};
    return {kind:'warmup',icon:'🌙',title:'前日は軽い確認だけ',desc:'既習3問だけ確認し、新しい範囲は増やしません。',button:'ウォームアップ3問'};
  }

  if((routes||due)&&((urgentPhase)||(status.mem.due>10))){
    return {kind:'review',icon:'🧠',title:'最優先：復習待ちを解消',desc:`復習ルート ${routes}件・期限/低保持 ${due}問。判断問題を優先して戻します。`,button:deepTaper?'5問まで確認':'復習を始める'};
  }

  // 残り3日以内は、未完了教材があっても新規範囲を広げない。
  if(!deepTaper&&status.lessonDone<130){
    const lesson=nextLessonChoice();
    return {kind:'lesson',icon:'📘',title:'未完了教材を埋める',desc:`残り ${130-status.lessonDone}テーマ。弱い分野から未完了教材を進めます。`,button:'次の教材へ',lessonId:lesson.id};
  }

  if(status.bTraining<90&&!urgentPhase){
    const b=nextBChoice(20);
    return {kind:'subjectB',icon:'💻',title:'科目Bの基礎演習を完成',desc:`科目B学習 ${status.bTraining}% 。未完了のアルゴリズム/セキュリティを優先します。`,button:'科目Bを続ける',b};
  }

  if(deepTaper){
    const weakEvidence=categoryCognitiveEvidence(status.weakest[0]);
    if(Number(status.weakest[1])<70){
      const level=weakEvidence.weakest.level;
      return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${level}を短く補強`,desc:'残り3日以内は新規教材やフル模試ではなく、既習の最弱思考を10問だけ確認します。',button:`${level}を10問`,cat:status.weakest[0],level};
    }
    if(status.bTraining<90){
      const b=nextBChoice(10);
      return {kind:'subjectB',icon:'💻',title:'科目Bを1セットだけ確認',desc:'100分総合実戦は追加せず、既存の短い演習を一つ確認します。',button:'科目Bを確認',b};
    }
    const chapter=nextReadyUnpassedChapter();
    if(chapter){
      return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を短く統合確認`,desc:'学習済みの章だけを確認します。未学習範囲は混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
    }
    const x=nextMasterTopicCandidate();
    if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
      return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:'既習テーマの保持を整えます。新しい知識は増やしません。',button:'テーマ演習',topicId:x.topic.id};
    }
    return {kind:'warmup',icon:'✅',title:'既習3問だけ確認',desc:'ここからは仕上がりを崩さないことを優先します。',button:'ウォームアップ3問'};
  }

  if(urgentPhase&&!status.aMock.passed){
    return {kind:'aMock',icon:'🏁',title:'科目Aを本番時間で確認',desc:'フル模試2回の安定条件が未達です。90分を確保できる日に本番型で確認します。',button:'フル模試90分を始める',long:true};
  }

  if(urgentPhase&&!status.bFinal.passed){
    return {kind:'bFinal',icon:'💻',title:'科目B総合実戦で確認',desc:'直近2回の安定条件が未達です。100分を確保してアルゴリズム＋セキュリティを通しで確認します。',button:'科目B総合100分を始める',long:true};
  }

  const weakEvidence=categoryCognitiveEvidence(status.weakest[0]);
  if(Number(status.weakest[1])<70){
    const level=weakEvidence.weakest.level;
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${level}を補強`,desc:`最低分野 ${Math.round(status.weakest[1])}% 。最も弱い思考段階「${level}」を10問で直接補強します。`,button:`${level}を10問`,cat:status.weakest[0],level};
  }

  if(status.chapterPassed<21){
    const row=nextUnpassedChapter();
    return {kind:'chapter',icon:'🧩',title:`第${row?.ch||1}章の統合確認`,desc:`章末統合 ${status.chapterPassed}/21。80%以上到達＋直近70%以上維持を習得判定の統合証拠にします。`,button:`第${row?.ch||1}章を12問で確認`,chapter:row?.ch||1};
  }

  if(status.bTraining<90){
    const b=nextBChoice(20);
    return {kind:'subjectB',icon:'💻',title:'科目Bの基礎演習を完成',desc:`科目B学習 ${status.bTraining}% 。未完了演習を優先します。`,button:'科目Bを続ける',b};
  }

  if(!status.aMock.passed){
    return {kind:'aMock',icon:'🏁',title:'科目Aフル模試を安定させる',desc:'直近2回で平均75%以上・各70%以上をFE QUESTの総仕上げ基準にしています。',button:'フル模試90分を始める',long:true};
  }
  if(!status.bFinal.passed){
    return {kind:'bFinal',icon:'💻',title:'科目B総合実戦を安定させる',desc:'直近2回で平均70%以上・各65%以上をFE QUESTの総仕上げ基準にしています。',button:'科目B総合100分を始める',long:true};
  }

  if(status.stable<117||status.master<130){
    const x=nextMasterTopicCandidate();
    if(x){
      if(x.state.key==='stable'&&!x.state.chapterReady){
        return {kind:'chapter',icon:'🧩',title:`第${x.topic.chapter}章の章末確認`,desc:`「${x.topic.title}」はテーマ内では習得水準ですが、章横断の確認が残っています。`,button:`第${x.topic.chapter}章を確認`,chapter:x.topic.chapter};
      }
      return masteryRecoveryInfo(x.topic.id)?{kind:'topic',icon:'↩️',title:`${x.topic.title}の習得状態を戻す`,desc:`${masteryRecoveryReason(x.state)} 現在「${x.state.label}」。`,button:'必要な復習を始める',topicId:x.topic.id}:{kind:'topic',icon:'⭐',title:`${x.topic.title}を習得状態へ`,desc:`現在「${x.state.label}」。保持と高次問題の証拠を整えます。`,button:'テーマ演習を始める',topicId:x.topic.id};
    }
  }

  if(!status.gates.find(g=>g.id==='memory')?.passed){
    return {kind:'review',icon:'🧠',title:'記憶を最終メンテナンス',desc:`推定保持 ${status.mem.avg}%・要復習 ${status.mem.due}問。新規学習より保持の回復を優先します。`,button:'復習を始める'};
  }

  const ev=categoryCognitiveEvidence(status.weakest[0]);
  return {kind:'cognitive',icon:'✅',title:'総仕上げ維持',desc:`主要ゲートを満たしています。最も弱い「${status.weakest[0]}・${ev.weakest.level}」を短く維持します。`,button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}


function shortFinalFocusRecommendation(status=courseMasteryStatus()){
  if(status.chapterPassed<21){
    const row=nextUnpassedChapter();
    return {kind:'chapter',icon:'🧩',title:`第${row?.ch||1}章の統合確認`,desc:'教材完了後は章横断で見分けられるかを確認します。',button:`第${row?.ch||1}章を確認`,chapter:row?.ch||1};
  }
  const ev=categoryCognitiveEvidence(status.weakest[0]);
  if(Number(status.weakest[1])<78){
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${ev.weakest.level}補強`,desc:'新規教材ではなく、最も弱い思考段階を直接10問で補強します。',button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
  }
  const x=nextMasterTopicCandidate();
  if(x){
    return masteryRecoveryInfo(x.topic.id)?{kind:'topic',icon:'↩️',title:`${x.topic.title}の習得状態を戻す`,desc:masteryRecoveryReason(x.state),button:'必要な復習',topicId:x.topic.id}:{kind:'topic',icon:'⭐',title:`${x.topic.title}を習得状態へ`,desc:`現在「${x.state.label}」。定着証拠を積み上げます。`,button:'テーマ演習',topicId:x.topic.id};
  }
  return {kind:'cognitive',icon:'✅',title:`${status.weakest[0]}・${ev.weakest.level}維持`,desc:'全体の仕上がりを維持する短時間演習です。',button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}

function launchFinalFocus(f=finalFocusRecommendation()){
  if(!f)return;
  if(f.kind==='warmup'){showScreen('problems');startQuiz('warmup');return;}
  if(f.kind==='review'){
    const days=examDaysRemaining();
    if(days!=null&&days>=0&&days<=3){showScreen('problems');startQuiz('taperreview');return;}
    const j=actionableReviewJourneys()[0];
    if(j)startJourneyAction(j.id);
    else{showScreen('problems');startQuiz('review');}
    return;
  }
  if(f.kind==='lesson'){startLesson(f.lessonId);return;}
  if(f.kind==='chapter'){showScreen('problems');startQuiz(`corechapter:${f.chapter}`);return;}
  if(f.kind==='topic'){showScreen('problems');startQuiz(`coretopic:${f.topicId}`);return;}
  if(f.kind==='cognitive'){showScreen('problems');startQuiz(`cogcat:${f.cat}:${f.level}`);return;}
  if(f.kind==='subjectB'){
    showScreen('trace');
    const b=f.b||nextBChoice(20);
    if(b.mode==='trace'){setBMode('trace');if(b.id)startBExercise(b.id);}
    else if(b.mode==='security'){setBMode('security');if(b.id)startSecurityScenario(b.id);}
    else if(b.mode==='compound'){setBMode('mock');startCompoundChallenge();}
    else if(b.mode==='securityMock'){setBMode('security');startSecurityMock();}
    return;
  }
  if(f.kind==='aMock'){showScreen('mock');startMock('full');return;}
  if(f.kind==='bFinal'){showScreen('trace');setBMode('final');startBFinal();return;}
}

let currentFinalFocus=null;
function renderFinalMasterPanel(){
  const summary=document.getElementById('finalMasterSummary');
  const gates=document.getElementById('finalMasterGates');
  const note=document.getElementById('finalFocusNote');
  const btn=document.getElementById('finalFocusAction');
  if(!summary||!gates||!note||!btn)return;

  const st=courseMasteryStatus();
  currentFinalFocus=finalFocusRecommendation(st);
  summary.innerHTML=`<b>${st.ready?'✅ 総仕上げ基準 8/8':'🎯 総仕上げ基準 '+st.passed+'/8'}</b><br>習得 ${st.master}/130・定着以上 ${st.stable}/130・章末統合 ${st.chapterPassed}/21${st.recovering?`・習得状態を再確認中 ${st.recovering}`:''}。<br><span class="sub">習得状態は記憶保持に応じて動的に変わります。崩れたテーマは必要な証拠を優先して戻します。FE QUEST独自の学習完了基準で、合格確率や公式の合格基準ではありません。</span>`;
  gates.innerHTML=st.gates.map(g=>`<div class="readiness-part"><span>${g.passed?'✓':'•'} ${escapeHtml(g.name)}</span><b>${escapeHtml(g.value)}</b></div>`).join('');
  note.innerHTML=`<b>${currentFinalFocus.icon} 次に優先：</b> ${escapeHtml(currentFinalFocus.title)}<br>${escapeHtml(currentFinalFocus.desc)}${currentFinalFocus.long?'<br><span class="sub">通常クエストへ上乗せせず、その日のメイン学習としてまとまった時間を確保する実戦メニューです。</span>':''}`;
  btn.textContent=currentFinalFocus.button;
  btn.onclick=()=>launchFinalFocus(currentFinalFocus);
}

function examDaysRemaining(){
  const val=profile.settings?.examDate;if(!val)return null;
  const target=new Date(val+'T12:00:00'),now=new Date();now.setHours(12,0,0,0);
  return Math.ceil((target-now)/86400000);
}
function examStudyPhase(days=examDaysRemaining()){
  if(days==null)return {id:'normal',name:'通常学習',icon:'📘',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days<0)return {id:'expired',name:'受験日経過',icon:'📅',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days>90)return {id:'foundation',name:'基礎拡張期',icon:'🌱',ratios:{review:.15,lesson:.35,subjectB:.30,boss:.20},allowNew:true,allowLongExam:true};
  if(days>30)return {id:'build',name:'実力形成期',icon:'🧩',ratios:{review:.20,lesson:.25,subjectB:.35,boss:.20},allowNew:true,allowLongExam:true};
  if(days>14)return {id:'finish',name:'仕上げ期',icon:'🎯',ratios:{review:.25,lesson:.15,subjectB:.35,boss:.25},allowNew:true,allowLongExam:true};
  if(days>7)return {id:'finalPractice',name:'直前演習期',icon:'🏁',ratios:{review:.30,lesson:.10,subjectB:.30,boss:.30},allowNew:true,allowLongExam:true};
  if(days>3)return {id:'taper',name:'直前調整期',icon:'🧠',ratios:{review:.35,lesson:.25,subjectB:.20,boss:.20},allowNew:true,allowLongExam:true};
  if(days>1)return {id:'protect',name:'仕上がり保護期',icon:'🛡️',ratios:{review:.40,lesson:.40,subjectB:0,boss:.20},allowNew:false,allowLongExam:false};
  if(days===1)return {id:'eve',name:'前日確認',icon:'🌙',ratios:{review:.67,lesson:0,subjectB:0,boss:.33},allowNew:false,allowLongExam:false};
  return {id:'examDay',name:'受験当日',icon:'☀️',ratios:{review:0,lesson:0,subjectB:0,boss:1},allowNew:false,allowLongExam:false};
}
function taperStudyCap(days=examDaysRemaining()){
  if(days==null||days<0||days>7)return null;
  if(days>=4)return 45;
  if(days>=2)return 30;
  if(days===1)return 15;
  return 10;
}
function roundUp5(n){return Math.ceil((Number(n)||0)/5)*5}
function allocateByRatios(total,ratios){
  total=Math.max(20,Math.round(Number(total)||60));
  const keys=['review','lesson','subjectB','boss'],out={};let used=0;
  keys.forEach((k,i)=>{
    if(i===keys.length-1){out[k]=Math.max(5,total-used);return;}
    out[k]=Math.max(5,Math.round(total*(ratios[k]||0)/5)*5);used+=out[k];
  });
  while(Object.values(out).reduce((a,b)=>a+b,0)>total){
    const k=keys.slice(0,-1).sort((a,b)=>out[b]-out[a]).find(k=>out[k]>5);if(!k)break;out[k]-=5;
  }
  while(Object.values(out).reduce((a,b)=>a+b,0)<total){
    const k=[...keys].sort((a,b)=>(ratios[b]||0)-(ratios[a]||0))[0];out[k]+=5;
  }
  return out;
}
function estimateRemainingStudyMinutes(){
  let m=0;
  (typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS||{})).forEach(id=>{const p=clamp(profile.lessonProgress?.[id]||0,0,100);m+=(1-p/100)*14;});
  (QUESTION_BANK||[]).forEach(q=>{if(!((profile.qStats?.[q.id]?.attempts||0)>0))m+=2.5;});
  (B_EXERCISES||[]).forEach(x=>{const p=clamp(profile.bProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  (SECURITY_SCENARIOS||[]).forEach(x=>{const p=clamp(profile.securityBProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  const a=(profile.mockHistory||[]).filter(x=>x.mode==='full').length,b=(profile.bFinalHistory||[]).length;
  m+=Math.max(0,2-a)*90+Math.max(0,2-b)*100+Math.max(0,1-(profile.bMockHistory||[]).length)*40+Math.max(0,1-(profile.securityMockHistory||[]).length)*20+Math.max(0,3-(profile.bCompoundHistory||[]).length)*20;
  const active=activeReviewJourneys().length;
  m+=Math.min(240,active*8+dueQuestions().length*3);
  return Math.max(0,Math.round(m));
}
function recentCalendarPace(days=14){
  const today=new Date();today.setHours(12,0,0,0);let total=0,activeDays=0;
  for(let i=0;i<days;i++){const d=new Date(today);d.setDate(d.getDate()-i);const min=Number(profile.activity?.[dateKey(d)]?.minutes)||0;total+=min;if(min>0)activeDays++;}
  const existing=Object.keys(profile.activity||{}).filter(k=>(profile.activity[k]?.minutes||0)>0).sort();
  let observedDays=0;
  if(existing.length){const first=new Date(existing[0]+'T12:00:00');observedDays=Math.min(days,Math.max(1,Math.floor((today-first)/86400000)+1));}
  return {total,activeDays,observedDays,enough:activeDays>=3&&observedDays>=4,avg:observedDays?total/observedDays:0};
}
function examPaceStatus(){
  const days=examDaysRemaining(),baseline=Number(profile.settings?.studyMinutes)||60,remaining=estimateRemainingStudyMinutes(),recent=recentCalendarPace(),phase=examStudyPhase(days);
  if(days==null)return {hasExam:false,baseline,effective:baseline,remaining,recent,phase};
  if(days<0)return {hasExam:true,expired:true,days,baseline,effective:baseline,remaining,recent,phase};
  const available=Math.max(1,days),required=remaining/available,currentPace=recent.enough?recent.avg:baseline,paceSource=recent.enough?'recent':'plan';
  const projectedDays=currentPace>0?Math.ceil(remaining/currentPace):9999,projectedDate=new Date();projectedDate.setHours(12,0,0,0);projectedDate.setDate(projectedDate.getDate()+projectedDays);
  const slack=available-projectedDays;
  let status='danger';
  if(required<=0||currentPace>=required*1.20)status='good';else if(currentPace>=required*.95)status='ok';else if(currentPace>=required*.75)status='warn';
  const auto=profile.settings?.autoPace!==false,suggested=Math.max(baseline,roundUp5(required*1.10));
  const cap=taperStudyCap(days);
  const taper=cap!=null;
  const normalEffective=auto?Math.min(120,suggested):baseline;
  // 残り7日以内は「残学習量を全部消化する」ための追い込みを止める。
  // 標準時間が短い利用者は増やさず、長い利用者だけ段階的に上限を下げる。
  const effective=taper?Math.min(baseline,cap):normalEffective;
  const adjustedDays=effective>0?Math.ceil(remaining/effective):9999,maxDate=new Date();maxDate.setHours(12,0,0,0);maxDate.setDate(maxDate.getDate()+Math.ceil(remaining/120));
  return {hasExam:true,expired:false,days,baseline,remaining,recent,phase,required,currentPace,paceSource,projectedDays,projectedDate,slack,status,auto,effective,canRecover:adjustedDays<=available,maxDate,taper,taperCap:cap};
}
function effectiveStudyMinutes(){const p=examPaceStatus();return p.hasExam&&!p.expired?p.effective:(Number(profile.settings?.studyMinutes)||60);}
function taperTaskAllocation(total,days){
  total=Math.max(5,Math.round(Number(total)||10));
  if(days<=0)return {review:0,lesson:0,subjectB:0,boss:total};
  if(days===1)return {review:Math.max(5,total-5),lesson:0,subjectB:0,boss:Math.min(5,total)};
  if(days<=3)return {review:10,lesson:Math.max(5,total-15),subjectB:0,boss:5};
  if(total<=30)return {review:10,lesson:10,subjectB:5,boss:5};
  return {review:15,lesson:10,subjectB:10,boss:Math.max(5,total-35)};
}
function taskAllocation(total){
  total=Number(total)||effectiveStudyMinutes();const days=examDaysRemaining();
  if(days!=null&&days>=0&&days<=6)return taperTaskAllocation(total,days);
  if(days==null){if(total===30)return {review:5,lesson:10,subjectB:10,boss:5};if(total===45)return {review:5,lesson:15,subjectB:15,boss:10};if(total===90)return {review:15,lesson:30,subjectB:30,boss:15};if(total===60)return {review:10,lesson:20,subjectB:20,boss:10};}
  return allocateByRatios(total,examStudyPhase(days).ratios);
}

function weakestSkill(){
  return sortedSkills()[0]?.[0] || 'アルゴリズム';
}
function nextLessonChoice(){
  const weakOrder=sortedSkills().map(x=>x[0]);
  for(const skill of weakOrder){
    const ids=CORE_A_IDS.filter(id=>LESSONS[id].skill===skill);
    const incomplete=ids.find(id=>(profile.lessonProgress?.[id]||0)<100);
    if(incomplete) return {id:incomplete,skill,title:LESSONS[incomplete].title};
  }
  return {id:null,skill:weakOrder[0]||'基礎理論',title:'科目A教材 130テーマ完了',complete:true};
}
function nextBChoice(minutes=20){
  const algoTotal=B_EXERCISES.length;
  const secTotal=SECURITY_SCENARIOS.length;
  const algoDone=B_EXERCISES.filter(x=>(profile.bProgress?.[x.id]||0)>=100).length;
  const secDone=SECURITY_SCENARIOS.filter(x=>(profile.securityBProgress?.[x.id]||0)>=100).length;
  const algoRate=algoDone/Math.max(1,algoTotal);
  const secRate=secDone/Math.max(1,secTotal);

  if(algoDone<algoTotal || secDone<secTotal){
    if(algoRate<=secRate && algoDone<algoTotal){
      const ex=B_EXERCISES.find(x=>(profile.bProgress?.[x.id]||0)<100) || B_EXERCISES[0];
      return {mode:'trace',id:ex?.id,title:ex?.title||'アルゴリズムトレース'};
    }
    const sc=SECURITY_SCENARIOS.find(x=>(profile.securityBProgress?.[x.id]||0)<100) || SECURITY_SCENARIOS[0];
    return {mode:'security',id:sc?.id,title:sc?.title||'セキュリティ演習'};
  }

  // 通常の20分枠に100分の総合実戦を自動割当しない。
  // 基礎演習完了後は20分の複合演習とセキュリティ実戦を交互に回す。
  const compoundRuns=(profile.bCompoundHistory||[]).length;
  const securityRuns=(profile.securityMockHistory||[]).length;
  if(compoundRuns<=securityRuns)return {mode:'compound',id:null,title:'複合問題・3問'};
  return {mode:'securityMock',id:null,title:'セキュリティ ミニ模試'};
}

function nextReadyUnpassedChapter(){
  const rows=CORE_A_CHAPTERS.map(ch=>{
    const topics=CORE_A_CURRICULUM.filter(t=>t.chapter===ch);
    const done=topics.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
    return {ch,done,total:topics.length,e:chapterIntegrationEvidence(ch)};
  }).filter(x=>x.done===x.total&&!x.e.passed);
  rows.sort((a,b)=>(b.e.bestRate||0)-(a.e.bestRate||0)||a.ch-b.ch);
  return rows[0]||null;
}

function taperFocusRecommendation(days,status=courseMasteryStatus()){
  const ev=categoryCognitiveEvidence(status.weakest[0]);

  // 残り4〜6日は、教材進捗が90%未満なら未学習を1テーマだけ許容。
  // 3日前以降は新規教材を増やさず、既習内容の穴だけを塞ぐ。
  if(days>=4&&status.lessonDone<117){
    const lesson=nextLessonChoice();
    if(lesson?.id)return {kind:'lesson',icon:'📘',title:'未完了教材を1テーマだけ',desc:`教材 ${status.lessonDone}/130。直前に広げすぎず、今日は「${lesson.title}」だけ進めます。`,button:'教材を開く',lessonId:lesson.id};
  }

  if(Number(status.weakest[1])<70){
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${ev.weakest.level}を補強`,desc:`最低分野 ${Math.round(status.weakest[1])}% 。新規範囲ではなく弱い思考を10問で戻します。`,button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
  }

  // 3日前以降は独立した科目B枠を置かないため、Bが弱い場合はこの枠で短く確認。
  if(days<=3&&status.bTraining<90){
    const b=nextBChoice(10);
    return {kind:'subjectB',icon:'💻',title:'科目Bを短く確認',desc:`科目B学習 ${status.bTraining}% 。長時間実戦ではなく未完了の基礎演習を1つ確認します。`,button:'科目Bを確認',b};
  }

  const chapter=nextReadyUnpassedChapter();
  if(chapter){
    return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を統合確認`,desc:'学習済みの章だけを12問で確認します。未学習範囲を直前に混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
  }

  const x=nextMasterTopicCandidate();
  if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
    return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:`現在「${x.state.label}」。既習テーマの保持だけを整えます。`,button:'テーマ演習',topicId:x.topic.id};
  }

  return {kind:'cognitive',icon:'✅',title:`${status.weakest[0]}・${ev.weakest.level}を維持`,desc:'新しい範囲へ広げず、既習の最弱思考を短く確認します。',button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}

function chooseTaperReviewQuestions(n=5){
  ensureQuestionProfile();
  const due=dueQuestions();
  const used=new Set();
  const out=[];
  const add=q=>{if(q&&!used.has(q.id)&&out.length<n){out.push(q);used.add(q.id);}};
  due.slice(0,n).forEach(add);
  if(out.length<n){
    trackedQuestionPool()
      .filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!used.has(q.id)&&!questionHasActiveJourney(q.id))
      .sort((a,b)=>reviewUrgency(b)-reviewUrgency(a))
      .slice(0,n-out.length).forEach(add);
  }
  if(out.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-out.length).forEach(add);
  }
  return out.map(buildReviewItem);
}

function chooseExamWarmupQuestions(n=3){
  ensureQuestionProfile();
  const attempted=QUESTION_BANK.filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!questionHasActiveJourney(q.id));
  const stable=attempted.filter(q=>{
    const r=memoryRetention(profile.qStats[q.id]);
    return r!=null&&r>=80;
  });
  const source=stable.length?stable:attempted;
  const selected=[],usedCats=new Set(),used=new Set();
  const ranked=shuffled(source).sort((a,b)=>{
    const ar=memoryRetention(profile.qStats[a.id])??0,br=memoryRetention(profile.qStats[b.id])??0;
    const cognitiveRank={'想起':0,'適用':1,'判断':2};
    const difficultyRank={'基礎':0,'標準':1,'実戦':2};
    const as=(cognitiveRank[a.cognitiveLevel]??2)*20+(difficultyRank[a.difficulty]??1)*8+Math.abs(ar-90);
    const bs=(cognitiveRank[b.cognitiveLevel]??2)*20+(difficultyRank[b.difficulty]??1)*8+Math.abs(br-90);
    // 当日は「できる問題を軽く解く」ことが目的。想起・基礎を優先し、難しい判断問題は最後にする。
    return as-bs;
  });
  for(const q of ranked){
    if(selected.length>=n)break;
    if(usedCats.has(q.cat))continue;
    selected.push(q);used.add(q.id);usedCats.add(q.cat);
  }
  for(const q of ranked){
    if(selected.length>=n)break;
    if(used.has(q.id))continue;
    selected.push(q);used.add(q.id);
  }
  // 学習履歴が全くない特殊ケースだけ、基礎の想起問題を最小限使う。
  if(selected.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-selected.length).forEach(q=>selected.push(q));
  }
  return selected.slice(0,n);
}

function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

function buildTodayTasks(){
  const daysNow=examDaysRemaining();
  const totalNow=effectiveStudyMinutes();
  if(daysNow!=null&&daysNow>=0&&daysNow<=7)return buildTaperTodayTasks(daysNow,totalNow);
  const alloc=taskAllocation(totalNow);
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;
  const lesson=nextLessonChoice();
  const b=nextBChoice(alloc.subjectB);
  const bMinutes=(b.mode==='compound'||b.mode==='securityMock')?Math.min(20,alloc.subjectB):alloc.subjectB;
  const lessonMinutes=alloc.lesson+Math.max(0,alloc.subjectB-bMinutes);
  const weak=weakestSkill();
  const days=examDaysRemaining();
  const finalPhase=days!=null&&days<=14;

  const rxReady=window.FEQUEST_RX_READY===true;
  const rx=rxReady?recommendedPrescription():{kind:'knowledge',cat:lesson.skill,reason:'データ不足'};
  const rxMeta=rxReady?prescriptionMeta(rx):{icon:'📘',title:lesson.title,desc:'未完了教材を優先'};
  const useRx=rxReady && rx.kind!=='knowledge';

  let learnTask;
  if(lesson.complete){
    const focus=shortFinalFocusRecommendation();
    learnTask={
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:lessonMinutes,focus
    };
  }else if(useRx){
    learnTask={
      type:'prescription',icon:rxMeta.icon,bg:'blue',
      title:rxMeta.title,desc:`原因「${rx.reason}」に合わせて自動処方`,
      minutes:lessonMinutes,rx
    };
  }else{
    learnTask={
      type:'lesson',icon:'📘',bg:'blue',
      title:lesson.title,desc:`${lesson.skill}・未完了教材を優先`,
      minutes:lessonMinutes,lessonId:lesson.id
    };
  }

  return [
    {
      type:'review',icon:'🧠',bg:'green',
      title:'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`復習期限の問題 ${due}問を優先`:`今日の復習期限はなし。「${weak}」を補強`,
      minutes:alloc.review
    },
    learnTask,
    {
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`プログラムトレース：${b.title}`:b.mode==='security'?`セキュリティ：${b.title}`:b.mode==='compound'?`複合演習：${b.title}`:b.mode==='securityMock'?b.title:`実戦：${b.title}`,
      desc:b.mode==='trace'?'科目B アルゴリズム':b.mode==='security'?'科目B 情報セキュリティ':b.mode==='compound'?'科目B アルゴリズム・20分実戦':b.mode==='securityMock'?'科目B セキュリティ・20分実戦':'科目B 実戦',
      minutes:bMinutes,bmode:b.mode,bid:b.id
    },
    {
      type:'boss',icon:'👑',bg:'yellow',
      title:finalPhase?'直前総合チェック':'今日の総合チェック',
      desc:finalPhase?'判断3問＋適用2問・分野を散らして5問':'全分野から5問・仕上げチェック',
      minutes:alloc.boss
    }
  ];
}
function renderDailyPlan(){
  const root=document.getElementById('dailyTaskList');
  if(!root) return;
  const rec=getDailyRecord();
  const tasks=ensureTodayPlanSnapshot();
  const total=Number(rec.targetMinutes)||tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0)||effectiveStudyMinutes();
  const doneTasks=tasks.filter(t=>dailyTaskDone(rec,t));
  const doneMinutes=doneTasks.reduce((s,t)=>s+t.minutes,0);
  const pct=Math.min(100,Math.round(doneMinutes/total*100));

  document.getElementById('dailyProgressBar').style.width=pct+'%';
  document.getElementById('dailyProgressLabel').textContent=`${doneMinutes} / ${total}分`;
  document.getElementById('dailyDoneLabel').textContent=`${doneTasks.length} / ${tasks.length} 完了`;
  const pace=examPaceStatus();
  document.getElementById('todayPlanMeta').textContent=pace.hasExam&&!pace.expired
    ? `${pace.phase.name}・今日${total}分・復習待ち${reviewWorkloadCount()}件・弱点「${weakestSkill()}」`
    : `標準${total}分・復習待ち${reviewWorkloadCount()}件・弱点「${weakestSkill()}」`;
  const ready=calcReadiness();
  document.getElementById('homeReadiness').textContent=ready+'%';

  root.innerHTML='';
  tasks.forEach(t=>{
    const done=dailyTaskDone(rec,t);
    const d=document.createElement('div');
    d.className='daily-task'+(done?' done':'');
    d.innerHTML=`
      <div class="daily-task-icon ${t.bg}">${t.icon}</div>
      <div>
        <div class="daily-task-title">${learningHtml(t.title)}</div>
        <div class="daily-task-desc">${escapeHtml(t.desc)}</div>
      </div>
      <div class="daily-task-side">
        <div class="daily-task-time">${t.minutes}分</div>
        <button class="daily-task-btn">${done?'もう一度':'開始'}</button>
      </div>`;
    d.querySelector('button').onclick=()=>launchDailyTask(t);
    root.appendChild(d);
  });

  const resume=document.getElementById('todayResumeBtn');
  if(resume){
    const nextTask=tasks.find(t=>!dailyTaskDone(rec,t));
    if(nextTask){
      resume.disabled=false;
      resume.textContent=doneTasks.length?'続きから再開 →':'今日の学習を始める →';
      resume.onclick=()=>launchDailyTask(nextTask);
    }else{
      resume.disabled=true;
      resume.textContent='今日の学習は完了しました ✓';
      resume.onclick=null;
    }
  }
  const rightProgress=document.getElementById('rightDailyProgress'),rightNext=document.getElementById('rightDailyNext'),rightAction=document.getElementById('rightDailyAction');
  const nextTask=tasks.find(t=>!dailyTaskDone(rec,t));
  if(rightProgress)rightProgress.textContent=`${doneTasks.length}/${tasks.length}完了・${doneMinutes}/${total}分`;
  if(rightNext)rightNext.textContent=nextTask?`次は「${nextTask.title}」・目安${nextTask.minutes}分`:'今日の計画は完了しています。';
  if(rightAction){rightAction.disabled=!nextTask;rightAction.textContent=nextTask?'続きから再開 →':'今日の学習は完了 ✓';rightAction.onclick=nextTask?()=>launchDailyTask(nextTask):null;}
}

function launchDailyTask(t){
  if(t.type==='warmup'){
    showScreen('problems');
    startQuiz('warmup');
    return;
  }
  if(t.type==='taperReview'){
    showScreen('problems');
    startQuiz('taperreview');
    return;
  }
  if(t.type==='review'){
    const j=actionableReviewJourneys()[0];
    if(j){
      startJourneyAction(j.id);
    }else{
      showScreen('problems');
      startQuiz('review');
    }
    return;
  }
  if(t.type==='lesson'){
    startLesson(t.lessonId);
    return;
  }
  if(t.type==='prescription'){
    if(t.rx?.kind==='knowledge') startLesson(pickLessonForSkill(t.rx.cat));
    else{
      showScreen('problems');
      startQuiz(rxMode(t.rx));
    }
    return;
  }
  if(t.type==='finalFocus'){
    launchFinalFocus(t.focus);
    return;
  }
  if(t.type==='subjectB'){
    showScreen('trace');
    if(t.bmode==='trace'){
      setBMode('trace');
      if(t.bid) startBExercise(t.bid);
    }else if(t.bmode==='security'){
      setBMode('security');
      if(t.bid) startSecurityScenario(t.bid);
    }else if(t.bmode==='compound'){
      setBMode('mock');
      startCompoundChallenge();
    }else if(t.bmode==='securityMock'){
      setBMode('security');
      startSecurityMock();
    }else{
      setBMode('mock');
    }
    return;
  }
  if(t.type==='boss'){
    showScreen('problems');
    startQuiz('boss');
  }
}

// Mark planner tasks when the corresponding real activity is completed.
// Wrap existing completion functions rather than duplicating their learning logic.
const _completeLessonV65=completeLesson;
completeLesson=function(){
  const lessonBefore=activeLesson;
  const reviewBefore=activeReviewJourneyId?journeyFor(activeReviewJourneyId):null;
  const isReviewLesson=!!reviewBefore&&reviewBefore.stage==='relearn'&&reviewBefore.lessonId===lessonBefore;
  const isCoreLesson=!!LESSONS[lessonBefore]?.core;
  _completeLessonV65();

  // 科目Aコアは「教材を読む→テーマ演習を終える」までを今日の学習1枠とする。
  // 復習ルート内の教材読み直しは新規学習枠として数えない。
  if(!isReviewLesson&&!isCoreLesson)markDailyTask('lesson',{lessonId:lessonBefore});
};

const _finishBV65=finishBExercise;
finishBExercise=function(){
  const idBefore=currentB?.id||null;
  _finishBV65();
  markDailyTask('subjectB',{mode:'trace',id:idBefore});
};

const _finishSecV65=finishSecurityScenario;
finishSecurityScenario=function(){
  const idBefore=currentSec?.id||null;
  _finishSecV65();
  markDailyTask('subjectB',{mode:'security',id:idBefore});
};

// Quiz completion must match the actual task route.
const _finishQuizSessionV65=finishQuizSession;
finishQuizSession=function(){
  const modeBefore=quizMode;
  _finishQuizSessionV65();

  // 通常復習と復習ルートは、どちらも今日の「記憶の復習」枠。
  if(modeBefore==='review'||String(modeBefore).startsWith('journey:'))markDailyTask('review');
  if(modeBefore==='taperreview')markDailyTask('taperReview');
  if(modeBefore==='warmup')markDailyTask('warmup');

  // 科目Aコア教材は、そのテーマの演習を最後まで終えて初めて今日の学習枠を完了。
  if(String(modeBefore).startsWith('coretopic:')){
    markDailyTask('lesson',{lessonId:String(modeBefore).slice(10)});
  }

  if(String(modeBefore).startsWith('corechapter:')||String(modeBefore).startsWith('cogcat:')||String(modeBefore).startsWith('coretopic:')){
    markDailyTask('finalFocus');
  }

  if(modeBefore==='boss') markDailyTask('boss');
  if(String(modeBefore).startsWith('rx:')) markDailyTask('prescription',{mode:modeBefore});
};


// v95: 章末統合演習の成績をMASTER判定用に永続化する。
const _finishQuizSessionV95=finishQuizSession;
finishQuizSession=function(){
  const modeBefore=quizMode;
  const rateBefore=quizItems.length?Math.round(quizCorrectCount/quizItems.length*100):0;
  _finishQuizSessionV95();
  if(String(modeBefore).startsWith('corechapter:')){
    const ch=Number(String(modeBefore).slice(12));
    if(ch>=1&&ch<=21){
      recordChapterIntegrationResult(ch,rateBefore);
      saveProfile();
      renderCoreCourseMap(document.getElementById('coreCourseSearch')?.value||'');
    }
  }
};

// Subject B's later stages are also valid completions of today's Subject B slot.
const _finishBFinalV65=finishBFinal;
finishBFinal=function(timeUp=false){
  const hadItems=!!bFinalItems.length;
  _finishBFinalV65(timeUp);
  if(hadItems)markDailyTask('subjectB',{mode:'final'});
};
const _finishBMiniMockV65=finishBMiniMock;
finishBMiniMock=function(timeUp=false){
  const hadItems=!!bMockItems.length;
  _finishBMiniMockV65(timeUp);
  if(hadItems)markDailyTask('subjectB',{mode:'mock'});
};

// v82: 20分の複合演習・セキュリティミニ模試も、完了時だけ今日の科目B枠を完了扱いにする。
const _finishCompoundV82=finishCompoundChallenge;
finishCompoundChallenge=function(timeUp=false){
  const hadSet=!!bCompoundSet;
  _finishCompoundV82(timeUp);
  if(hadSet)markDailyTask('subjectB',{mode:'compound'});
};
const _finishSecurityMockV82=finishSecurityMock;
finishSecurityMock=function(timeUp=false){
  const hadItems=!!secMockItems.length;
  _finishSecurityMockV82(timeUp);
  if(hadItems)markDailyTask('subjectB',{mode:'securityMock'});
};

function roadmapData(){
  const techIds=CORE_A_CURRICULUM.filter(t=>t.chapter<=13).map(t=>t.id);
  const businessIds=CORE_A_CURRICULUM.filter(t=>t.chapter>=14).map(t=>t.id);
  const aTech=lessonCompletionAverage(techIds);
  const aBusiness=lessonCompletionAverage(businessIds);
  const bAlgo=objectCompletion(profile.bProgress,B_EXERCISES.length);
  const bSec=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
  const c=readinessComponents();
  const practice=Math.round((c.aMock+c.bExam)/2);
  return [
    {icon:'📘',title:'ステップ 1　科目A テクノロジ',desc:`第1〜13章・${techIds.length}テーマ`,pct:aTech},
    {icon:'📊',title:'ステップ 2　科目A マネジメント・ストラテジ',desc:`第14〜21章・${businessIds.length}テーマ`,pct:aBusiness},
    {icon:'💻',title:'ステップ 3　科目B アルゴリズム',desc:'20演習を基礎→標準→応用の順にトレース',pct:bAlgo},
    {icon:'🛡️',title:'ステップ 4　科目B セキュリティ',desc:'15ケースで状況判断',pct:bSec},
    {icon:'🏁',title:'ステップ 5　総合実戦',desc:'科目Aフル模試＋科目B総合実戦の直近成績',pct:practice}
  ];
}

