function examAreaProgress(area){
  if(area.special==='b'){
    const a=objectCompletion(profile.bProgress,B_EXERCISES.length);
    const s=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
    return Math.round((a+s)/2);
  }
  const valid=(area.ids||[]).filter(id=>LESSONS[id]);
  if(!valid.length) return 0;
  return Math.round(valid.reduce((sum,id)=>sum+(profile.lessonProgress?.[id]||0),0)/valid.length);
}
function renderCoverage(){
  const root=document.getElementById('coverageGrid');
  if(!root) return;
  root.innerHTML='';
  const vals=[];
  EXAM_AREA_COVERAGE.forEach(area=>{
    const pct=examAreaProgress(area); vals.push(pct);
    const d=document.createElement('div');
    d.className='coverage-chapter';
    d.innerHTML=`<div class="coverage-ch-num" style="font-size:20px">${area.icon}</div>
      <div><div class="coverage-ch-title">${area.title}</div><div class="coverage-ch-sub">${area.special==='b'?'トレース / セキュリティ演習':'対応テーマ '+(area.ids||[]).length+'本'}</div>
      <div class="progress" style="height:8px;margin-top:7px"><div style="width:${pct}%"></div></div></div>
      <div class="coverage-ch-pct">${pct}%</div>`;
    root.appendChild(d);
  });
  const overall=Math.round(vals.reduce((a,b)=>a+b,0)/Math.max(1,vals.length));
  document.getElementById('coverageOverall').textContent=overall+'%';
}

