let mockItems=[];
let mockAnswers=[];
let mockFlags=[];
let mockIndex=0;
let mockMode='full';
let mockSeconds=0;
let mockInitialSeconds=0;
let mockTimerHandle=null;
let mockStartedAt=null;
let mockLastMode='full';
let mockQuestionSeconds=[];
let mockQuestionEnteredAt=null;
let lastMockAttempt=null;
