// ===== v15: deep weakness analytics =====
const WEAK_CATEGORIES=['基礎理論','コンピュータ','データベース','ネットワーク','セキュリティ','アルゴリズム','マネジメント','ストラテジ'];

function weakQuestionIdsForCat(cat){
  return QUESTION_BANK.filter(q=>q.cat===cat).map(q=>q.id);
}
function allRecentMockDetails(limit=6){
  const rows=[];
  (profile.mockHistory||[]).slice(0,limit).forEach(h=>{
    (h.details||[]).forEach(d=>rows.push({...d,examDate:h.date,mode:h.mode}));
  });
  return rows;
}
function reasonForQuestion(id){
  return profile.mockMistakeStats?.[id]?.lastReason || profile.qStats?.[id]?.lastReason || null;
}
function categoryAnalytics(cat){
  ensureQuestionProfile();
  const ids=new Set(weakQuestionIdsForCat(cat));
  let attempts=0,correct=0;
  ids.forEach(id=>{
    const st=profile.qStats?.[id];
    if(st){attempts+=st.attempts||0;correct+=st.correct||0;}
  });
  const cognitive=categoryCognitiveEvidence(cat);
  const accuracy=attempts?Math.round(correct/attempts*100):cognitive.score;

  const mockRows=allRecentMockDetails().filter(d=>ids.has(d.id));
  const mockWrong=mockRows.filter(d=>d.answerIndex===null || d.answerIndex!==d.correctIndex).length;
  const timed=mockRows.filter(d=>(d.seconds||0)>0);
  const avgSec=timed.length?Math.round(timed.reduce((s,d)=>s+(d.seconds||0),0)/timed.length):0;

  const reasons={};
  ids.forEach(id=>{
    const r=reasonForQuestion(id);
    if(r) reasons[r]=(reasons[r]||0)+1;
  });
  const dominant=Object.entries(reasons).sort((a,b)=>b[1]-a[1])[0]?.[0]||'データ不足';

  let repeats=0;
  ids.forEach(id=>{
    const st=profile.qStats?.[id];
    const mistakes=Math.max(0,(st?.attempts||0)-(st?.correct||0));
    const mockMiss=profile.mockMistakeStats?.[id]?.misses||0;
    if(Math.max(mistakes,mockMiss)>=2) repeats++;
  });

  const mastery=cognitive.score;
  const masteryRisk=100-mastery;
  const accuracyRisk=100-accuracy;
  const mockRisk=Math.min(100,mockWrong*12);
  const timeRisk=avgSec?Math.min(100,Math.max(0,(avgSec-60)/1.2)):0;
  const repeatRisk=Math.min(100,repeats*20);
  const cognitiveRisk=100-(cognitive.weakest.score==null?50:cognitive.weakest.score);
  const priority=Math.round(clamp(
    masteryRisk*.34 + accuracyRisk*.18 + cognitiveRisk*.20 + mockRisk*.10 + timeRisk*.06 + repeatRisk*.12,
    0,100
  ));
  return {
    cat,mastery,attempts,accuracy,mockWrong,avgSec,dominant,repeats,priority,
    cognitive,weakestCognitive:cognitive.weakest.level,weakestCognitiveScore:cognitive.weakest.score
  };
}
function categoryAdvice(a){
  if(a.dominant==='知識不足') return '教材を1本やり直してから、この分野だけ10問解くのがおすすめです。';
  if(a.dominant==='計算ミス') return '途中式を省略せず、数値問題をゆっくり解く練習を優先しましょう。';
  if(a.dominant==='読み違い') return '「適切／不適切」「以上／未満」など条件語へ印を付ける練習が有効です。';
  if(a.dominant==='2択で迷った') return '似た用語の違いを比較表で整理し、根拠を言葉にして選ぶ練習が有効です。';
  if(a.dominant==='時間不足' || a.avgSec>100) return '正解できる問題でも時間を使いすぎています。90秒を目安に一度判断する練習を。';
  if(a.attempts===0) return '演習データが少ないので、まずこの分野を10問解いて実力を測りましょう。';
  if(a.weakestCognitive==='判断') return '判断問題が弱めです。条件を複数拾い、計算・比較・優先順位まで根拠を持って選ぶ練習を。';
  if(a.weakestCognitive==='適用') return '適用問題が弱めです。用語を覚えるだけでなく、状況や目的へ当てはめる練習を増やしましょう。';
  if(a.weakestCognitive==='想起') return '基礎知識の取り出しが弱めです。用語・役割・定数を短時間で答えられるまで復習しましょう。';
  return '弱点問題を解き、間違えた問題を翌日の復習までつなげましょう。';
}
function sortedCategoryAnalytics(){
  return WEAK_CATEGORIES.map(categoryAnalytics).sort((a,b)=>b.priority-a.priority);
}
function aggregateWeakReasons(){
  const totals={'知識不足':0,'計算ミス':0,'読み違い':0,'2択で迷った':0,'時間不足':0,'用語を知らなかった':0,'計算方法を忘れた':0,'問題文を読み違えた':0,'ほぼ分からなかった':0};
  Object.values(profile.qStats||{}).forEach(st=>{
    if(st?.lastReason) totals[st.lastReason]=(totals[st.lastReason]||0)+1;
  });
  Object.values(profile.mockMistakeStats||{}).forEach(st=>{
    if(st?.lastReason) totals[st.lastReason]=(totals[st.lastReason]||0)+1;
  });
  // Normalize older v5 reason labels into the v14 labels.
  totals['知識不足'] += (totals['用語を知らなかった']||0) + (totals['ほぼ分からなかった']||0);
  totals['計算ミス'] += totals['計算方法を忘れた']||0;
  totals['読み違い'] += totals['問題文を読み違えた']||0;
  return ['知識不足','計算ミス','読み違い','2択で迷った','時間不足'].map(name=>[name,totals[name]||0]);
}
function repeatedWrongQuestions(){
  return trackedQuestionPool().map(q=>{
    const st=profile.qStats?.[q.id]||{};
    const ordinary=Math.max(0,(st.attempts||0)-(st.correct||0));
    const mock=profile.mockMistakeStats?.[q.id]?.misses||0;
    return {q,count:Math.max(ordinary,mock),reason:reasonForQuestion(q.id),due:st.due||''};
  }).filter(x=>x.count>=2).sort((a,b)=>b.count-a.count).slice(0,6);
}
function slowMockQuestions(){
  const byId={};
  allRecentMockDetails(5).forEach(d=>{
    if((d.seconds||0)<=0) return;
    if(!byId[d.id] || d.seconds>byId[d.id].seconds) byId[d.id]=d;
  });
  return Object.values(byId).map(d=>({d,q:originalQuestionById(d.id)}))
    .filter(x=>x.q).sort((a,b)=>b.d.seconds-a.d.seconds).slice(0,6);
}

