function validateQuestionSemanticContracts(){
  const byId=Object.fromEntries(QUESTION_BANK.map(q=>[q.id,q]));
  const errors=[];
  Object.entries(QUESTION_SEMANTIC_CONTRACTS).forEach(([id,expected])=>{
    const q=byId[id];
    if(!q){errors.push(`${id}: missing`);return;}
    if(q.options?.[q.a]!==expected)errors.push(`${id}: expected "${expected}"`);
  });
  QUESTION_BANK.forEach(q=>{
    if(QUESTION_CONTEXT_DEPENDENCY_PATTERNS.some(x=>String(q.q).includes(x))){
      errors.push(`${q.id}: context-dependent wording`);
    }
  });
  CORE_A_LINKED_QUESTIONS.forEach(q=>{
    const t=CORE_A_TOPIC_MAP[q.coreTopicId];
    if(!t)return;
    if(CORE_A_LINKED_PLAIN_CONTRACTS[q.id]!==q.options[q.a]){
      errors.push(`${q.id}: plain answer contract drift`);
    }
    if(q.distractorMode==='same-topic-comparison'){
      if(!CORE_A_COMPARISON_GUIDES[q.coreTopicId]){
        errors.push(`${q.id}: same-topic comparison guide missing`);
      }
      if(q.choiceExps?.[q.a]!==q.exp){
        errors.push(`${q.id}: same-topic comparison explanation drift`);
      }
    }else{
      if(q.angle==='application'&&q.exp!==t.example){
        errors.push(`${q.id}: application explanation binding drift`);
      }
      const explanationOverrideIds=new Set(['coreq_05_02_3','coreq_07_02_3']);
      if(q.angle==='discrimination'&&!explanationOverrideIds.has(q.id)&&q.exp!==t.pitfall){
        errors.push(`${q.id}: discrimination explanation binding drift`);
      }
    }
  });
  return {ok:errors.length===0,errors};
}


